import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-c1-001","clusterId":"C","werkstueckRef":"C.1.1","stufe":1,"question":"Ein Freund sagt: „Wenn sich alle Galaxien voneinander entfernen, muss es irgendwo einen Mittelpunkt geben, wo der Urknall stattfand. Dort müsste man hinfliegen können.“ Welche Antwort trifft den Denkfehler am besten?","options":["Der Schluss ist richtig, denn eine gemeinsame Fluchtbewegung ist ohne einen zentralen Ausgangspunkt im Raum nicht zu erklären. Dieser liegt wahrscheinlich nur außerhalb des Bereichs, den wir beobachten können.","Der Schluss ist falsch, denn der Raum selbst dehnt sich überall zugleich aus. Einen Mittelpunkt, von dem alles wegfliegt und zu dem man fliegen könnte, gibt es nicht.","Der Schluss ist nur teilweise richtig: Es gab einen Mittelpunkt, doch durch die ständige Ausdehnung ist er inzwischen so weit entfernt, dass wir ihn mit keinem Teleskop mehr erkennen können.","Der Schluss ist falsch, denn die Galaxien entfernen sich nicht wirklich voneinander. Es handelt sich um den langsamen Zerfall eines bereits unendlich großen, kalten Raumes in einzelne Galaxien."],"correctIndex":1,"explanation":"Der Fehlschluss überträgt ein Alltagsbild auf den Kosmos: Bei einer Explosion im Raum fliegen Teile von einem Ort weg, und es gibt einen Mittelpunkt. Der Urknall war aber keine Explosion in einen bestehenden Raum hinein, sondern die Entstehung und Ausdehnung des Raumes selbst, nicht an einem Punkt, sondern überall zugleich. Dazu passt die Beobachtung: Je weiter eine Galaxie entfernt ist, desto schneller entfernt sie sich. Einen Mittelpunkt, von dem alles wegfliegt, gibt es nicht. Daher gibt es auch keinen Ort, zu dem man fliegen könnte. Gestützt wird das Modell von zwei unabhängigen Beobachtungen: der Expansion der Galaxien und der kosmischen Mikrowellen-Hintergrundstrahlung, die aus allen Richtungen des Himmels nahezu gleichmäßig messbar ist.","coreRule":"⚡ Wer aus „alles entfernt sich voneinander“ auf einen Mittelpunkt schließt, überträgt ein Alltagsbild (Explosion im Raum) auf einen Vorgang, bei dem der Raum selbst sich ausdehnt, überall zugleich.","quote":"Es war die Entstehung und Ausdehnung des Raumes selbst -- nicht an einem Punkt, sondern überall zugleich.","quoteLabel":"Merksatz:","beleg":"Werkstück C.1.1 (Kontext & Tiefe, „Keine Explosion im Raum“)","status":"entwurf","scenario":"In einer Diskussion über die Ausdehnung des Universums beobachtet ihr: Galaxien entfernen sich voneinander, und zwar umso schneller, je weiter sie entfernt sind. Dein Freund schließt daraus auf einen zentralen Explosionsort.","kurz":"Der Urknall war keine Explosion an einem Ort im Raum, sondern die Ausdehnung des Raumes selbst, überall zugleich. Das Alltagsbild der Explosion verführt zum Schluss auf einen Mittelpunkt, zu dem man fliegen könnte. Den gibt es nicht.","prueffrage":"Wie sähe die Fluchtbewegung für Beobachter in einer ganz anderen Galaxie aus, und was würde das über einen Mittelpunkt verraten?","rueckmeldung":[{"option":0,"text":"Eine gemeinsame Fluchtbewegung scheint einen Ausgangspunkt zu verlangen. Doch dehnt sich der Raum überall zugleich, sieht jeder Beobachter alle Galaxien von sich wegfliegen, umso schneller, je weiter sie weg sind; ein Mittelpunkt ist nicht nötig."},{"option":2,"text":"Dass sich die Abstände durch die Ausdehnung vergrößern, stimmt. Einen Mittelpunkt gab es aber nie, auch keinen versteckten: Der Urknall ereignete sich nicht an einem Ort, sondern überall zugleich."},{"option":3,"text":"Dass der Schluss auf ein Zentrum falsch ist, trifft zu. Doch die Galaxien entfernen sich beobachtbar voneinander, und für einen Zerfall eines kalten Raums in Galaxien gibt es keinen Beleg: Ein Fehler wird hier durch eine unbelegte Behauptung ersetzt."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Scientific American (1999): „According to the big bang, space itself is expanding …“ (Antworten von J. R. Primack und T. Takahashi)","oeffentlich":true,"url":"https://www.scientificamerican.com/article/according-to-the-big-bang-1999-10-21","abruf":"2026-10-12"},{"typ":"url","kurz":"ESA: Planck and the cosmic microwave background","oeffentlich":true,"url":"https://www.esa.int/Science_Exploration/Space_Science/Planck/Planck_and_the_cosmic_microwave_background","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hubble, E. (1929): A Relation between Distance and Radial Velocity among Extra-Galactic Nebulae. PNAS 15(3), 168–173 (aus Landkarte-Fn gl-c-hubble-lemaitre)","oeffentlich":false,"doi":"10.1073/pnas.15.3.168"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"04347d82f8aad650"}},{"id":"qx-c1-002","clusterId":"C","werkstueckRef":"C.1.1","stufe":2,"question":"Der Heiler soll nennen, über welche der vier fundamentalen Kräfte (Gravitation, Elektromagnetismus, starke und schwache Kernkraft) seine „Energie“ übertragen werden soll. Er kann keine nennen, die auf seine Beschreibung passt. Was folgt daraus für seine Behauptung?","scenario":"Bei einem Heilerabend sagt jemand, er lenke „kosmische Heilenergie“ in deine Hände.","options":["Seine „Energie“ ist mit hoher Wahrscheinlichkeit keine physikalische Größe, sondern eine bildhafte Redeweise; er müsste für eine neue Kraft außergewöhnliche Belege liefern.","Seine Behauptung enthält einen Zirkelschluss, weil er die Energie mit ihrer Heilwirkung begründet und die Heilwirkung mit der Energie; die Kräftefrage trifft das nicht.","Seine Behauptung lässt sich erst bewerten, wenn ein Doppelblindversuch zeigt, ob seine Wirkung messbar ist; aus der Antwort auf die Kräftefrage folgt dafür noch nichts.","Seine Behauptung stützt sich auf Erfahrungsberichte seiner Zuhörer; viele übereinstimmende Berichte wiegen schwerer als die Frage nach der Kraft, über die sie wirkt."],"correctIndex":0,"explanation":"Jede bisher beobachtete Wechselwirkung lässt sich auf die vier bekannten Grundkräfte zurückführen. Wer behauptet, eine „Energie“ zu lenken, behauptet etwas Physikalisches und muss sagen können, über welche dieser Kräfte sie übertragen werden soll; kann er das nicht, ist das Wort wahrscheinlich nur bildhaft gemeint. Eine neue, fünfte Kraft wäre denkbar, doch Präzisionsexperimente suchen gezielt danach und lassen ihr bislang nur winzige Spielräume; wer sie behauptet, muss außergewöhnliche Belege liefern. Die anderen Gedanken klingen vernünftig, passen aber nicht: Ein Zirkelschluss liegt nicht vor, denn der Heiler begründet seine Energie hier gar nicht mit ihrer Wirkung. Ein Doppelblindversuch wäre für eine behauptete Wirkung sinnvoll, doch schon die unbeantwortete Frage nach der Kraft sagt etwas über die Behauptung aus. Und Berichte vieler Zuhörer ersetzen keine Auskunft darüber, auf welchem Weg die „Energie“ übertragen werden soll.","coreRule":"⚡ Nenne die Kraft: Passt keine der vier fundamentalen Kräfte, ist „Energie“ eine Metapher und keine Physik – und wer eine neue Kraft behauptet, trägt die Beweislast.","beleg":"Werkstück C.1.1 (Anwendung & Relevanz, „Gegen die Esoterik & ‚Energieheilung‘“, mit Verweis auf D.4.1; Kontext & Tiefe, Absatz zur ‚fünften Kraft‘); Fn. gl-c-dunkle-energie (Adelberger u. a. 2003, Suche nach einer fünften Kraft)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer eine „Energie“ lenken will, behauptet etwas Physikalisches und muss sagen können, über welche bekannte Kraft sie wirkt. Kann er das nicht, ist das Wort wahrscheinlich nur bildhaft gemeint; für eine neue Kraft bräuchte er außergewöhnliche Belege.","prueffrage":"Was würde sich an Messgeräten ändern, wenn tatsächlich etwas in deine Hände fließt?","rueckmeldung":[{"option":1,"text":"Bei Heilerbehauptungen liegt die Suche nach einem Kreis im Argument nahe. Hier begründet der Heiler seine Energie aber gar nicht mit ihrer Wirkung, ein Zirkelschluss liegt also nicht vor. Die Kräftefrage zielt auf den Übertragungsweg, nicht auf die Begründung."},{"option":2,"text":"Ein Doppelblindversuch ist für eine behauptete Wirkung sinnvoll und wäre ein guter nächster Schritt. Aber schon die unbeantwortete Frage nach der Kraft sagt etwas über die Behauptung aus: Das Wort „Energie“ ist dann wahrscheinlich nur bildhaft gemeint."},{"option":3,"text":"Viele übereinstimmende Berichte beeindrucken, doch sie sagen nichts darüber, auf welchem Weg die „Energie“ übertragen werden soll. Dazu fehlt dem Heiler die Auskunft, und Berichte können sie nicht ersetzen, auch wenn es viele sind."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"CERN: The Standard Model","oeffentlich":true,"url":"https://home.cern/science/physics/standard-model","abruf":"2026-10-12"},{"typ":"url","kurz":"Adelberger, E. G.; Heckel, B. R.; Nelson, A. E. (2003): Tests of the Gravitational Inverse-Square Law. Ann. Rev. Nucl. Part. Sci. 53, 77–121 (arXiv-Fassung)","oeffentlich":true,"url":"https://arxiv.org/abs/hep-ph/0307284","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6240e91bff933f87"}},{"id":"qx-c1-003","clusterId":"C","werkstueckRef":"C.1.1","stufe":3,"question":"Welche der folgenden Äußerungen ist ein Fehlschluss, der aus einer offenen Frage einen Beleg gegen ein gut gestütztes Modell machen will?","options":["„Die Physik kann nicht sagen, was vor dem Urknall war. Also ist die ganze Theorie widerlegt, und eine übernatürliche Erklärung muss an ihre Stelle treten.“","„Ob hinter dem Anfang des Universums ein Sinn oder ein erster Beweger steht, ist eine Frage für Philosophie und Religion und lässt sich nicht im Experiment prüfen.“","„Was vor dem Urknall war, ist offen. In extremen Zuständen wie einer Singularität könnten Regeln gelten, die ganz anders sind als in unserem Alltag.“","„Die Natur der Dunklen Energie ist noch nicht verstanden. Ihr Zahlenwert ist aber präzise vermessen, und die Forschung arbeitet weiter daran.“"],"correctIndex":0,"explanation":"Der Satz schließt von einer offenen Frage auf die Falschheit des gesamten Modells. Das ist ein Argument aus Unwissenheit: „Das weiß man nicht, also ist das übrige Wissen hinfällig und meine Erklärung gewinnt.“ Dieser Schluss trägt nicht. Ein Modell wird durch seine Belege getragen, bei der Urknall-Theorie vor allem durch die beobachtete Expansion der Galaxien und die kosmische Hintergrundstrahlung. Eine ungeklärte Frage am Rand ändert an diesen Belegen nichts. Zudem wäre die Ersatzerklärung dadurch nicht gestützt, denn sie müsste selbst Belege liefern. Die anderen Sätze sind unproblematisch. Philosophische oder religiöse Fragen nach einem Sinn oder ersten Beweger sind legitim, solange sie nicht als wissenschaftliche Argumente getarnt werden, um belegte Modelle zu leugnen. Auch ehrlich benannte Lücken sind kein Fehler, solange sie als Lücken behandelt werden und nicht als Freibrief.","coreRule":"⚡ Eine offene Frage am Rand eines Modells ist kein Beleg gegen das Modell. Wer das Modell kippen will, muss zeigen, dass es die gut belegten Beobachtungen schlechter erklärt, nicht nur auf eine Lücke zeigen.","beleg":"Werkstück C.1.1 (Der Kipppunkt; Red Flags, Argument aus Unwissenheit)","status":"entwurf","scenario":"In einer Diskussion über den Ursprung des Universums fallen vier Sätze. Es geht um die Frage, wie man mit offenen Fragen eines wissenschaftlichen Modells umgehen sollte.","kurz":"Eine offene Frage am Rand widerlegt kein Modell, das auf Belegen wie der Expansion der Galaxien und der Hintergrundstrahlung ruht. Der Fehler: aus „das weiß man nicht“ wird „also stimmt meine Erklärung“, die selbst Belege bräuchte.","prueffrage":"Welche Beobachtungen stützen die Theorie, und ändert sich an ihnen etwas, nur weil eine Frage offen ist?","rueckmeldung":[{"option":1,"text":"Hier wird eine Frage nach Sinn oder erstem Beweger gestellt, die sich tatsächlich nicht im Experiment prüfen lässt. Das Modell wird dabei nicht angegriffen und nichts an seine Stelle gesetzt, deshalb liegt kein Fehlschluss vor."},{"option":2,"text":"Die Lücke wird als offen benannt, und die Vermutung über andere Regeln bleibt vorsichtig („könnten“). Weder wird das Modell widerlegt noch eine Ersatzerklärung durchgesetzt, eine ehrlich benannte Lücke ist hier kein Fehler."},{"option":3,"text":"Auch dieser Satz nennt eine Wissenslücke, hält aber zugleich fest, was gesichert ist, nämlich den präzise vermessenen Zahlenwert. Er behandelt die Lücke als Aufgabe der Forschung und nicht als Grund, das Modell zu verwerfen."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (2015, überarb. 2024), Abschn. 2.4","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"},{"typ":"url","kurz":"ESA: Planck and the cosmic microwave background","oeffentlich":true,"url":"https://www.esa.int/Science_Exploration/Space_Science/Planck/Planck_and_the_cosmic_microwave_background","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hubble, E. (1929): A Relation between Distance and Radial Velocity among Extra-Galactic Nebulae. PNAS 15(3), 168–173","oeffentlich":false,"doi":"10.1073/pnas.15.3.168"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4864c6c94a3c7065"}},{"id":"qx-c1-004","clusterId":"C","werkstueckRef":"C.1.1","stufe":4,"question":"Welche Antwort deckt den Denkfehler in dieser Rechtfertigung am genauesten auf?","scenario":"Ein Esoteriker kontert: „Selbst die Physik gibt zu, dass sie Dunkle Energie nicht versteht – dann darf ich auch meine unsichtbare Lebensenergie annehmen.“","options":["Er verallgemeinert voreilig: Weil die Physik bei einer Frage offen ist, hält er alle ihre Aussagen für unsicher, obwohl die übrigen Ergebnisse davon unberührt bleiben.","Er beruft sich auf die Mehrheit: Weil viele Menschen an eine Lebensenergie glauben, gilt sie als gesichert, und die Frage nach der Messbarkeit tritt dahinter zurück.","Die Dunkle Energie wird gezielt beobachtet und gemessen, die Lücke ist also begrenzt und eindeutig beschrieben; eine bloß behauptete Lebensenergie hat nichts Vergleichbares.","Er argumentiert im Kreis: Er begründet die Lebensenergie mit der Dunklen Energie und die Dunkle Energie mit der Lebensenergie, sodass keine von beiden etwas stützt."],"correctIndex":2,"explanation":"Der Schluss „Die Physik versteht etwas nicht, also darf ich irgendetwas Unsichtbares annehmen“ macht aus einer Wissenslücke einen Freibrief. Die Dunkle Energie ist aber nicht aus der Luft gegriffen: Supernova-Messungen zeigen eine beschleunigte Ausdehnung des Universums (Riess u. a. 1998; Perlmutter u. a. 1999), und ihr Anteil am Universum ist vermessen, nach den Planck-Daten von 2018 rund 68 %. Ihre Natur ist keineswegs verstanden, die Lücke selbst aber genau umrissen und überprüfbar; einer „Lebensenergie“ ohne Messgröße und ohne beobachtbaren Effekt fehlt genau das. Die Beweislast liegt bei dem, der eine Behauptung aufstellt, nicht bei den Kritikern. Die anderen Einwände sind für sich bedenkenswert, treffen den Esoteriker aber nicht: Er hält nicht die ganze Physik für unsicher, sondern nutzt eine einzelne offene Frage als Vorbild. Er beruft sich auch auf keine Mehrheit. Und er begründet nicht im Kreis, denn die Dunkle Energie stützt sich auf eigene Messungen und nicht auf seine Lebensenergie.","coreRule":"⚡ Eine Lücke im Wissen, die genau vermessen ist, trägt eine Hypothese; eine Lücke, die nur als Platz für eine Behauptung dient, trägt nichts.","beleg":"Werkstück C.1.1 (Kontext & Tiefe); Fn. gl-c-dunkle-energie (Riess u. a. 1998; Perlmutter u. a. 1999; Planck Collaboration 2020, A&A 641, A6)","status":"entwurf","kurz":"Eine Lücke im Wissen ist kein Freibrief für beliebige Annahmen. Die Dunkle Energie ist durch Messungen umrissen, auch wenn ihre Natur offen ist; für die „Lebensenergie“ gibt es keine Messgröße und keinen beobachtbaren Effekt.","prueffrage":"Was genau gibt die Physik zu, wenn sie sagt, sie verstehe die Dunkle Energie nicht?","rueckmeldung":[{"option":0,"text":"Eine offene Frage als Anlass zu nehmen, die ganze Physik anzuzweifeln, wäre voreilig. Der Esoteriker tut das aber gar nicht: Er stellt keine anderen Ergebnisse infrage, sondern nutzt eine einzelne Lücke als Vorbild für seine Annahme."},{"option":1,"text":"Mehrheitsglaube ist ein verbreiteter Fehlschluss, kommt hier aber nicht vor. Der Esoteriker beruft sich nicht darauf, wie viele Menschen an Lebensenergie glauben, sondern auf eine Lücke der Physik."},{"option":3,"text":"Ein Zirkelschluss liegt nicht vor, denn die Dunkle Energie stützt sich auf eigene Messungen und nicht auf die Lebensenergie. Er benutzt sie nur als Vergleich, in dem beide Begriffe unsichtbar und rätselhaft erscheinen."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Riess, A. G. u. a. (1998): Observational Evidence from Supernovae for an Accelerating Universe and a Cosmological Constant. AJ 116, 1009–1038","oeffentlich":true,"doi":"10.1086/300499","url":"https://arxiv.org/abs/astro-ph/9805201","abruf":"2026-10-12"},{"typ":"url","kurz":"Planck Collaboration (2020): Planck 2018 results. VI. Cosmological parameters. A&A 641, A6 (arXiv-Fassung)","oeffentlich":true,"url":"https://arxiv.org/abs/1807.06209","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"289192f96408f42a"}},{"id":"qx-c1-005","clusterId":"C","werkstueckRef":"C.1.2","stufe":1,"question":"Was ist an dem Schluss deiner Freundin fehlerhaft?","options":["Sie betrachtet nur das Zimmer. Das Aufräumen kostet Energie, und dabei entsteht anderswo Unordnung, sodass die Gesamtunordnung nicht sinkt.","Sie verwechselt Zeitfolge mit Ursache. Dass es nach dem Aufräumen ordentlicher ist, beweist nicht, dass ihr Aufräumen die Ordnung bewirkt hat.","Sie argumentiert im Kreis. Sie setzt voraus, dass Aufräumen die Unordnung senkt, und folgert daraus am Ende genau dasselbe wieder.","Sie vergisst die Zeit. Jedes Zimmer wird von selbst wieder unordentlicher, sodass ihre Ordnung nicht lange hält und der Schluss höchstens kurzzeitig gilt."],"correctIndex":0,"explanation":"Entropie misst, auf wie viele Arten ein System im Kleinen angeordnet sein kann; in einem abgeschlossenen System, das mit seiner Umgebung weder Energie noch Stoff austauscht, nimmt sie insgesamt nie ab. Lokale Ordnung entsteht nur unter Energieeinsatz, und dabei entsteht anderswo mehr Unordnung, etwa als Wärme aus Muskeln und Staubsauger. Gemessen daran zählt die Anordnung von Kleidung und Büchern thermodynamisch sogar verschwindend wenig; die Alltagsordnung dient hier nur als Bild. Der Schluss „Ordnung im Zimmer heißt weniger Unordnung insgesamt“ ist deshalb falsch. Die anderen Gedanken klingen vernünftig, treffen aber nicht den Kern: Zeitfolge und Ursache sind nicht verwechselt, denn das Aufräumen hat die Ordnung im Zimmer tatsächlich bewirkt. Dass ein Zimmer von selbst wieder unordentlich wird, ist richtig, ändert aber nichts an der Bilanz der Stunde, und selbst dauerhafte Ordnung im Zimmer ließe die Unordnung anderswo bestehen. Auch ein Zirkelschluss liegt nicht vor, denn ihre Folgerung geht von einer beobachteten Ordnung im Zimmer aus und nicht von ihrem Ergebnis.","coreRule":"⚡ Lokale Ordnung gibt es nur auf Kosten von mehr Unordnung anderswo: Rechne immer die ganze Bilanz, nicht nur das Zimmer.","quote":"","quoteLabel":"","beleg":"Werkstück C.1.2 (Das aufgeräumte Zimmer; Kontext & Tiefe, Erster und Zweiter Hauptsatz)","status":"entwurf","scenario":"Du räumst eine Stunde lang dein Zimmer auf: Kleidung gefaltet, Bücher sortiert, Boden gesaugt. Deine Freundin sagt: „Ich habe Ordnung geschaffen, also hat die Unordnung im Universum abgenommen.“","kurz":"Der Schluss springt vom Zimmer auf das ganze Universum. Ordnung entsteht nur unter Energieeinsatz, und dabei entsteht anderswo mehr Unordnung, etwa als Wärme aus Muskeln und Staubsauger, sodass die Gesamtunordnung nicht sinkt.","prueffrage":"Was verbraucht der Staubsauger, und was gibt dein Körper während der Stunde Arbeit an die Luft ab?","rueckmeldung":[{"option":1,"text":"Dass es nach dem Aufräumen ordentlicher ist, könnte tatsächlich bloßes Nacheinander sein. Hier hat das Aufräumen die Ordnung im Zimmer aber wirklich bewirkt; fehlerhaft ist erst der Sprung vom Zimmer auf das ganze Universum."},{"option":2,"text":"Ein Zirkelschluss klingt plausibel, weil Aufräumen und weniger Unordnung eng zusammenhängen. Sie geht aber von der beobachteten Ordnung im Zimmer aus, und diese Beobachtung stimmt. Was nicht trägt, ist die Ausweitung auf das Universum."},{"option":3,"text":"Ein Zimmer wird von selbst wieder unordentlicher, das stimmt. An der Bilanz der Stunde ändert das nichts, und selbst bleibende Ordnung im Zimmer ließe die Unordnung anderswo bestehen. Der Kern ist die Reichweite des Schlusses, nicht seine Dauer."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ling, S. J.; Moebs, W.; Sanny, J. (2016): University Physics Vol. 2 (OpenStax), 4.7 Entropy on a Microscopic Scale","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/4-7-entropy-on-a-microscopic-scale","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax: University Physics Vol. 2, 3.3 First Law of Thermodynamics","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/3-3-first-law-of-thermodynamics","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d2cc02c2c9357c07"}},{"id":"qx-c1-006","clusterId":"C","werkstueckRef":"C.1.2","stufe":2,"question":"Welche Antwort prüft den Einwand richtig?","scenario":"In einer Diskussion sagt jemand: „Mein Kaffee kühlt im Zimmer ab, und dabei sinkt seine Entropie. Damit ist bewiesen, dass der Satz ‚Die Gesamtentropie nimmt nie ab' nicht stimmen kann.“ Das Zimmer ist ein abgeschlossenes System aus Kaffee und Raumluft.","options":["Der Einwand ist ein Fehlschluss, denn Kaffee und Raum tauschen Energie mit der Außenwelt aus, und diese Zufuhr von außen gleicht den Entropieverlust des Kaffees aus.","Der Einwand ist ein Fehlschluss, denn er betrachtet nur den Kaffee; der kühle Raum gewinnt mehr Entropie, als der Kaffee verliert, und die Summe beider steigt.","Der Einwand ist ein Fehlschluss, denn der Satz verlangt nur, dass die Gesamtenergie erhalten bleibt, und die bleibt beim Abkühlen des Kaffees unverändert.","Der Einwand ist ein Fehlschluss, denn der Satz gilt nur im Mittel; einzelne Abnahmen der Entropie kommen vor und widerlegen ihn deshalb nicht."],"correctIndex":1,"explanation":"Der Satz gilt für das abgeschlossene Gesamtsystem, nicht für jeden Teil einzeln. Der Einwand betrachtet nur den Kaffee und übersieht die Umgebung: Die Wärme verteilt sich, bis Tasse und Raum gleich warm sind, und dabei gewinnt der kühlere Raum mehr Entropie, als der Kaffee verliert. Das lässt sich nachrechnen: Gleichen sich zwei gleiche Stahlkörper (Wärmekapazität je 1800 J/K, rund 4 kg Stahl), die nur miteinander Wärme austauschen, von 400 K und 300 K auf je 350 K an, verliert der heiße rund 240 J/K Entropie, der kalte gewinnt rund 277 J/K, netto steigt die Entropie um rund 37 J/K. Die Wärme geht dabei nicht verloren, sondern verteilt sich als ungeordnete Bewegung der Luftteilchen. Dass ein System von außen Energie aufnehmen und dadurch Entropie senken kann, trifft hier nicht zu, denn Kaffee und Raum bilden zusammen ein abgeschlossenes System. Der Satz handelt von der Entropie und nicht von der Energie, deren Erhaltung ein eigener Grundsatz ist und nichts über die Richtung des Abkühlens sagt. Und Schwankungen, die den Satz im Mittel bestehen lassen, betreffen nur sehr kleine Systeme; das Abkühlen einer Tasse ist ein gerichteter Vorgang.","coreRule":"⚡ Lokal darf die Entropie sinken – solange sie in der Umgebung mehr zunimmt. Prüfe bei „Das widerspricht dem Gesetz“ immer, ob das ganze System betrachtet wurde.","beleg":"Werkstück C.1.2; Fn. gl-c-waermefluss (Ling/Moebs/Sanny 2016, Abschn. 4.6 Beispiel 4.5 und 4.7 Beispiel 4.9)","status":"entwurf","kurz":"Der Satz gilt für das abgeschlossene Gesamtsystem, nicht für jeden Teil einzeln: Der kühlere Raum gewinnt mehr Entropie, als der Kaffee verliert. Der Einwand betrachtet nur den Kaffee und übersieht die Umgebung.","prueffrage":"Wohin geht die Wärme, die der Kaffee abgibt, und wie verändert sich dabei die Raumluft?","rueckmeldung":[{"option":0,"text":"Dass ein System von außen Energie aufnehmen und so Entropie senken kann, gibt es tatsächlich. Hier aber bilden Kaffee und Raum zusammen ein abgeschlossenes System, es kommt nichts von außen hinzu."},{"option":2,"text":"Die Gesamtenergie bleibt beim Abkühlen tatsächlich erhalten. Der Satz handelt aber von der Entropie, nicht von der Energie. Ihre Erhaltung ist ein eigener Grundsatz und sagt nichts darüber, in welche Richtung sich der Kaffee abkühlt."},{"option":3,"text":"Dass Entropie in sehr kleinen Systemen kurzzeitig abnehmen kann, stimmt. Das betrifft aber keine Tasse Kaffee: Ihr Abkühlen ist ein gerichteter Vorgang und keine Schwankung, die der Satz im Mittel ausgleicht."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ling, S. J.; Moebs, W.; Sanny, J. (2016): University Physics Vol. 2 (OpenStax), 4.7, Beispiel 4.9","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/4-7-entropy-on-a-microscopic-scale","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"99ee55f9d8e00108"}},{"id":"qx-c1-007","clusterId":"C","werkstueckRef":"C.1.2","stufe":3,"question":"Ein Redner sagt: „Der menschliche Körper ist hochgeordnet. Das widerlegt den Zweiten Hauptsatz der Thermodynamik und beweist eine Lebenskraft.“ Welcher Denkfehler steckt in diesem Schluss?","options":["Er stützt sich auf bloße Autorität, denn dass ein Redner überzeugend auftritt, zeigt noch nicht, dass der Zweite Hauptsatz widerlegt ist oder dass es eine Lebenskraft gibt.","Er argumentiert im Kreis, denn er nimmt die Lebenskraft als Ursache der Ordnung an und folgert aus der Ordnung dann wieder die Lebenskraft als Beweis.","Er verallgemeinert voreilig, denn er schließt vom Körper des Menschen auf alle Lebewesen, obwohl Pflanzen und Pilze ganz anders gebaut sind und leben.","Er betrachtet nur den Körper und nicht die Umgebung, denn Lebewesen halten ihre Ordnung durch ständige Energieaufnahme und erhöhen dabei die Entropie ihrer Umgebung."],"correctIndex":3,"explanation":"Der Zweite Hauptsatz verlangt nur, dass die Gesamtentropie eines abgeschlossenen Systems nicht abnimmt. Ein Körper ist aber kein abgeschlossenes System: Er nimmt ständig Energie von außen auf (Nahrung) und gibt Wärme und Abfallprodukte an die Umgebung ab. Dadurch steigt die Entropie der Umgebung stärker, als die Entropie im Körper sinkt, sodass die Gesamtentropie nicht abnimmt. Lokale Ordnung ist also möglich, wenn sie mit Energie und Abwärme bezahlt wird; ein Widerspruch zum Hauptsatz entsteht nicht. Die anderen Einwände wären in anderen Fällen berechtigt, passen hier aber nicht: Der Redner beruft sich auf keine Autorität, sondern auf eine Beobachtung. Er argumentiert auch nicht im Kreis, und er spricht ausdrücklich vom menschlichen Körper und nicht von allen Lebewesen.","coreRule":"⚡ Ordnung in einem Teil ist kein Gegenbeweis zum Zweiten Hauptsatz: Prüfe immer das Gesamtsystem. Leben zahlt für lokale Ordnung mit Energie und Abwärme.","beleg":"Werkstück C.1.2 (Kontext & Tiefe, Absatz „Das Leben selbst, einschließlich unseres Körpers …“)","status":"entwurf","scenario":"","kurz":"Der Körper ist kein abgeschlossenes System: Er nimmt Energie auf und gibt Wärme ab, wodurch die Entropie der Umgebung stärker steigt, als sie im Körper sinkt. Wer nur den Körper ansieht, übersieht das und macht aus lokaler Ordnung einen Widerspruch.","prueffrage":"Was geschieht mit der Ordnung eines Körpers, der wochenlang nichts zu essen bekommt?","rueckmeldung":[{"option":0,"text":"Dass Autorität allein nichts beweist, stimmt allgemein. Der Redner stützt sich hier aber auf eine Beobachtung, den hochgeordneten Körper. Der Fehler liegt im Schluss daraus, nicht in der Person."},{"option":1,"text":"Zirkelschlüsse gibt es, aber hier nimmt der Redner die Lebenskraft nicht vorab als Ursache der Ordnung an. Er geht von der beobachteten Ordnung aus und folgert daraus zwei Dinge, die nicht daraus folgen."},{"option":2,"text":"Voreilige Verallgemeinerungen sind ein häufiger Fehler, und Pflanzen und Pilze sind tatsächlich anders gebaut. Der Redner spricht aber ausdrücklich nur vom menschlichen Körper. Der Fehler liegt daher nicht in der Reichweite der Aussage."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ling, S. J.; Moebs, W.; Sanny, J. (2016): University Physics Vol. 2 (OpenStax), 4.7 Entropy on a Microscopic Scale","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/4-7-entropy-on-a-microscopic-scale","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"30e8a548dc0afc39"}},{"id":"qx-c1-008","clusterId":"C","werkstueckRef":"C.1.2","stufe":4,"question":"Welche Überlegung prüft den Kern dieser Werbebehauptung am besten?","options":["Der Körper besitzt mit Leber und Nieren Organe, die Stoffe laufend abbauen und ausscheiden; der Anbieter müsste erklären, welche zusätzliche Leistung sein Saft darüber hinaus erbringt.","Der Anbieter verdient am Verkauf des Safts und hat Anlass zu übertreiben; ein solches finanzielles Interesse ist ein Grund, den Werbetext besonders kritisch zu lesen.","Man vergleicht den Preis mit dem anderer Säfte; ein deutlich höherer Preis bei ähnlichen Zutaten ist ein Warnzeichen, dass der Anbieter mehr verspricht, als er hält.","Man liest, was andere Käufer berichten; viele übereinstimmende Erfahrungsberichte zeigen, ob der Saft tatsächlich ausleitet und die Werbung hält, was sie verspricht."],"correctIndex":0,"explanation":"Die Behauptung unterstellt, der Körper werde „Schlacken“ allein nicht los. Abbau und Ausscheidung leisten aber laufend vor allem Leber und Nieren, deshalb müsste der Anbieter erklären, was sein Saft darüber hinaus bewirkt; hinzu kommt, dass „Schlacke“ kein medizinisch definierter Stoff ist und der Werbetext offenlässt, was sich ansammeln soll. Die anderen Überlegungen sind in vielen Fällen nützlich, treffen den Kern hier aber nicht: Das finanzielle Interesse des Anbieters ist ein Grund zur Vorsicht, sagt aber nichts darüber, ob die Behauptung stimmt. Auch der Preis zeigt nicht, ob der Körper wirklich auf Hilfe beim Ausleiten angewiesen ist. Und Erfahrungsberichte spiegeln oft Erwartung und Zufall; sie ersetzen keine Erklärung, wie der Saft wirken soll.","coreRule":"⚡ Behauptungen über ein „Ausleiten“ durch Spezialprodukte prüft man am Körper als entropie-bekämpfendem System: Leber und Nieren leisten diese Arbeit bereits laufend und ohne teure Säfte.","beleg":"Werkstück C.1.2 (Anwendung & Relevanz, „In der Pseudomedizin (‚Detox‘)“)","status":"entwurf","scenario":"Im Werbetext eines Saftanbieters steht: „Dein Körper ist voller Schlacken, die er allein nie wieder loswird. Nur unser Saft leitet sie zuverlässig aus.“ Eine Freundin überlegt, ob sie den Saft bestellen soll.","kurz":"Die Behauptung setzt voraus, der Körper werde „Schlacken“ allein nicht los, obwohl Leber und Nieren laufend abbauen und ausscheiden. Der Saft müsste also etwas leisten, das darüber hinausgeht. Dazu schweigt der Werbetext, auch darüber, was „Schlacke“ überhaupt sein soll.","prueffrage":"Was genau sollen diese „Schlacken“ sein, und hat sie schon jemand im Blut oder Urin nachgewiesen?","rueckmeldung":[{"option":1,"text":"Wer am Verkauf verdient, hat Anlass zu übertreiben, das ist ein berechtigter Grund zur Vorsicht. Ob die Behauptung stimmt, folgt daraus aber nicht: Auch ein interessierter Anbieter kann etwas Zutreffendes sagen, geprüft wird die Aussage selbst."},{"option":2,"text":"Ein deutlich höherer Preis kann misstrauisch machen. Er sagt aber nichts darüber, ob der Körper überhaupt Hilfe beim Ausleiten braucht; auch ein teurer oder billiger Saft kann die Behauptung weder bestätigen noch widerlegen."},{"option":3,"text":"Erfahrungsberichte wirken wie ein Praxistest. Sie spiegeln aber oft Erwartung und Zufall, und viele ähnliche Berichte erklären nicht, wie der Saft wirken soll. Ohne diese Erklärung bleibt offen, was da eigentlich ausgeleitet würde."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Verbraucherzentrale: Detox – überflüssig oder doch gesünder durch Entgiftung?","oeffentlich":true,"url":"https://www.verbraucherzentrale.de/wissen/lebensmittel/nahrungsergaenzungsmittel/detox-ueberfluessig-oder-doch-gesuender-durch-entgiftung-25381","abruf":"2026-10-12"},{"typ":"url","kurz":"Ling, S. J.; Moebs, W.; Sanny, J. (2016): University Physics Vol. 2 (OpenStax), 4.7 Entropy on a Microscopic Scale","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-2/pages/4-7-entropy-on-a-microscopic-scale","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"397bbda4762bd74d"}},{"id":"qx-c1-009","clusterId":"C","werkstueckRef":"C.1.3","stufe":1,"question":"Ein Sternenforscher erklärt: „Massereiche Sterne fusionieren Element für Element bis zum Eisen. Danach macht Fusion keinen Sinn mehr.“ Eine Studentin fragt nach: „Warum sollte genau Eisen das Ende der Kette sein?“ Welche Antwort erklärt es am besten?","options":["Ab dem Eisen wächst die elektrische Abstoßung der Kerne so stark, dass die Temperatur im Kern für weitere Fusionen nicht mehr ausreicht.","Ab dem Eisen hält der Entartungsdruck der Elektronen den Kern stabil, sodass er sich nicht weiter verdichtet und keine höhere Brennstufe zündet.","Ab dem Eisen verbraucht Fusion mehr Energie, als sie erzeugt, der Kern verliert seine Energiequelle und kollabiert unter der eigenen Schwerkraft.","Ab dem Eisen entweicht so viel Energie als Neutrinos, dass der Kern sich abkühlt und die Fusion nicht mehr in Gang gehalten werden kann."],"correctIndex":2,"explanation":"Entscheidend ist die Energiebilanz: Bis zum Eisen setzt jede Fusion Energie frei und hält den Stern am Leben. Bei Eisen kehrt sich das um: Weitere Fusion würde mehr Energie kosten, als sie liefert, der Kern verliert seine Energiequelle und kollabiert unter seiner eigenen Schwerkraft, was meist in einer Supernova endet. Schwerere Elemente sind dennoch nicht unmöglich: Gold und Uran existieren, sie entstehen nur nicht durch Fusion im Sternkern, sondern in der Supernova, zum Teil in aufgeblähten Roten Riesen und nach heutigem Wissen wohl großenteils beim Zusammenstoß von Neutronensternen. Die anderen Gründe klingen nach echter Sternphysik, erklären aber nicht, warum gerade Eisen die Grenze ist: Die elektrische Abstoßung der Kerne wächst mit jeder Stufe stetig und hat bei Eisen keinen Knick. Der Entartungsdruck der Elektronen hält Sterne geringer Masse auf, versagt bei den Eisenkernen massereicher Sterne aber gerade, sodass der Kern kollabiert. Neutrinoverluste beschleunigen die späten Brennstufen, setzen aber an keiner bestimmten Stelle der Elementfolge ein Ende.","coreRule":"⚡ Bei jeder Erklärung fragen: Was ist die Energiebilanz? Bis zum Eisen liefert Fusion Energie, danach kostet sie welche, und der Stern stirbt.","beleg":"Werkstück C.1.3 (Die erste Ernte; Fn gl-c-nukleosynthese: Tyson/Gott/Strauss 2022, Schwedt 2014)","status":"entwurf","scenario":"","kurz":"Bis zum Eisen setzt jede Fusion Energie frei, bei Eisen kehrt sich das um: Weitere Fusion kostet mehr, als sie liefert. Wer nach Kräften sucht, die zufällig bei Eisen greifen, übersieht die Energiebilanz, an der der Kern kollabiert.","prueffrage":"Was hält einen Stern davon ab, unter seinem eigenen Gewicht zusammenzufallen, solange er Elemente verschmilzt?","rueckmeldung":[{"option":0,"text":"Die elektrische Abstoßung erschwert Fusion tatsächlich, je schwerer die Kerne werden. Sie wächst aber stetig und hat bei Eisen keinen Knick; eine Grenze genau dort erklärt sie nicht."},{"option":1,"text":"Der Entartungsdruck der Elektronen hält Sterne geringer Masse stabil, das klingt nach genau der richtigen Physik. Bei den Eisenkernen massereicher Sterne reicht er jedoch nicht mehr aus, der Kern kollabiert, statt stabil zu bleiben."},{"option":3,"text":"Neutrinos tragen in den späten Brennstufen tatsächlich viel Energie davon und beschleunigen diese Stufen. Eine Grenze bei Eisen ergibt sich daraus nicht, denn der Effekt setzt an keiner bestimmten Stelle der Elementfolge ein."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NASA Imagine the Universe!: Supernovae","oeffentlich":true,"url":"https://imagine.gsfc.nasa.gov/science/objects/supernovae1.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kobayashi, C.; Karakas, A. I.; Lugaro, M. (2020): The Origin of Elements from Carbon to Uranium. ApJ 900(2), 179","oeffentlich":true,"doi":"10.3847/1538-4357/abae65","url":"https://arxiv.org/abs/2008.04660","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"06aefe15fc408d4a"}},{"id":"qx-c1-010","clusterId":"C","werkstueckRef":"C.1.3","stufe":2,"question":"Welche Überlegung prüft die Behauptung am besten und führt zu einem begründeten Urteil?","scenario":"In einem Artikel über Schmuck steht: „Gold ist so alt wie das Universum selbst. Es entstand beim Urknall und sammelte sich später in den Planeten.“ Du trägst einen goldenen Ehering und willst prüfen, ob die Aussage stimmt.","options":["Im frühen Universum bestand fast alles aus Wasserstoff und Helium. Schwere Elemente wie Gold brauchen extreme Prozesse in oder nach dem Tod von Sternen. Die Behauptung ist deshalb sehr unwahrscheinlich.","Der Artikel steht im Schmuckkontext ohne Fachquelle, und Werbetexte erzählen gern schöne Herkunftsgeschichten. Ein Urteil über die Behauptung ist deshalb erst nach einer Rückfrage beim Autor möglich.","Gold reagiert chemisch kaum und verändert sich nie. Was seit Milliarden Jahren unverändert bleibt, kann auch seit Milliarden Jahren existieren. Die Behauptung ist deshalb plausibel.","Der Artikel nennt eine sehr bestimmte Herkunft, und Autoren erfinden so etwas selten, ohne nachzuschlagen. Konkrete Aussagen sind meist sorgfältig recherchiert. Die Behauptung ist deshalb plausibel."],"correctIndex":0,"explanation":"Eine Behauptung über Herkunft lässt sich mit dem prüfen, was über die Anfangsbedingungen bekannt ist. Das frühe Universum bestand zu rund 75 % aus Wasserstoff und zu rund 25 % aus Helium, schwerere Elemente gab es praktisch nicht. Elemente jenseits des Eisens entstehen teils in der Hitze von Supernovae, teils durch langsamen Neutroneneinfang in aufgeblähten Roten Riesen. Gold und Uran entstehen nach heutigem Wissen großenteils beim Zusammenstoß zweier ausgebrannter Neutronensterne. Das Gold in deinem Ring entstand also erst, nachdem Sterne entstanden und gestorben waren, in einem Prozess wie einer Sternkatastrophe, nicht beim Urknall. Eine Behauptung ohne Quelle bleibt zwar ungeprüft, aber die Prüfung gegen bekanntes Wissen spricht klar dagegen. Eine Rückfrage beim Autor ist nur nötig, wenn man das Wissen nicht selbst prüfen kann; hier lässt sich die Aussage schon mit bekannten Fakten beurteilen. Dass Gold chemisch kaum reagiert, sagt etwas über seine Haltbarkeit, aber nichts über sein Alter. Und dass ein Artikel konkret klingt, macht ihn noch nicht richtig.","coreRule":"⚡ Prüfe Herkunftsbehauptungen an den Anfangsbedingungen: Was es am Anfang nicht gab, musste später entstehen, und zwar durch einen Prozess, der es erzeugen kann.","beleg":"Werkstück C.1.3; Fn. gl-c-nukleosynthese (Tyson/Gott/Strauss 2022, S. 64–65; Schwedt 2014, S. 197)","status":"entwurf","kurz":"Die Behauptung lässt sich mit bekanntem Wissen prüfen: Das frühe Universum bestand fast nur aus Wasserstoff und Helium, Gold entsteht erst in extremen Sternprozessen. Wer stattdessen auf Quelle, Konkretheit oder Haltbarkeit schaut, prüft nicht die Sache selbst.","prueffrage":"Wird Gold mit der Zeit verbraucht, und was verrät seine Seltenheit dann über sein Alter?","rueckmeldung":[{"option":1,"text":"Misstrauen gegenüber einem Schmucktext ohne Fachquelle ist berechtigt. Ein Urteil hängt aber nicht an einer Rückfrage beim Autor, denn die Aussage lässt sich schon mit bekanntem Wissen über das frühe Universum beurteilen."},{"option":2,"text":"Dass Gold chemisch kaum reagiert, stimmt, es sagt aber nur etwas über seine Haltbarkeit. Wann und wie es entstanden ist, bleibt davon unberührt, und dazu spricht das bekannte Wissen gegen den Urknall."},{"option":3,"text":"Eine sehr bestimmte Aussage wirkt gut recherchiert. Wie konkret etwas klingt, sagt aber nichts darüber, ob es stimmt, und hier fehlt zudem jede Quelle. Entscheidend ist, was sich gegen bekanntes Wissen prüfen lässt."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Fields, B. D.; Molaro, P.; Sarkar, S.: Big Bang Nucleosynthesis. In: Particle Data Group, Review of Particle Physics 2024, Kap. 24","oeffentlich":true,"url":"https://pdg.lbl.gov/2024/reviews/rpp2024-rev-bbang-nucleosynthesis.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kobayashi, C.; Karakas, A. I.; Lugaro, M. (2020): The Origin of Elements from Carbon to Uranium. ApJ 900(2), 179","oeffentlich":true,"doi":"10.3847/1538-4357/abae65","url":"https://arxiv.org/abs/2008.04660","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Tyson, N. deG.; Gott, J. R.; Strauss, M. A. (2022): Das Universum für die Hosentasche, S. 64–65 (laut Landkarte-Fn gl-c-nukleosynthese)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"541ae7dbecbe596d"}},{"id":"qx-c1-011","clusterId":"C","werkstueckRef":"C.1.3","stufe":3,"question":"Du liest die Behauptung: „Das Eisen in deinem Blut stammt aus dem Eisenkern massereicher Sterne, den die Supernova beim Sterben ins All schleudert.“ Welche Prüffrage deckt am besten auf, ob das stimmen kann?","options":["Wird der kollabierte Eisenkern ins All geschleudert, oder bleibt er als dichter Sternrest zurück?","Stammt das Eisen im Blut überhaupt aus Sternen, oder ist es erst später auf der Erde entstanden?","Nennt der Artikel Quellen für den Satz „Wir sind aus Sternenstoff gemacht“, und wer hat ihn verfasst?","Wie viele Supernovae sind nötig, bis genug Eisen für einen Planeten wie die Erde zusammengekommen ist?"],"correctIndex":0,"explanation":"Die Behauptung verwechselt zwei Dinge: das Eisen im Kern eines massereichen Sterns und das Eisen, das tatsächlich ins All gelangt. Wenn der Eisenkern kollabiert, bleibt er als Neutronenstern oder Schwarzes Loch zurück, statt ausgeschleudert zu werden. Die Frage nach dem Schicksal des Kerns trifft deshalb genau die Stelle, an der das Argument bricht. Das Eisen, das ins All gelangt, entsteht erst bei Explosionen: zum Teil in der Kernkollaps-Supernova selbst, in Schichten außerhalb des Kerns, zu einem großen Teil in Supernovae vom Typ Ia, bei denen ein Weißer Zwerg in einem engen Doppelsternsystem explodiert. In beiden Fällen entsteht zunächst Nickel, das über Kobalt zu Eisen zerfällt. Die anderen Fragen sind sinnvoll, entscheiden aber nicht über die Behauptung: Dass das Eisen im Blut aus Sternen stammt, ist unstrittig und sagt nichts darüber, ob es aus dem Eisenkern kommt. Die Frage nach Quellen und Autor ist nützlich, ersetzt aber nicht die Prüfung des Inhalts. Und wie viele Supernovae es braucht, ändert nichts daran, woher ihr Eisen stammt.","coreRule":"⚡ Prüfe bei einer Herkunftsbehauptung, wo das Material entsteht und auf welchem Weg es tatsächlich nach außen gelangt: Das meiste Eisen stammt aus Supernovae vom Typ Ia, der Eisenkern massereicher Sterne bleibt zurück.","beleg":"Werkstück C.1.3 (Kontext & Tiefe, Supernova); Fn. gl-c-eisen (Langer 1995, S. 96; Schneider 2007, S. 49–50); Fn. gl-c-elementherkunft (Kobayashi/Karakas/Lugaro 2020, S. 3 und S. 26)","status":"entwurf","scenario":"In einem Online-Artikel über „Sternenstaub im Körper“ steht der Satz „Wir sind aus Sternenstoff gemacht“ als selbstverständliche Tatsache. Dazu heißt es, bei Eisen sei die Fusion im Sterneninneren an ihr Ende gekommen, weil eine weitere Fusion mehr Energie verbrauchen als freisetzen würde. Danach kollabiere der Kern des Sterns unter der eigenen Schwerkraft.","kurz":"Der Eisenkern kollabiert und bleibt als Neutronenstern oder Schwarzes Loch zurück, er wird nicht ausgeschleudert. Der Fehler: Eisen im Kern wird mit Eisen verwechselt, das ins All gelangt. Das entsteht erst bei Explosionen.","prueffrage":"Was muss mit dem Eisen eines Sterns geschehen, bevor es in einem Planeten und schließlich in deinem Blut landen kann?","rueckmeldung":[{"option":1,"text":"Dass Eisen aus Sternen stammt, ist unstrittig und wird im Artikel ohnehin vorausgesetzt. Dadurch ist aber noch nicht geklärt, ob es gerade aus dem Eisenkern kommt, und genau dort liegt die schwache Stelle der Behauptung."},{"option":2,"text":"Nach Quellen und Autor zu fragen ist ein sinnvoller Reflex. Sie sagen aber nichts darüber, ob die Aussage zum Eisenkern stimmt; dafür musst du den Inhalt selbst prüfen."},{"option":3,"text":"Die Zahl der Supernovae wäre eine reine Mengenfrage. Sie ändert nichts daran, woher das Eisen dieser Explosionen stammt, und trifft die Behauptung deshalb nicht."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NASA Imagine the Universe!: Supernovae","oeffentlich":true,"url":"https://imagine.gsfc.nasa.gov/science/objects/supernovae1.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kobayashi, C.; Karakas, A. I.; Lugaro, M. (2020): The Origin of Elements from Carbon to Uranium. ApJ 900(2), 179","oeffentlich":true,"doi":"10.3847/1538-4357/abae65","url":"https://arxiv.org/abs/2008.04660","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Langer, N. (1995): Leben und Sterben der Sterne. München: C. H. Beck (laut Landkarte-Fn gl-c-eisen S. 96)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1c25924ed428c29a"}},{"id":"qx-c1-012","clusterId":"C","werkstueckRef":"C.1.3","stufe":4,"question":"Eine Astrologin sagt, die Sterne seien mystisch mit uns „verbunden“ und beeinflussten deinen Charakter. Du willst prüfen, ob an einer „Verbindung zu den Sternen“ überhaupt etwas dran ist. Welche Überlegung hält einer Prüfung stand?","options":["Sternbilder zur Geburt bilden Muster, die mit dem Charakter zusammenhängen, sobald man nur lange genug beobachtet und sauber auswertet.","Die Anziehung ferner Sterne wirkt auf Neugeborene stärker als die der Menschen im Kreißsaal und prägt sie dadurch.","Eine Verbindung zu den Sternen gibt es nicht, denn Sternenstoff ist nur eine dichterische Metapher, die sich physikalisch nicht belegen lässt.","Eine Verbindung gibt es, aber als Herkunft: Die Atome deines Körpers, außer Wasserstoff, entstanden in Sternen, ohne dass daraus ein Einfluss auf deinen Charakter folgt."],"correctIndex":3,"explanation":"Die Behauptung „Verbindung“ ist erst dann prüfbar, wenn man fragt, welche Art von Verbindung gemeint ist. Eine Herkunftsverbindung ist real und gut belegt: Nach dem Urknall gab es fast nur Wasserstoff und Helium. Kohlenstoff, Sauerstoff, Eisen und die übrigen schwereren Elemente wurden später durch Kernfusion in Sternen sowie in Supernovae und bei Kollisionen ausgebrannter Sternreste erzeugt. Dass dein Körper aus diesen Elementen besteht, ist ein beobachtbarer Befund und mehr als Poesie. Ein Einfluss auf den Charakter folgt daraus aber nicht: Herkunft des Materials ist etwas anderes als eine Wirkung auf dein Verhalten. Dass ferne Sterne Neugeborene gravitativ prägen, ist physikalisch nicht begründet; für einen solchen Einfluss gibt es keinen Beleg, die belegte Verbindung ist stofflicher Natur. Und wer „Muster, wenn man nur lange genug auswertet“ verspricht, beschreibt keinen Nachweis, sondern die Haltung, nach Bestätigung zu suchen. Die Aussage, es gebe gar keine Verbindung, ist dagegen falsch: Die stoffliche Herkunft aus Sternen ist belegt und mehr als eine Metapher. So hältst du beides auseinander: das echte Herkunftsargument und das unbelegte Einflussargument.","coreRule":"⚡ Prüfe, welche Art von Verbindung behauptet wird: Eine stoffliche Herkunft aus den Sternen ist belegt, ein Einfluss auf Charakter oder Zukunft folgt daraus nicht.","beleg":"Werkstück C.1.3 (Anwendung & Relevanz, „Gegen die Esoterik & Astrologie“; Kernidee)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Eine Verbindung zu den Sternen gibt es als Herkunft: Die schwereren Elemente deines Körpers entstanden in Sternen. Der naheliegende Fehler ist, aus dieser stofflichen Herkunft einen Einfluss auf den Charakter abzuleiten, den sie nicht begründet.","prueffrage":"Was genau soll mit „Verbindung“ gemeint sein, und woran ließe sich diese Art von Verbindung beobachten?","rueckmeldung":[{"option":0,"text":"Wer lange genug sucht, findet in Daten fast immer irgendein Muster. Das ist aber kein Nachweis, sondern eine Suche nach Bestätigung. Ein belegter Zusammenhang zwischen Sternbild und Charakter ergibt sich daraus nicht."},{"option":1,"text":"Gravitation ist eine reale Kraft, daher wirkt die Überlegung physikalisch. Ferne Sterne ziehen wegen ihrer gewaltigen Entfernung aber weit schwächer als die Menschen im Kreißsaal; eine Prägung des Charakters ist dadurch weder begründet noch belegt."},{"option":2,"text":"Sternenstoff klingt tatsächlich nach Poesie, und ein Einfluss auf den Charakter ist nicht belegt. Zu weit geht aber die Aussage, es gebe gar keine Verbindung: Die Herkunft der schwereren Elemente aus Sternen ist gut belegt und mehr als eine Metapher."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Fields, B. D.; Molaro, P.; Sarkar, S.: Big Bang Nucleosynthesis. In: Particle Data Group, Review of Particle Physics 2024, Kap. 24","oeffentlich":true,"url":"https://pdg.lbl.gov/2024/reviews/rpp2024-rev-bbang-nucleosynthesis.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kobayashi, C.; Karakas, A. I.; Lugaro, M. (2020): The Origin of Elements from Carbon to Uranium. ApJ 900(2), 179","oeffentlich":true,"doi":"10.3847/1538-4357/abae65","url":"https://arxiv.org/abs/2008.04660","abruf":"2026-10-12"},{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is Astrology Relevant to Consciousness and Psi? JCS 10(6–7), 175–198 (Archivfassung der Autoren)","oeffentlich":true,"url":"https://www.astrology-and-science.com/D-psia2.htm","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9b8ff0d7b7fd9390"}},{"id":"qx-c1-013","clusterId":"C","werkstueckRef":"C.1.4","stufe":1,"question":"Welche Überlegung führt zur plausibelsten Einschätzung?","options":["Die Hebamme zog vermutlich nicht schwächer als der Mars: Der riesige Abstand schwächt die Kraft stärker, als die Masse des Planeten ausgleicht.","Der Mars zog stärker, denn ein Planet hat unvorstellbar viel mehr Masse als ein Mensch, und die Kraft nimmt nur gleichmäßig mit der Entfernung ab.","Beide zogen praktisch gleich stark, denn die Gravitation reicht unendlich weit und hängt nur von der Masse ab, nicht vom Abstand.","Das lässt sich ohne Messung am Neugeborenen nicht sagen, denn die Stärke einer Kraft zeigt sich nur in der Wirkung auf das Kind selbst."],"correctIndex":0,"explanation":"Die Schwerkraft ist proportional zur Masse und zu 1/r². Verzehnfachst du den Abstand, sinkt die Kraft auf ein Hundertstel. Bei dem Abstand zwischen Baby und Mars (rund 55 Millionen Kilometer gegenüber einem halben Meter) wiegt die enorme Masse des Planeten das nicht auf: Die Hebamme zieht meist um ein Vielfaches stärker als der Mars und selbst bei dessen größter Annäherung nicht schwächer. Die Annahme, Größe zähle mehr als Nähe, ist deshalb ein Denkfehler, denn der Abstand fließt mit der zweiten Potenz ein. Auch ohne Messung am Kind lässt sich die Kraft aus Masse und Abstand berechnen.","coreRule":"⚡ Kraft ~ Masse / Abstand²: Doppelter Abstand heißt ein Viertel der Kraft, zehnfacher Abstand ein Hundertstel. Nähe schlägt Größe, wenn der Abstand groß genug ist.","quote":"Wenn du die Entfernung verdoppelst, sinkt seine Kraft auf ein Viertel (1/2²).","quoteLabel":"Merksatz:","beleg":"Werkstück C.1.4 (Kontext & Tiefe, Formel und Konsequenz)","status":"entwurf","scenario":"Eine Freundin liest ihr Horoskop und sagt: „Der Mars ist riesig, aber selbst bei seiner größten Annäherung rund 55 Millionen Kilometer weg, die Hebamme bei meiner Geburt war dagegen winzig und stand nur etwa einen halben Meter neben mir. Ich frage mich, wie viel Einfluss durch Anziehungskraft da von beiden wohl ausging.“ Du weißt: Die Schwerkraft nimmt mit dem Quadrat der Entfernung ab.","kurz":"Die Schwerkraft wächst mit der Masse, nimmt mit dem Abstand aber im Quadrat ab. Bei 55 Millionen Kilometern gegenüber einem halben Meter gleicht die riesige Masse des Mars das nicht aus. Größe allein entscheidet also nicht.","prueffrage":"Um welchen Faktor ist der Mars schwerer als die Hebamme, und um welchen Faktor schwächt das Quadrat des größeren Abstands seine Anziehung?","rueckmeldung":[{"option":1,"text":"Die Masse des Mars ist tatsächlich unvorstellbar viel größer als die eines Menschen. Die Kraft sinkt aber nicht gleichmäßig, sondern mit dem Quadrat des Abstands, und bei diesem Abstandsverhältnis wiegt das die Masse mehr als auf."},{"option":2,"text":"Die Gravitation hat zwar theoretisch unbegrenzte Reichweite. Das heißt aber nicht, dass der Abstand egal wäre: Die Kraft wird mit zunehmender Entfernung rasch kleiner, und zwar mit 1/r². Dass sie nur von der Masse abhinge, trifft nicht zu."},{"option":3,"text":"Eine Messung am Neugeborenen wäre kaum möglich, aber auch gar nicht nötig. Die Anziehungskraft folgt aus Masse und Abstand und lässt sich daher berechnen, ohne sie am Kind selbst zu beobachten."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 1, 13.1 Newton's Law of Universal Gravitation","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-1/pages/13-1-newtons-law-of-universal-gravitation","abruf":"2026-10-12"},{"typ":"daten","kurz":"NASA NSSDCA: Mars Fact Sheet","oeffentlich":true,"url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/marsfact.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"64e48200a45e997e"}},{"id":"qx-c1-014","clusterId":"C","werkstueckRef":"C.1.4","stufe":2,"question":"Die Astrologin sagt: „Bei deiner Geburt hat der riesige Mars viel stärker an dir gezogen als die Hebamme neben dir. Er ist schließlich ein ganzer Planet.“ Welche Überlegung prüft diese Behauptung am besten?","options":["Man muss Masse und Entfernung gemeinsam betrachten: Weil die Kraft mit dem Quadrat der Entfernung abnimmt, kann die winzige, aber nahe Hebamme stärker ziehen als der riesige, aber ferne Planet.","Man muss nur die Masse vergleichen: Weil der Mars unvergleichlich schwerer ist als ein Mensch, zieht er zwangsläufig stärker, auch wenn die Entfernung groß ist.","Man muss nur die Entfernung vergleichen: Weil die Hebamme viel näher ist, zieht sie stärker, ganz gleich wie klein ihre Masse im Verhältnis zum Planeten ist.","Man muss prüfen, welcher Körper im Horoskop wichtiger ist: Weil der Mars dort eine zentrale Rolle spielt, zieht er stärker als ein Mensch im Raum."],"correctIndex":0,"explanation":"Die Gravitationskraft hängt von zwei Größen zugleich ab: Sie wächst mit der Masse und sinkt mit dem Quadrat der Entfernung; verzehnfachst du den Abstand, bleibt nur ein Hundertstel der Kraft. Beim Mars gleicht die riesige Masse das nicht aus: Eine Hebamme von etwa 70 Kilogramm zieht selbst bei der größten Annäherung des Mars noch etwas stärker als er, bei üblichem Abstand meist um ein Vielfaches stärker. Umgekehrt ziehen Mond und Sonne wegen ihrer enormen Masse trotz großer Entfernung viel stärker als die Hebamme (der Mond rund 1.800-mal, die Sonne rund 300.000-mal so stark). Wie stark ein Körper zieht, folgt also allein aus Masse und Abstand, nicht aus der Bedeutung, die ihm eine Lehre zuschreibt. Wer nur eine der beiden Größen betrachtet oder die Stärke nach Ansehen vergibt, kommt zu falschen Schlüssen.","coreRule":"⚡ Bei Fernwirkungen immer Masse und Abstand zusammen prüfen: Größe allein entscheidet nichts.","beleg":"Werkstück C.1.4 (Das Härten im Feuer, Schmiede-Übung „Die Einfluss-Hierarchie“; Kontext & Tiefe)","status":"entwurf","scenario":"Du sprichst mit einer Astrologin über den angeblichen Einfluss der Planeten auf Neugeborene. Du weißt: Die Gravitationskraft wächst mit der Masse und sinkt mit dem Quadrat der Entfernung. Der Mars ist bei seiner größten Annäherung etwa 55 Millionen Kilometer entfernt, die Hebamme bei einer Geburt etwa einen halben Meter.","kurz":"Gravitation hängt von Masse und Entfernung zugleich ab, und die Entfernung zählt quadratisch. Wer nur auf die Masse des Planeten schaut, übersieht das: Selbst bei größter Annäherung des Mars zieht die nahe Hebamme nicht schwächer, bei üblichem Abstand um ein Vielfaches stärker.","prueffrage":"Wie viel weiter als die Hebamme ist der Mars entfernt, und was sagt die Astrologin über diese Entfernung?","rueckmeldung":[{"option":1,"text":"Der Mars ist unvergleichlich schwerer als ein Mensch, das stimmt. Die Kraft sinkt aber mit dem Quadrat der Entfernung: Selbst bei größter Annäherung zieht die Hebamme nicht schwächer, in größerer Entfernung meist um ein Vielfaches stärker."},{"option":2,"text":"Dass die Hebamme hier stärker zieht, stimmt, aber nicht allein wegen der Nähe. Beide Größen wirken zusammen: Mond und Sonne ziehen trotz großer Entfernung viel stärker als die Hebamme, weil ihre Masse so gewaltig ist."},{"option":3,"text":"Welche Rolle der Mars im Horoskop spielt, sagt nichts über seine Gravitation. Wie stark ein Körper zieht, folgt allein aus Masse und Abstand, nicht aus der Bedeutung, die eine Lehre ihm zuschreibt."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 1, 13.1 Newton's Law of Universal Gravitation","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-1/pages/13-1-newtons-law-of-universal-gravitation","abruf":"2026-10-12"},{"typ":"daten","kurz":"NASA NSSDCA: Mars Fact Sheet","oeffentlich":true,"url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/marsfact.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e00508ee6cfb2a09"}},{"id":"qx-c1-015","clusterId":"C","werkstueckRef":"C.1.4","stufe":3,"question":"Der Astrologe räumt ein: „Die Gravitation der Planeten ist tatsächlich zu schwach, aber es wirkt eine andere, noch unbekannte Kraft.“ Wie lässt sich seine Behauptung am besten prüfen?","options":["Man prüft die behauptete Wirkung selbst: Ordnen Astrologen Geburtshoroskope Menschen besser zu, als der Zufall erwarten lässt, egal welche Kraft dahintersteht?","Man rechnet die bekannten Kräfte der Planeten noch genauer nach: Wirken sie auf das Kind stärker als die Dinge in seiner Umgebung, etwa die Hebamme im Raum?","Man sammelt Berichte von Kunden, deren Horoskop zutraf, und zählt, wie viele von ihnen die Deutung bestätigen und sich mit ihr gut beraten fühlen.","Man wendet Ockhams Rasiermesser an: Eine zusätzliche, unbekannte Kraft ist eine unnötige Annahme, und damit ist die Behauptung bereits geprüft."],"correctIndex":0,"explanation":"Der Verweis auf eine unbekannte Kraft ist ein Argument aus Unwissenheit: Er lässt sich nicht widerlegen, weil sich über das Unbekannte nichts sagen lässt. Prüfbar ist aber die behauptete Wirkung selbst, ganz gleich, durch welche Kraft sie entstehen soll. Genau das wurde getestet: In mehr als vierzig kontrollierten Versuchen ordneten Astrologen Geburtshoroskope nicht besser zu, als der Zufall erwarten lässt. Und gut 2.000 Londoner, die im März 1958 nur Minuten nacheinander zur Welt kamen, glichen einander nicht stärker als beliebige andere. Außerdem liegt die Beweislast bei dem, der die Wirkung behauptet; niemand muss die Nichtexistenz einer unbekannten Kraft beweisen. Die anderen Gedanken klingen vernünftig, passen aber nicht: Die bekannten Kräfte hat der Astrologe bereits als zu schwach eingeräumt, genaueres Nachrechnen klärt also nichts über die behauptete neue Kraft. Berichte zufriedener Kunden zeigen nicht, ob die Treffer über den Zufall hinausgehen. Und Ockhams Rasiermesser hilft, Erklärungen zu gewichten, ersetzt aber nie die Prüfung der behaupteten Wirkung.","coreRule":"⚡ Wer eine Wirkung behauptet, muss sie zeigen – egal, durch welche Kraft sie angeblich entsteht.","beleg":"Werkstück C.1.4 (Anwendung & Relevanz, „Bei der Astrologie“; Belege unter F.2.1 und Band II, Sektion II.8.1)","status":"entwurf","scenario":"Du hast einem Astrologen vorgerechnet, dass der Mars bei einer Geburt nicht stärker an dem Kind zieht als die anwesende Hebamme.","kurz":"Eine unbekannte Kraft lässt sich nicht widerlegen, die behauptete Wirkung aber sehr wohl testen, gleich durch welche Kraft sie entstehen soll. Der Denkfehler ist, mit dem Unbekannten zu argumentieren, statt die Wirkung zu prüfen.","prueffrage":"Was ließe sich über eine Kraft, von der nichts bekannt ist, überhaupt berechnen oder widerlegen?","rueckmeldung":[{"option":1,"text":"Genaueres Nachrechnen wirkt gründlich, trifft aber den Punkt nicht mehr: Der Astrologe hat die bekannten Kräfte schon als zu schwach eingeräumt und beruft sich auf eine andere. Die behauptete neue Kraft lässt sich so nicht prüfen."},{"option":2,"text":"Zufriedene Kunden wirken wie Belege aus der Praxis. Sie zeigen aber nicht, ob die Treffer über den Zufall hinausgehen, denn es fehlen Vergleichswerte. Gut beraten zu sein heißt auch nicht, dass das Horoskop etwas bewirkt hat."},{"option":3,"text":"Ockhams Rasiermesser hilft, Erklärungen zu gewichten, und eine zusätzliche Kraft ist tatsächlich eine zusätzliche Annahme. Es ersetzt aber nicht den Test der behaupteten Wirkung: Mit dem Verweis auf Sparsamkeit allein ist noch nichts geprüft."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is Astrology Relevant to Consciousness and Psi? JCS 10(6–7), 175–198 (Archivfassung der Autoren)","oeffentlich":true,"url":"https://www.astrology-and-science.com/D-psia2.htm","abruf":"2026-10-12"},{"typ":"doi","kurz":"Carlson, S. (1985): A double-blind test of astrology. Nature 318, 419–425","oeffentlich":false,"doi":"10.1038/318419a0"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (2015, überarb. 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7971a1ecb3ba5866"}},{"id":"qx-c1-016","clusterId":"C","werkstueckRef":"C.1.4","stufe":4,"question":"Eine „Fernheilerin“ behauptet, ihre Wirkung sei aus 8.000 Kilometern Entfernung genauso stark wie am Bett. Welche Frage prüft diese Behauptung am besten?","options":["Wie viel Masse die Heilerin besitzt, denn bei großem Abstand wirken nur sehr massereiche Objekte überhaupt noch auf einen Menschen.","Wie schnell die Wirkung eintrifft, denn nur zu langsam ankommende Kräfte lassen sich mit physikalischen Gesetzen infrage stellen.","Keine, denn die Gravitation reicht unendlich weit; also darf jede andere Wirkung ebenfalls beliebig weit tragen, ohne zu schwinden.","Welche Kraft das leisten soll, denn jede Kraft aus so weiter Ferne müsste erklären, warum sie nicht mit der Entfernung abnimmt."],"correctIndex":3,"explanation":"Bekannte langreichweitige Kräfte wie Gravitation und Elektromagnetismus nehmen mit dem Quadrat der Entfernung ab: Bei zehnfachem Abstand bleibt nur ein Hundertstel, bei 8.000 Kilometern statt einem Meter ist die Wirkung nach dieser Regel um viele Größenordnungen geschwunden. Unendliche Reichweite heißt nicht gleichbleibende Stärke. Wer eine Wirkung aus großer Ferne behauptet, die am Bett genauso stark sein soll wie in 8.000 Kilometern, muss deshalb erklären, welcher Mechanismus das Abnehmen mit der Entfernung umgeht. Antwortet jemand darauf nur mit vagen, mystischen Begriffen statt mit überprüfbaren Angaben, ist das ein Warnsignal. Die Frage nach der Masse der Heilerin oder der Geschwindigkeit der Wirkung trifft den Kern nicht, und die Behauptung, Reichweite bedeute gleiche Stärke, ist schlicht falsch.","coreRule":"⚡ Wer eine Fernwirkung behauptet, muss erklären, warum sie mit der Entfernung nicht schwindet.","beleg":"Werkstück C.1.4 (Anwendung & Relevanz, „Bei anderen esoterischen Behauptungen“; Red Flags)","status":"entwurf","kurz":"Eine Wirkung aus 8.000 Kilometern müsste erklären, warum sie nicht schwächer wird, denn bekannte Kräfte nehmen mit dem Quadrat der Entfernung ab. Der naheliegende Fehler: „unendlich weit“ mit „gleich stark“ zu verwechseln.","prueffrage":"Reicht die Schwerkraft der Erde bis zum Mond, und ist sie dort noch so stark wie an der Erdoberfläche?","rueckmeldung":[{"option":0,"text":"Bei der Gravitation zählt die Masse tatsächlich, doch auch dort schwindet die Wirkung mit dem Abstand. Die Masse der Heilerin erklärt also nicht, warum die Wirkung in 8.000 Kilometern so stark sein soll wie am Bett."},{"option":1,"text":"Die Frage nach dem Tempo wirkt messbar und damit wissenschaftlich. Physikalische Gesetze gelten aber nicht nur für langsame Kräfte: Entscheidend ist, warum die Wirkung mit der Entfernung nicht abnehmen soll, ganz gleich, wie schnell sie ankommt."},{"option":2,"text":"Gravitation reicht tatsächlich unendlich weit, aber ihre Stärke nimmt mit dem Quadrat der Entfernung ab. Unendliche Reichweite heißt nicht gleichbleibende Stärke, und daraus lässt sich keine beliebig weit tragende Wirkung ableiten."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 1, 13.1 Newton's Law of Universal Gravitation","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-1/pages/13-1-newtons-law-of-universal-gravitation","abruf":"2026-10-12"},{"typ":"url","kurz":"CERN: The Standard Model","oeffentlich":true,"url":"https://home.cern/science/physics/standard-model","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"33c8ff7042a2f80b"}},{"id":"qx-c1-017","clusterId":"C","werkstueckRef":"C.1.5","stufe":1,"question":"Welche Schlussfolgerung ist mit diesen Messwerten am besten vereinbar?","scenario":"Am Rand des Grand Canyon sagt ein Besucher: „Eine so riesige Schlucht kann nur eine einzige gewaltige Flut in kurzer Zeit in den Fels geschnitten haben.“ Datierte Ablagerungen in Höhlen der Canyonwände zeigen, dass sich der Colorado River im Mittel nur um Bruchteile eines Millimeters pro Jahr eingegraben hat, also langsamer, als ein Fingernagel wächst.","options":["Der Canyon ist vor allem von Gletschern ausgeschürft worden, weil Eis Täler schneller vertieft als gewöhnliches fließendes Wasser.","Der Canyon ist in kurzer Zeit entstanden, weil Hochwasser in wenigen Tagen sehr viel Fels abtragen und Erosion meist in Schüben verläuft.","Der Canyon ist in vergleichsweise kurzer Zeit entstanden, weil sich der Fluss mit mehreren Millimetern pro Jahr eingegraben hat.","Der Canyon ist über sehr lange Zeit entstanden, weil ein meist unspektakulärer Fluss sich nur langsam, aber stetig eingegraben hat."],"correctIndex":3,"explanation":"Rate mal Zeit ergibt die Tiefe: Wer eine gemessene Einschneiderate von nur Bruchteilen eines Millimeters pro Jahr kennt, kann die Entstehung einer so gewaltigen Schlucht nicht in Wochen oder wenigen Jahrtausenden erklären. Er braucht unvorstellbar lange Zeiträume, in denen winzige Schritte sich summieren. Die genannte Größenordnung stammt aus der Datierung von Höhlenablagerungen (Polyak u. a. 2008): Der Grundwasserspiegel sank um rund 0,05 bis 0,4 mm pro Jahr. Vorbehalt: Umstritten ist unter anderem, ob sich Absenkung des Grundwasserspiegels und Einschneiden gleichsetzen lassen, nicht aber die Größenordnung der Rate. Dass man sich langsame Prozesse über riesige Zeiträume schwer vorstellen kann, ist kein Argument gegen sie. Dass Hochwasser viel Fels abtragen und Erosion in Schüben verläuft, stimmt, ändert aber nichts am gemessenen Mittelwert, aus dem sich die Dauer ergibt. Gletscher vertiefen Täler tatsächlich schnell, die Messwerte betreffen aber das Einschneiden des Flusses. Und mehrere Millimeter pro Jahr widersprechen den gemessenen Bruchteilen eines Millimeters.","coreRule":"⚡ Rate mal Zeit ergibt das Ergebnis: Auch winzige, stetige Veränderungen schaffen über genug Zeit riesige Formen. Prüfe immer, ob die Zeitskala der Erklärung zur gemessenen Rate passt.","beleg":"Werkstück C.1.5 (Der Fingernagel am Grand Canyon); Fn. gl-c-grandcanyon (Polyak/Hill/Asmerom 2008, Science 319, S. 1377–1380)","status":"entwurf","kurz":"Aus der gemessenen Rate von Bruchteilen eines Millimeters pro Jahr ergibt sich über Rate mal Zeit eine sehr lange Dauer. Dass sich langsame Prozesse über riesige Zeiträume schwer vorstellen lassen, ist kein Einwand gegen sie.","prueffrage":"Wie tief wird eine Schlucht, wenn sich ein Fluss 1.000 Jahre lang um 0,1 Millimeter pro Jahr eingräbt, und wie tief nach einer Million Jahren?","rueckmeldung":[{"option":0,"text":"Eis vertieft Täler tatsächlich schnell. Die Messwerte stammen aber aus Höhlenablagerungen und beschreiben das Einschneiden des Flusses, nicht das von Gletschern. Mit ihnen lässt sich die Gletscherthese weder stützen noch widerlegen."},{"option":1,"text":"Hochwasser tragen tatsächlich viel Fels ab, und Erosion verläuft meist in Schüben. Entscheidend ist aber der gemessene Mittelwert über lange Zeit: Bruchteile eines Millimeters pro Jahr. Aus ihm ergibt sich die Dauer, und kräftige Schübe ändern daran nichts."},{"option":2,"text":"Die Rechenidee stimmt: Rate mal Zeit ergibt die Tiefe. Die Zahl dahinter stimmt jedoch nicht, denn gemessen wurden nur Bruchteile eines Millimeters pro Jahr, nicht mehrere Millimeter. Mit der gemessenen Rate wird die Dauer viel länger."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Polyak, V.; Hill, C.; Asmerom, Y. (2008): Age and Evolution of the Grand Canyon Revealed by U-Pb Dating of Water Table-Type Speleothems. Science 319, 1377–1380","oeffentlich":false,"doi":"10.1126/science.1151248"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f6eb2061de9e7a78"}},{"id":"qx-c1-018","clusterId":"C","werkstueckRef":"C.1.5","stufe":2,"question":"Wie weit vor dem Ziel würde der Mensch auf dieser Strecke auftauchen?","options":["Etwa 15 Meter vor dem Ziel, also ungefähr dort, wo auch die Dinosaurier ausgestorben sind.","Etwa 4 bis 7 Zentimeter vor dem Ziel, also weniger als eine Handbreit vor der Ziellinie.","Etwa 50 Zentimeter vor dem Ziel, also noch ungefähr eine Armlänge vor der Ziellinie.","Etwa 5 Millimeter vor dem Ziel, also nur noch ungefähr die Länge eines Reiskorns davor."],"correctIndex":1,"explanation":"Die Rechnung ist ein einfacher Dreisatz: 200.000 bis 300.000 Jahre geteilt durch 4,54 Milliarden Jahre ergibt rund 0,004 bis 0,007 Prozent der Erdgeschichte. Auf 1.000 Metern sind das etwa 4 bis 7 Zentimeter. Zur Gegenprobe: Das Aussterben der Dinosaurier läge bei Meter 985, also etwa 15 Meter vor dem Ziel; der Mensch kommt erst etwa 4 bis 7 Zentimeter vor dem Ziel. Zwischen dem Aussterben der Dinosaurier und dem Auftauchen des Menschen liegt also fast die gesamte letzte Strecke. Die Menschheit ist ein geologischer Wimpernschlag am Ende der Strecke. Unsere Intuition ist für Tage und Lebenszeiten gemacht und überfordert sich bei Milliarden von Jahren, deshalb hilft es, die Größenordnung durch eine Verhältnisrechnung zu prüfen.","coreRule":"⚡ Schätze Größenordnungen durch ein Verhältnis, nicht nach dem Gefühl: Auf der Zeitleiste der Erde sind wir ein Wimpernschlag am Ende.","beleg":"Werkstück C.1.5 (Die Schmiede-Übung „Der Zeit-Spaziergang“; Kontext & Tiefe); Fn. gl-c-erdalter (Dalrymple 2001, S. 205, 213, 217–219)","status":"entwurf","scenario":"Ein Freund sagt: „Den modernen Menschen gibt es doch schon ewig – dass die Dinosaurier lange vor uns ausgestorben sind, ist ein kleiner Unterschied.“ Um ihm die Größenordnung greifbar zu machen, überträgst du die gesamte Erdgeschichte (4,54 Milliarden Jahre) auf einen Kilometer Wegstrecke: Der Start steht für die Entstehung der Erde, das Ziel für heute. Der moderne Mensch existiert seit etwa 200.000 bis 300.000 Jahren, die Dinosaurier starben vor etwa 66 Millionen Jahren aus.","kurz":"200.000 bis 300.000 Jahre sind nur etwa 0,004 bis 0,007 Prozent der Erdgeschichte, auf einem Kilometer also 4 bis 7 Zentimeter. Der Denkfehler: Mensch und Dinosaurier-Ende wirken zeitlich nah, liegen auf der Strecke aber rund 15 Meter auseinander.","prueffrage":"Wie viele Meter der Strecke entsprechen einem Zehntel Prozent der gesamten Erdgeschichte, und passen die Zeitspannen der Menschheit darunter oder darüber?","rueckmeldung":[{"option":0,"text":"Bei etwa 15 Metern vor dem Ziel endet tatsächlich die Zeit der Dinosaurier, das stimmt. Der Mensch taucht aber erst viel später auf, rund 4 bis 7 Zentimeter vor dem Ziel. Zwischen beiden liegt fast die ganze letzte Strecke."},{"option":2,"text":"Eine Armlänge klingt nach einem sehr kurzen Stück, und das Gefühl, der Mensch sei spät dran, stimmt. Die Rechnung ergibt aber etwa 4 bis 7 Zentimeter. 50 Zentimeter entsprächen mehr als zwei Millionen Jahren, rund dem Zehnfachen."},{"option":3,"text":"Dass es auf der Strecke winzig ist, stimmt. Ein Reiskorn wäre aber zu wenig: 5 Millimeter entsprächen nur etwa 23.000 Jahren, nicht den 200.000 bis 300.000 Jahren des modernen Menschen. Der Dreisatz ergibt 4 bis 7 Zentimeter."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"USGS: Geologic Time – Age of the Earth","oeffentlich":true,"url":"https://pubs.usgs.gov/gip/geotime/age.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Dalrymple, G. B. (2001): The age of the Earth in the twentieth century: a problem (mostly) solved. Geol. Soc. London Spec. Publ. 190, 205–221","oeffentlich":false,"doi":"10.1144/GSL.SP.2001.190.01.14"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"19096bd4c12e221c"}},{"id":"qx-c1-019","clusterId":"C","werkstueckRef":"C.1.5","stufe":3,"question":"Ein Gesprächspartner zeigt dir das Fossil eines Meerestiers, das auf einem hohen Berg gefunden wurde, und sagt: „Das beweist eine weltweite Sintflut vor wenigen tausend Jahren.“ Welche Erwiderung nimmt den Fund ernst und erklärt ihn am sparsamsten, ohne die Tatsache selbst zu bestreiten?","options":["Manche Gesteinsmuster ähneln Lebewesen, ohne je welche gewesen zu sein, und lassen sich als Zufallsbildung im Gestein erklären.","Der Meeresspiegel schwankt im Wechsel von Warm- und Eiszeiten um viele Dutzend Meter und überflutete so zeitweise weite Landstriche.","Ehemaliger Meeresboden wurde durch die Bewegung der Erdplatten über Millionen Jahre langsam zu Hochgebirgen aufgefaltet.","Sturmfluten und Tsunamis spülen Meerestiere tatsächlich weit landeinwärts, wo sie liegen bleiben und mit der Zeit in Sedimenten eingebettet werden."],"correctIndex":2,"explanation":"Der Fund selbst ist echt: Meerestiere lebten dort, wo heute Berge stehen. Offen ist nur, wie er dorthin kam. Die sparsamste Erklärung nimmt Prozesse, die sich heute noch beobachten lassen: Erdplatten bewegen sich, und ehemaliger Meeresboden wird über Millionen Jahre langsam zu Hochgebirgen aufgefaltet. Die radiometrische Datierung und die Abfolge der Gesteinsschichten belegen so lange Zeiträume (Tiefenzeit). Gegen den Sintflut-Einwand hilft das Konzept der Tiefenzeit: Es bietet die langsame, aber mächtigere Erklärung. Pseudofossilien gibt es zwar, doch hier soll der Fund als Versteinerung von Meerestieren erklärt und nicht bestritten werden. Schwankungen des Meeresspiegels um einige Dutzend Meter sind real, sie heben aber keine Meeresablagerungen auf die Höhe eines Gebirges. Sturmfluten und Tsunamis tragen Tiere tatsächlich ins Land, sie erklären jedoch nicht, wie daraus hohe Felswände aus Meeresgestein werden.","coreRule":"⚡ Wenn ein Fund zu einer einzigen großen Katastrophe passt, prüfe, ob langsame, heute beobachtbare Prozesse über sehr lange Zeit denselben Befund sparsamer erklären.","beleg":"Werkstück C.1.5 (Werkbank-Frage; Red Flags, „Sintflut“)","status":"entwurf","scenario":"Auf einer Wanderung in den Alpen entdeckst du in einer Felswand Versteinerungen von Muscheln und Seelilien. Dein Begleiter hält sie für den Beweis einer einzigen großen Überflutung vor wenigen tausend Jahren.","quote":"","quoteLabel":"","kurz":"Der Fund ist echt, offen ist nur, wie er dorthin kam. Am sparsamsten erklären ihn heute noch beobachtbare Vorgänge: Erdplatten falten ehemaligen Meeresboden über Millionen Jahre zu Gebirgen auf. Eine einzelne Flut braucht keiner.","prueffrage":"Stecken die Versteinerungen in einer einzigen Schicht oder in vielen übereinanderliegenden Gesteinsschichten der Felswand?","rueckmeldung":[{"option":0,"text":"Pseudofossilien gibt es wirklich, doch Muscheln und Seelilien mit erkennbarem Körperbau sind keine Zufallsmuster. Diese Erwiderung bestreitet den Fund, statt ihn zu erklären, und die Frage verlangt gerade, ihn ernst zu nehmen."},{"option":1,"text":"Meeresspiegel schwanken im Wechsel von Warm- und Eiszeiten tatsächlich um viele Dutzend Meter. Das reicht aber nicht, um Meeresablagerungen auf die Höhe eines Gebirges zu bringen, deshalb erklärt es den Fund nicht."},{"option":3,"text":"Sturmfluten und Tsunamis spülen Meerestiere wirklich weit ins Land. Eine ganze Felswand aus Meeresgestein mit eingebetteten Muscheln und Seelilien ist damit aber nicht erklärt, denn dafür müsste ehemaliger Meeresboden in die Höhe gelangt sein."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"USGS, This Dynamic Earth: The Himalayas – Two continents collide","oeffentlich":true,"url":"https://pubs.usgs.gov/gip/dynamic/himalaya.html","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS: Geologic Time – radiometrische Zeitskala","oeffentlich":true,"url":"https://pubs.usgs.gov/gip/geotime/radiometric.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d17077f298b4fb3b"}},{"id":"qx-c1-020","clusterId":"C","werkstueckRef":"C.1.5","stufe":4,"question":"Jemand sagt: „Das Klima hat sich schon immer verändert – heute ist nichts Besonderes.“ Du hast Daten aus Eisbohrkernen vor dir, die das Klima über rund 800.000 Jahre rekonstruieren. Welche Frage an diese Daten prüft die Behauptung am besten?","options":["Wie schnell stieg die CO₂-Konzentration in den früheren Phasen, die die Eisbohrkerne zeigen, im Vergleich zum heutigen Anstieg?","Stimmen Eisbohrkerne aus verschiedenen Regionen im Verlauf der CO₂-Konzentration überein, sodass die Messdaten verlässlich sind?","Wie genau lässt sich die Zusammensetzung der Luftbläschen im Labor messen, und mit welchen Messfehlern ist dabei zu rechnen?","Gingen in den früheren Phasen die Temperaturänderungen den CO₂-Änderungen voraus, oder folgten sie ihnen erst mit zeitlichem Abstand?"],"correctIndex":0,"explanation":"Der Satz „Das Klima hat sich schon immer verändert“ ist richtig, beweist aber wenig: Auch wenn Veränderung früher vorkam, sagt das nichts darüber, ob die heutige Veränderung vergleichbar ist. Entscheidend ist die Rate, also wie schnell sich etwas ändert, und nicht nur, ob. Genau das lässt sich mit langen Datenreihen prüfen. Die heutige CO₂-Konzentration liegt höher als in mindestens zwei Millionen Jahren; laut IPCC (2021) ist ihr Anstieg seit 1850 in den letzten 800.000 Jahren ohne Beispiel. Zudem hat sich die Erde seit 1970 schneller erwärmt als in jedem anderen Fünfzigjahreszeitraum der letzten zweitausend Jahre. Auch die schnellsten CO₂-Änderungsraten der letzten 56 Millionen Jahre lagen mindestens um den Faktor vier darunter (geringe Konfidenz). Wer nur fragt, ob es früher Veränderungen gab, übersieht den Kern: Eine wahre Aussage („Klima änderte sich immer“) kann trotzdem in die Irre führen, wenn sie das Tempo ausblendet. Ob Bohrkerne übereinstimmen und wie genau im Labor gemessen wird, sind sinnvolle Fragen zur Verlässlichkeit der Daten, sagen aber nicht, ob das heutige Tempo ungewöhnlich ist. Die zeitliche Reihenfolge von Temperatur und CO₂ betrifft die Ursache früherer Schwankungen, nicht den Vergleich der Geschwindigkeiten. Die Daten liegen hier ohnehin vor; entscheidend ist, was man sie fragt.","coreRule":"⚡ „Das Klima änderte sich immer“ stimmt – aber die Frage ist, wie schnell. Prüfe die Änderungsrate, nicht nur das Vorkommen von Veränderung.","beleg":"Werkstück C.1.5 (Anwendung & Relevanz, „Im Kontext des Klimawandels (C.5.1)“); Fn. gl-c-ipcc-tempo (IPCC 2021, SPM A.2.1 und A.2.2, S. 8; Technical Summary S. 69)","status":"entwurf","scenario":"Eisbohrkerne enthalten eingeschlossene Luftbläschen aus vergangenen Zeiten. Aus ihnen lässt sich ablesen, wie hoch die CO₂-Konzentration in der Atmosphäre früher war und wie schnell sie sich änderte.","quote":"","quoteLabel":"","kurz":"Die Behauptung blendet das Tempo aus: Dass sich das Klima früher änderte, sagt nichts darüber, ob die heutige Änderung vergleichbar schnell ist. Erst der Vergleich der Änderungsraten in den langen Datenreihen prüft sie.","prueffrage":"Würden Eisbohrkerne auch dann frühere CO₂-Schwankungen zeigen, wenn die heutige Änderung völlig neuartig wäre?","rueckmeldung":[{"option":1,"text":"Dass Kerne aus verschiedenen Regionen übereinstimmen, spricht für verlässliche Daten. Das klärt aber nur, ob man den Daten trauen kann, nicht, ob das heutige Tempo ungewöhnlich ist."},{"option":2,"text":"Messgenauigkeit und Messfehler sind eine berechtigte Frage an Daten. Sie sagt dir aber nichts darüber, wie schnell sich CO₂ früher und heute änderte; die Daten liegen hier ohnehin vor."},{"option":3,"text":"Die Reihenfolge von Temperatur und CO₂ betrifft die Ursache früherer Schwankungen. Die Behauptung dreht sich aber um das Ausmaß der heutigen Veränderung, und dafür zählt das Tempo."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"IPCC (2021): Summary for Policymakers. In: Climate Change 2021: The Physical Science Basis (AR6 WGI), Abschn. A.2.1–A.2.2","oeffentlich":true,"doi":"10.1017/9781009157896.001","url":"https://www.ipcc.ch/report/ar6/wg1/downloads/report/IPCC_AR6_WGI_SPM.pdf","abruf":"2026-10-04"},{"typ":"doi","kurz":"Arias, P. A. u. a. (2021): Technical Summary. In: Climate Change 2021 (AR6 WGI)","oeffentlich":false,"doi":"10.1017/9781009157896.002"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"dea7085659cdbf37"}},{"id":"qx-c1-021","clusterId":"C","werkstueckRef":"C.1.6","stufe":1,"question":"Jemand sagt: „In ein paar tausend Jahren haben wir einfach bessere Antriebe, dann fliegen wir mit Lichtgeschwindigkeit zu den Nachbarsternen.“ Welcher Einwand trifft den Kern dieser Annahme am besten?","options":["Je schneller ein Schiff durch den Raum fliegt, desto härter treffen es Staub und Gasteilchen zwischen den Sternen und beschädigen es.","Je näher ein Objekt mit Masse dem Lichttempo kommt, desto mehr Energie braucht es; für das Erreichen selbst wäre unendlich viel nötig.","Je näher ein Objekt mit Masse dem Lichttempo kommt, desto langsamer vergeht seine Zeit, sodass die Reisenden weniger altern als die Daheimgebliebenen.","Je stärker ein Schiff beschleunigt, desto größer ist die Belastung für die Besatzung, denn Menschen halten nur begrenzte Beschleunigung aus."],"correctIndex":1,"explanation":"Die Annahme übersieht, dass es hier nicht um einen Mangel an Technik geht, sondern um ein Prinzip: Für alles mit Masse wächst der Energiebedarf bei Annäherung an die Lichtgeschwindigkeit (ca. 300.000 km/s) immer weiter an und würde für das Erreichen selbst gegen unendlich gehen. Bessere Antriebe können diese Schwelle also nicht abschaffen, höchstens den Weg dorthin effizienter machen. Wer „es braucht nur bessere Technik“ sagt, behauptet daher etwas, das die Physik nicht hergibt, und müsste einen konkreten Mechanismus nennen, der die Energieschranke umgeht. Das Argument „irgendwie wird sich das lösen“ ersetzt keinen solchen Beleg. Staub und Gas können ein sehr schnelles Schiff tatsächlich beschädigen, das ist aber ein technisches Hindernis und keine Grundgrenze. Die Zeitdehnung an Bord ist real, ändert aber nichts am Energiebedarf, denn die Zeit vergeht dort nur langsamer und bleibt nicht stehen. Die Belastung durch Beschleunigung lässt sich durch längeres, sanfteres Beschleunigen mildern, die Energieschranke bliebe trotzdem.","coreRule":"⚡ Für alles mit Masse ist die Lichtgeschwindigkeit eine Schwelle, die unendlich viel Energie kosten würde: Das ist ein Prinzip, kein Technikproblem.","beleg":"Werkstück C.1.6 (Kontext & Tiefe, „Die kosmische Temposchwelle“)","status":"entwurf","scenario":"In einer Diskussion über Reisen zu anderen Sternen wird argumentiert, es sei nur eine Frage der Antriebstechnik, bis Raumschiffe mit Masse die Lichtgeschwindigkeit erreichen.","kurz":"Hier fehlt kein Antrieb, sondern es gibt eine Grenze: Für alles mit Masse wächst der Energiebedarf nahe der Lichtgeschwindigkeit immer weiter und würde fürs Erreichen selbst gegen unendlich gehen. Bessere Technik schafft das nicht ab.","prueffrage":"Welcher konkrete Mechanismus soll nach dieser Aussage das Hindernis aus dem Weg räumen, und nennt sie einen?","rueckmeldung":[{"option":0,"text":"Staub und Gas können ein sehr schnelles Schiff tatsächlich beschädigen. Das ist aber ein technisches Hindernis, dem sich etwa mit Schutz begegnen ließe, und keine Grenze, die das Erreichen der Lichtgeschwindigkeit selbst ausschließt."},{"option":2,"text":"Die Zeitdehnung ist real: An Bord vergeht die Zeit langsamer. Am Energiebedarf ändert das nichts, denn die Zeit wird nur gedehnt und steht nicht still. Der Einwand trifft deshalb nicht den Kern der Annahme."},{"option":3,"text":"Menschen halten nur begrenzte Beschleunigung aus, das stimmt. Längeres, sanfteres Beschleunigen mildert das aber, und die Energieschranke bliebe trotzdem. Der Einwand betrifft also nur die Besatzung, nicht die Grenze selbst."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: University Physics Vol. 3, 5.9 Relativistic Energy","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-3/pages/5-9-relativistic-energy","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0ddacee2d12f3d75"}},{"id":"qx-c1-022","clusterId":"C","werkstueckRef":"C.1.6","stufe":2,"question":"Du willst die Behauptung mit einer Überschlagsrechnung prüfen: Wie lange bräuchte die schnellste Sonde der Menschheit für den Hinflug zum nächsten Stern etwa?","scenario":"Ein Mann behauptet im Gespräch: „Außerirdische können uns ganz leicht besuchen. Unsere schnellste Raumsonde fliegt doch schon mit rund 700.000 km/h, da ist der nächste Stern praktisch um die Ecke.“ Der nächste Stern, Proxima Centauri, ist etwa 4,2 Lichtjahre entfernt, das sind rund 40 Billionen Kilometer. Ein Lichtjahr ist die Strecke, die Licht in einem Jahr zurücklegt; Licht fliegt mit etwa 300.000 km/s, also rund 1,08 Milliarden km/h.","options":["Etwa 66 Jahre, kaum länger als ein langes Menschenleben, wenn das Höchsttempo gehalten wird.","Etwa 660 Jahre, mehr als zehn Menschenleben, aber noch im Bereich vorstellbarer Generationenschiffe.","Etwa 6.600 Jahre, selbst im Tempo der schnellsten Sonde dauert der Hinflug Jahrtausende.","Etwa 66.000 Jahre, so lange würde die Sonde bis zum nächsten Stern unterwegs sein."],"correctIndex":2,"explanation":"Die Sonde ist mit rund 700.000 km/h nur etwa 1/1.500 so schnell wie das Licht (700.000 geteilt durch 1,08 Milliarden). Licht braucht für 4,2 Lichtjahre 4,2 Jahre, die Sonde also rund 1.500-mal so lang: grob gerechnet 6.300 Jahre, mit genaueren Werten (4,24 Lichtjahre, rund 690.000 km/h) gut 6.600 Jahre. Entscheidend ist die Größenordnung: Jahrtausende, nicht Jahrzehnte oder Jahrhunderte, und das Tempo ist noch großzügig angesetzt, denn die Sonde erreicht es nur im Sturz auf die Sonne zu; Voyager 1 mit rund 17 km/s bräuchte etwa 75.000 Jahre. Dass der Stern „praktisch um die Ecke“ liege, hält der Rechnung also nicht stand. Wer „leichte“ Besuche behauptet, muss erklären, wie ein Fahrzeug um ein Vielfaches schneller sein soll als alles, was wir bauen können.","coreRule":"⚡ Ein beeindruckend klingendes Tempo sagt nichts, solange du es nicht mit der Entfernung vergleichst: Rechne die Größenordnung nach.","beleg":"Werkstück C.1.6 (Die unmögliche Reise); Fn. gl-c-proxima (Parker Solar Probe Ende 2024, rund 690.000 km/h; Voyager 1 rund 75.000 Jahre). Szenario auf Behauptungsprüfung umgebaut, Lichtgeschwindigkeit ca. 300.000 km/s aus der Analyse, Umrechnung in km/h Allgemeinwissen.","status":"entwurf","kurz":"Die Sonde fliegt nur mit etwa 1/1.500 der Lichtgeschwindigkeit und braucht also rund 1.500-mal so lange wie das Licht mit seinen 4,2 Jahren: etwa 6.300 bis 6.600 Jahre. „Praktisch um die Ecke“ täuscht, weil ein im Alltag riesiges Tempo an Sternentfernungen gemessen winzig ist.","prueffrage":"Wie oft passt die Sondengeschwindigkeit in die Geschwindigkeit des Lichts, und was bedeutet das für die Reisezeit im Vergleich zu den 4,2 Jahren, die Licht braucht?","rueckmeldung":[{"option":0,"text":"Ein Menschenleben als Reisedauer klingt beinahe machbar, weil die Zahl 700.000 km/h so groß wirkt. Gegen das Licht gerechnet ist die Sonde aber nur etwa 1/1.500 so schnell, die Zeit wird also nicht zu 66 Jahren, sondern zu Jahrtausenden."},{"option":1,"text":"660 Jahre klingen schon nach einer gewaltigen Reise, deshalb wirkt der Wert vorsichtig genug. Mit 4,2 Jahren Lichtlaufzeit mal etwa 1.500 kommt man aber auf Jahrtausende; 660 Jahre sind rund zehnmal zu wenig."},{"option":3,"text":"Wer die riesigen Entfernungen ernst nimmt, greift leicht zur größten Zahl. Die Überschlagsrechnung ergibt für die schnellste Sonde aber rund 6.600 Jahre, ein Zehntel davon; Zehntausende Jahre bräuchte erst eine langsamere Sonde wie Voyager 1."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NASA Science: Parker Solar Probe (Missionsseite)","oeffentlich":true,"url":"https://science.nasa.gov/mission/parker-solar-probe/","abruf":"2026-10-12"},{"typ":"url","kurz":"NASA Imagine the Universe!: The Nearest Neighbor Star","oeffentlich":true,"url":"https://imagine.gsfc.nasa.gov/features/cosmic/nearest_star_info.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c098eb035d38d45f"}},{"id":"qx-c1-023","clusterId":"C","werkstueckRef":"C.1.6","stufe":3,"question":"Drei Personen äußern sich zu Außerirdischen. Wer überschreitet die Grenze von legitimer Spekulation zur Pseudowissenschaft?","options":["Person A, denn sie setzt schon voraus, was sie erst zeigen will, und sucht dann nur noch nach Bestätigung dafür.","Person B, denn sie stellt einen Besuch als Tatsache hin und ersetzt Belege und Mechanismus durch „sicher irgendwie“.","Person A, denn sie hält außerirdisches Leben bereits für bewiesen, nur weil es bei so vielen Sternen wahrscheinlich sei.","Person C, denn sie beruft sich auf Science-Fiction als Beleg und gibt ein Gedankenspiel als gesichertes Wissen aus."],"correctIndex":1,"explanation":"Eine offene Frage zu stellen und danach zu suchen, ist legitim: Person A behauptet nichts als Tatsache, sondern prüft, und auch Person C kennzeichnet ihr Gedankenexperiment offen als Spekulation ohne Beleg. Person B dagegen behauptet einen Besuch als Faktum, obwohl die Hürden gewaltig sind: Selbst mit der Geschwindigkeit der schnellsten Sonde (Parker Solar Probe) bräuchte man rund 6.600 Jahre bis zum nächsten Stern, und nichts mit Masse erreicht Lichtgeschwindigkeit. „Sicher irgendwie gelöst“ bietet keinen plausiblen Mechanismus und ist ein klassisches Warnsignal (Argument aus Unwissenheit). Die Grenze verläuft also nicht beim Thema, sondern bei der Art, wie mit Belegen umgegangen wird. Zirkelschlüsse und Bestätigungssuche sind echte Fehler, aber Person A formuliert nur eine Erwartung und sucht mit offenem Ausgang. Auch einen Beweis für außerirdisches Leben behauptet sie nicht, sie sagt lediglich, es wäre überraschend. Und Person C beruft sich nicht auf Science-Fiction als Beleg, sie nennt Warp-Antriebe ausdrücklich Science-Fiction ohne Beleg.","coreRule":"⚡ Suchen und Fragen ist Wissenschaft, Behaupten ohne Beleg ist Pseudowissenschaft.","beleg":"Werkstück C.1.6 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"A: „Es wäre überraschend, wenn bei Hunderten Milliarden Sternen nur wir Leben hervorgebracht hätten. Deshalb suche ich mit Radioteleskopen nach Signalen.“ B: „Eine Zivilisation, die Millionen Jahre älter ist als wir, hat die Entfernungen sicher irgendwie überwunden. Also waren Außerirdische hier und haben die Pyramiden gebaut.“ C: „Warp-Antriebe sind bisher reine Science-Fiction. Als Gedankenexperiment finde ich sie trotzdem spannend, auch wenn es keinen Beleg gibt.“","quote":"","quoteLabel":"","kurz":"Person B überschreitet die Grenze: Sie behauptet einen Besuch als Tatsache und ersetzt Belege durch „sicher irgendwie“. Offenes Suchen (A) oder offen gekennzeichnetes Spekulieren (C) ist dagegen legitim; entscheidend ist der Umgang mit Belegen.","prueffrage":"Was genau behauptet Person A über außerirdisches Leben, und was tut sie, um es herauszufinden?","rueckmeldung":[{"option":0,"text":"Zirkelschlüsse und einseitige Bestätigungssuche sind echte Fehler. Person A sagt aber nur, etwas wäre überraschend, und lässt offen, was die Suche ergibt. Sie setzt ihr Ergebnis nicht voraus."},{"option":2,"text":"Eine Wahrscheinlichkeitsüberlegung ist kein Beweis, und A behauptet auch keinen. Sie sagt nur, es wäre überraschend, wenn wir allein wären, und prüft das mit Radioteleskopen, ergebnisoffen."},{"option":3,"text":"Science-Fiction taugt tatsächlich nicht als Beleg. Person C beruft sich aber gar nicht darauf: Sie nennt Warp-Antriebe ausdrücklich Science-Fiction, ohne Beleg, und gibt das Gedankenspiel nicht als Wissen aus."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NASA Science: Parker Solar Probe (Missionsseite)","oeffentlich":true,"url":"https://science.nasa.gov/mission/parker-solar-probe/","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax: University Physics Vol. 3, 5.9 Relativistic Energy","oeffentlich":true,"url":"https://openstax.org/books/university-physics-volume-3/pages/5-9-relativistic-energy","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (2015, überarb. 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"673079d428770049"}},{"id":"qx-c1-024","clusterId":"C","werkstueckRef":"C.1.6","stufe":4,"question":"Ein Gesprächspartner hält dagegen, dass interstellare Besuche physikalisch kaum plausibel sind. Er sagt: „Eine Zivilisation, die Millionen Jahre älter ist als wir, hat Technik wie Magie – unsere Physik gilt für sie vielleicht gar nicht.“ Welche Antwort ist die stärkste?","options":["Du bestreitest nicht, dass es solche Technik geben könnte, fragst aber, wer für die Behauptung Belege liefern muss und welche Erklärung weniger unbelegte Annahmen braucht.","Du verweist darauf, dass in der Wissenschaft schon manches zunächst Unmögliche später bestätigt wurde, und nimmst den Einwand deshalb ernst, ohne Belege dafür zu verlangen.","Du fragst nach den Beweggründen deines Gegenübers: Wer so argumentiert, will meist nur recht behalten, also muss man den Einwand nicht ernster prüfen.","Du betonst, dass die bekannten Naturgesetze durch unzählige Experimente bestätigt sind, und schließt daraus, dass sich solche Wundertechnik ausschließen lässt."],"correctIndex":0,"explanation":"Der Einwand schließt jede Gegenprobe im Voraus aus: Gilt die bekannte Physik „vielleicht gar nicht“, lässt sich mit nichts mehr argumentieren. Zwei Werkzeuge greifen hier. Erstens die Beweislast: Wer eine außergewöhnliche Behauptung aufstellt, muss sie belegen, und ein Gegner muss nicht das Unmögliche widerlegen. Zweitens Ockhams Rasiermesser: Solange keine außergewöhnlichen Beweise vorliegen, ist die Erklärung vorzuziehen, die mit weniger unbelegten Annahmen auskommt. „Menschen haben es selbst gebaut“ braucht keine zusätzliche, unbelegte Wundertechnik. Dass sich schon manches Unmögliche später bestätigt hat, stimmt, ersetzt aber keine Belege für genau diesen Einwand. Nach den Beweggründen des Gegenübers zu fragen trifft die Person statt der Behauptung und prüft nichts. Dass die bekannten Naturgesetze gut belegt sind, spricht gegen Wundertechnik, schließt sie aber nicht aus, denn auch „unmöglich“ ist eine Behauptung, die sich nicht belegen lässt.","coreRule":"⚡ Wer „Magie-Technik“ behauptet, trägt die Beweislast – und bis Belege kommen, gewinnt die Erklärung mit den wenigsten unbelegten Annahmen.","beleg":"Werkstück C.1.6 (Werkbank-Frage; verlinkt auf Werkstück A.4 Beweislast und A.1.1 Ockhams Rasiermesser)","status":"entwurf","scenario":"In einer Diskussion über angebliche Besuche Außerirdischer weist jemand auf Sternentfernungen und die Lichtgeschwindigkeit hin.","kurz":"Der Einwand schließt jede Gegenprobe aus, deshalb gilt: Wer Wundertechnik behauptet, muss sie belegen. Ohne Belege ist die Erklärung vorzuziehen, die mit weniger unbelegten Annahmen auskommt. Der Fehler wäre, das Unmögliche widerlegen zu wollen.","prueffrage":"Ließe sich der Einwand „unsere Physik gilt vielleicht gar nicht“ durch irgendeine Beobachtung je widerlegen?","rueckmeldung":[{"option":1,"text":"Dass sich manches Unmögliche später bestätigt hat, stimmt. Für genau diesen Einwand liegen aber keine Belege vor, und ohne sie nimmt man ihn nur ernst, statt ihn zu prüfen. So rutscht die Beweislast auf die Gegenseite."},{"option":2,"text":"Die Frage nach den Beweggründen klingt wie Skepsis, trifft aber die Person statt der Behauptung. Auch ein Einwand aus fragwürdigen Motiven kann stimmen, und geprüft ist damit noch nichts."},{"option":3,"text":"Gut bestätigte Naturgesetze sprechen tatsächlich gegen Wundertechnik. Ausschließen lässt sie sich damit aber nicht, denn auch „unmöglich“ ist eine Behauptung, die sich nicht belegen lässt. Eine vorsichtigere Aussage wäre hier stärker."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (2004, überarb. 2022)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (2015, überarb. 2024), Abschn. 3.6","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"83e40b6fe49c32eb"}},{"id":"qx-c1-025","clusterId":"C","werkstueckRef":"C.2.1","stufe":1,"question":"Mit welchem Einwand lässt sich die Behauptung des Verkäufers am besten prüfen?","options":["Stoffe bestehen aus einzelnen Teilchen. Nach genügend Verdünnungsschritten ist statistisch kein Teilchen des Wirkstoffs mehr enthalten, und was fehlt, kann nicht wirken.","Je stärker man verdünnt, desto gleichmäßiger verteilen sich die Teilchen im Lösungsmittel. Die Menge sinkt, aber die Wirkung des Stoffes bleibt dabei erhalten.","Je stärker man verdünnt, desto weniger Teilchen sind noch enthalten. Dafür entfaltet jedes einzelne Teilchen eine größere Wirkung als in der Ausgangslösung.","Eine Verdünnung wirkt nur dann, wenn sie in einem sauberen Labor erfolgt ist. Verunreinigungen schwächen die Wirkung des Wirkstoffs sonst deutlich ab."],"correctIndex":0,"explanation":"Materie ist nicht unendlich teilbar: Man kann einen Zuckerwürfel nicht beliebig oft halbieren, irgendwann bleibt ein einzelnes Zuckermolekül. Weil jeder Verdünnungsschritt die Teilchenzahl senkt, ist irgendwann im Schnitt weniger als ein Teilchen übrig; bei Schritten von 1 zu 100 ist diese Grenze schon nach etwa zwölf Schritten erreicht (Verdünnung 1 zu 10²⁴). Bei 30 Schritten (Verdünnung 1 zu 10⁶⁰) ist sie weit überschritten: Selbst bei einer Ausgangslösung von einem Mol pro Liter, also rund 6 × 10²³ Molekülen, blieben im Mittel nur etwa 6 × 10⁻³⁷ Moleküle pro Liter. Die Behauptung „je verdünnter, desto stärker“ kehrt die Dosis-Wirkungs-Beziehung um und ist ein klares Warnsignal. Wer sie trotzdem aufrechterhält, muss eine nicht stoffliche Ursache behaupten und dafür eigene Belege liefern.","coreRule":"⚡ Materie besteht aus Teilchen. Wer immer weiter verdünnt, landet irgendwann bei null Teilchen – und was nicht mehr enthalten ist, kann nicht wirken.","beleg":"Werkstück C.2.1 (Kernidee; Avogadro-Grenze; Red Flags; Fußnoten gl-c-avogadro, gl-c-c30). Frage zur Denkaufgabe umgebaut: Behauptung prüfen statt Definition abfragen.","status":"entwurf","scenario":"Ein Verkäufer bietet ein Mittel an, bei dem ein Wirkstoff 30-mal hintereinander im Verhältnis 1 zu 100 verdünnt wurde. Er sagt: „Je öfter man verdünnt, desto stärker wirkt es. Verdünnen kann man schließlich unendlich weit.“","kurz":"Stoffe bestehen aus Teilchen, und jede Verdünnung senkt deren Zahl. Bei 30 Schritten im Verhältnis 1 zu 100 ist im Schnitt kein einziges Teilchen mehr übrig. Der Fehler liegt darin, Verdünnung wie ein stufenloses Verteilen zu denken, das nie endet.","prueffrage":"Wie viele Teilchen des Wirkstoffs wären nach 30 solchen Schritten im Mittel in einem Liter noch enthalten?","rueckmeldung":[{"option":1,"text":"Gleichmäßiges Verteilen klingt, als bliebe vom Stoff überall ein wenig erhalten. Mit jedem Schritt sinkt aber die Zahl der Teilchen, bis im Mittel keines mehr übrig ist, und was fehlt, kann nicht wirken."},{"option":2,"text":"Dass die Teilchenzahl sinkt, stimmt. Ein einzelnes Molekül bleibt aber dasselbe, ob viel oder wenig Wasser es umgibt; weniger Stoff bedeutet in der Regel weniger Wirkung, nicht mehr."},{"option":3,"text":"Saubere Arbeit ist sinnvoll, trifft hier aber nicht den Kern. Selbst im reinsten Labor ist nach so vielen Schritten vom Wirkstoff nichts mehr übrig; die Frage ist die Teilchenzahl, nicht Verunreinigung."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"daten","kurz":"NIST CODATA: Avogadro constant","oeffentlich":true,"url":"https://physics.nist.gov/cgi-bin/cuu/Value?na","abruf":"2026-10-12"},{"typ":"url","kurz":"EASAC (2017): Homeopathic products and practices","oeffentlich":true,"url":"https://www.interacademies.org/sites/default/files/2020-04/easac_homepathy_statement_web_final.pdf","seite":"5","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7b2f10a28e0d2157"}},{"id":"qx-c1-026","clusterId":"C","werkstueckRef":"C.2.1","stufe":2,"question":"Ein Anbieter wirbt: „Unser Mittel in C30 enthält die volle Kraft der Ausgangssubstanz.“ C30 bedeutet: 30 Verdünnungsschritte im Verhältnis 1 zu 100, also insgesamt 1 zu 10⁶⁰. Ein Mol (ca. 6 × 10²³ Moleküle) der Ausgangssubstanz steckt in einem Liter Urtinktur. Du prüfst das Versprechen mit einer Überschlagsrechnung: Wie viel Lösung müsstest du einnehmen, um mit etwa 50 % Chance ein einziges Molekül der Ausgangssubstanz zu erwischen?","options":["Ein großes Schwimmbecken mit einigen Millionen Litern – die Verdünnung beträgt nur 10³⁰, danach steckt im Schnitt ein Molekül in dieser Menge.","Schon ein einziger Tropfen – 30 Schritte im Verhältnis 1 zu 100 verdünnen nur 30 × 100 = 3000-fach, also bleiben unzählige Moleküle übrig.","Eine Kugel mit mehreren hundert Lichtjahren Radius – bei einer Verdünnung von 10⁶⁰ braucht man für ein Molekül ebenso viele Liter Lösung.","Eine Kugel mit dem Durchmesser des Abstands Erde–Sonne, also rund 150 Millionen Kilometer – unvorstellbar viel Lösung für ein einzelnes Molekül."],"correctIndex":3,"explanation":"Rechne in Größenordnungen: Ein Liter Urtinktur enthält etwa 6 × 10²³ Moleküle. Nach der Verdünnung um den Faktor 10⁶⁰ bleiben im Mittel rund 6 × 10⁻³⁷ Moleküle pro Liter. Für ein einziges erwartetes Molekül brauchst du also etwa 1,7 × 10³⁶ Liter, das ist eine Kugel mit rund 1,5 × 10¹¹ Metern Durchmesser, ungefähr der Abstand zwischen Erde und Sonne. Für eine 50-Prozent-Chance genügt etwas weniger, rund das 0,9-Fache dieses Durchmessers; bei einer schwächeren Urtinktur würde die Kugel noch größer. Der Denkfehler dahinter ist, sich bei Verdünnungen von 10⁶⁰ Vorstellbares einzureden, statt nachzurechnen. Die Rechnung zeigt: In einer üblichen Dosis ist nichts von der Ursubstanz zu erwarten, das Werbeversprechen von der „vollen Kraft“ ist stofflich leer. Wer nur 10³⁰ rechnet, landet bei einem Schwimmbecken, hier sind es aber 30 Schritte zu je 1 zu 100, also 10⁶⁰. Verdünnungsschritte vervielfachen sich, sie addieren sich nicht, deshalb stimmt auch die Rechnung mit 3000-fach nicht. Und wer die rund 6 × 10²³ Moleküle pro Liter vergisst, kommt auf eine Kugel von hunderten Lichtjahren, die viel zu groß ist.","coreRule":"⚡ Bei extremen Verdünnungen gilt: erst die Teilchenzahl überschlagen, dann über die Wirkung reden. Ab etwa 1 zu 10²⁴ ist pro Mol statistisch nur noch rund ein Molekül der Ausgangssubstanz zu erwarten; darüber praktisch keines mehr.","beleg":"Werkstück C.2.1 (Kontext & Tiefe, „Die mathematische Realität der Homöopathie“); Fn. gl-c-c30 (Überschlag für eine einmolare Urtinktur)","status":"entwurf","scenario":"","kurz":"Nach 10⁶⁰-facher Verdünnung bleiben von etwa 6 × 10²³ Molekülen pro Liter nur noch rund 6 × 10⁻³⁷ übrig. Für ein einziges Molekül bräuchte man eine Lösungskugel von Erde–Sonne-Größe. Schätzen ohne Nachrechnen führt hier in die Irre.","prueffrage":"Wie viele Moleküle bleiben im Mittel in einem Liter, wenn 6 × 10²³ Moleküle um den Faktor 10⁶⁰ verdünnt werden?","rueckmeldung":[{"option":0,"text":"Die Überlegung „im Schnitt ein Molekül“ stimmt, doch der Exponent nicht: 30 Schritte zu je 1 zu 100 ergeben 10⁶⁰, nicht 10³⁰. Mit der richtigen Verdünnung wird die nötige Menge um ein Vielfaches größer als ein Schwimmbecken."},{"option":1,"text":"Die Schritte zu addieren, liegt nahe, wenn man an „30 mal etwas tun“ denkt. Jeder Schritt verdünnt aber den Rest erneut um den Faktor 100, die Faktoren multiplizieren sich zu 10⁶⁰. Deshalb bleiben keineswegs unzählige Moleküle übrig."},{"option":2,"text":"Die Verdünnung von 10⁶⁰ und die riesige Menge sind richtig erkannt. Es fehlt der Ausgangswert: Schon ein Liter Urtinktur enthält rund 6 × 10²³ Moleküle. Rechnet man das gegen, schrumpft die nötige Kugel auf etwa Erde–Sonne-Größe."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"daten","kurz":"NIST CODATA: Avogadro constant","oeffentlich":true,"url":"https://physics.nist.gov/cgi-bin/cuu/Value?na","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"83cbf8a7bd39ba2d"}},{"id":"qx-c1-027","clusterId":"C","werkstueckRef":"C.2.1","stufe":3,"question":"Ein Homöopath sagt: „Du denkst zu materialistisch – es geht um eine geistartige Information, die beim Potenzieren auf den Trägerstoff übergeht.“ Du willst im Gespräch bleiben und nichts behaupten, was du selbst nicht belegen kannst. Welche Antwort ist am sinnvollsten?","options":["Du hältst dagegen, dass es geistartige Information nicht gibt, weil in der Physik jede Wirkung einen stofflichen Träger braucht.","Du fragst ihn, wie sich die Wirkung dieser Information von der Wirkung des bloßen Glaubens daran unterscheiden ließe.","Du fragst, wie viele seiner Patienten sich nach der Behandlung besser fühlen, und nimmst diese Zahl als Maß für die Wirkung.","Du verweist darauf, dass die große Mehrheit der Fachleute seine Sicht ablehnt, und siehst die Frage damit als erledigt an."],"correctIndex":1,"explanation":"Am sinnvollsten ist es, nicht die Existenz der „geistartigen Information“ zu widerlegen, sondern zu fragen, wie sich ihre Wirkung von der reinen Wirkung des Glaubens daran unterscheiden lässt. Dafür dienen der Placebo-Effekt und die Hierarchie der Evidenz: Eine behauptete Wirkung zählt erst, wenn sie sich vom Glauben daran trennen lässt. So gibst du dem Gegenüber die Chance, seine Behauptung testbar zu machen, und das Gespräch bleibt offen. Dass eine Wirkung nicht über den Glauben hinausgeht, folgt aus einem Test, nicht aus einer Vorannahme. Zu behaupten, geistartige Information gebe es nicht, wäre selbst eine Behauptung, die du nicht belegen kannst. Dass sich Patienten besser fühlen, lässt sich auch durch Erwartung und natürlichen Verlauf erklären und trennt die Wirkung nicht vom Glauben. Und die Meinung der Mehrheit der Fachleute kann ein Hinweis sein, ist aber kein Test seiner Behauptung.","coreRule":"⚡ Frag nicht „Beweise, dass es sie nicht gibt“, sondern „Woran würden wir eine Wirkung erkennen, und wie unterscheiden wir sie vom Glauben daran?“","beleg":"Werkstück C.2.1 (Werkbank-Frage; Anwendung & Relevanz, „Bei anderen ‚Informationsmedizin‘-Systemen“)","status":"entwurf","scenario":"","kurz":"Statt die „geistartige Information“ zu bestreiten, fragst du, wie sich ihre Wirkung vom bloßen Glauben trennen ließe. Das macht die Behauptung testbar und hält das Gespräch offen; „gibt es nicht“ wäre selbst unbelegt.","prueffrage":"Könnte irgendeine Beobachtung den Homöopathen davon überzeugen, dass es die „geistartige Information“ nicht gibt?","rueckmeldung":[{"option":0,"text":"Dass sich eine Wirkung ohne messbaren Träger schwer stützen lässt, ist ein berechtigter Gedanke. „Gibt es nicht“ ist aber selbst eine Behauptung, die du nicht belegen kannst, und der Satz über stoffliche Träger ist eine Vorannahme, die das Gespräch schließt."},{"option":2,"text":"Eine Zahl wirkt konkret und prüfbar, und viele Patienten fühlen sich tatsächlich besser. Das lässt sich aber auch durch Erwartung und natürlichen Verlauf erklären und trennt die Wirkung deshalb nicht vom Glauben daran."},{"option":3,"text":"Die Einschätzung vieler Fachleute kann ein Hinweis sein. Sie ersetzt aber keinen Test seiner Behauptung, und die Frage als erledigt zu betrachten, beendet das Gespräch, statt die Behauptung prüfbar zu machen."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"EASAC (2017): Homeopathic products and practices: assessing the evidence and ensuring consistency in regulating medical claims in the EU","oeffentlich":true,"url":"https://www.interacademies.org/sites/default/files/2020-04/easac_homepathy_statement_web_final.pdf","seite":"5","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ad8f56782ea46517"}},{"id":"qx-c1-028","clusterId":"C","werkstueckRef":"C.2.1","stufe":4,"question":"Ein Anbieter verspricht Heilung durch „digital übertragene Schwingungsinformationen“, ganz ohne Wirkstoff. Mit welchem Einwand kannst du diese Behauptung am besten prüfen?","options":["Dass etwas natürlich ist, macht es noch nicht heilsam, denn der Verweis auf Natürlichkeit ist kein Beleg für eine Wirkung.","Eine Behauptung, die sich jeder Beobachtung nachträglich anpassen lässt, ist nicht widerlegbar und damit wertlos als Erklärung.","Information braucht einen physikalischen Träger, und ohne Teilchen der Substanz im Wasser gibt es nichts, was wirken könnte.","Wer ein Gerät verkauft, hat ein Geschäftsinteresse an der Wirkung, deshalb ist seine Behauptung mit besonderer Vorsicht zu behandeln."],"correctIndex":2,"explanation":"Information braucht einen physikalischen Träger. Eine Behauptung, die Wirkung ohne jeden Wirkstoff verspricht, muss deshalb erklären können, was genau übertragen wird und woran es im Wasser steckt. Ohne Moleküle der Substanz im Wasser gibt es keinen Träger, der etwas übertragen könnte. Dazu kommt: Materie ist nicht unendlich teilbar. Jenseits von etwa C12 ist statistisch kein einziges Molekül der Ausgangssubstanz mehr in der Lösung, und dann bleibt nichts übrig, was wirken könnte. Wer „Information“ ohne Träger behauptet, verschiebt die Frage nur, statt sie zu beantworten. Dass Natürliches nicht automatisch heilsam ist, stimmt zwar, doch die Werbung beruft sich gar nicht auf Natürlichkeit, sondern auf eine technische Übertragung. Dass sich unwiderlegbare Behauptungen nicht prüfen lassen, stimmt ebenfalls, trifft hier aber nicht zu, denn die Werbung nennt einen konkreten Weg und passt sich keiner Beobachtung nachträglich an. Das Geschäftsinteresse des Anbieters ist ein Grund für Vorsicht, prüft aber die Behauptung selbst nicht.","coreRule":"⚡ Ohne Träger keine Information, ohne Teilchen keine Wirkung.","beleg":"Werkstück C.2.1 (Anwendung & Relevanz, „Bei anderen ‚Informationsmedizin‘-Systemen“; Red Flags)","status":"entwurf","scenario":"In der Werbung heißt es: „Unser Gerät überträgt die Heilinformation der Substanz digital auf Ihr Trinkwasser. Es ist kein Wirkstoff nötig, die Information genügt.“","kurz":"Information braucht einen physikalischen Träger. Ohne Moleküle der Substanz im Wasser fehlt, was etwas übertragen könnte. Der Fehler wäre, bei „digital“ und „Information“ nicht nachzufragen, woran sie im Wasser eigentlich steckt.","prueffrage":"Würde sich am Wasser etwas ändern, wenn das Gerät statt der Heilinformation eine leere Datei überträgt, und wie ließe sich das prüfen?","rueckmeldung":[{"option":0,"text":"Dass Natürliches nicht automatisch heilsam ist, stimmt. Die Werbung beruft sich aber gar nicht auf Natürlichkeit, sondern auf eine technische Übertragung. Der Einwand trifft die Behauptung daher nicht."},{"option":1,"text":"Unwiderlegbare Behauptungen sind tatsächlich als Erklärung wertlos. Hier trifft das aber nicht zu: Die Werbung nennt einen konkreten Weg und biegt sich nicht nachträglich jeder Beobachtung zurecht. Der Einwand führt an der Behauptung vorbei."},{"option":3,"text":"Geschäftsinteresse ist ein guter Grund zur Vorsicht. Es sagt aber nur etwas über die Quelle und prüft die Behauptung selbst nicht: Ob etwas wirken kann, ließe sich auch bei einem Anbieter ohne Eigeninteresse fragen."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"EASAC (2017): Homeopathic products and practices","oeffentlich":true,"url":"https://www.interacademies.org/sites/default/files/2020-04/easac_homepathy_statement_web_final.pdf","seite":"5","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7df80e0c9fba4bbd"}},{"id":"qx-c1-029","clusterId":"C","werkstueckRef":"C.2.2","stufe":1,"question":"Was ist an der Aussage der Mitbewohnerin fehlerhaft, und was ist chemisch tatsächlich passiert?","scenario":"Jemand toastet eine Scheibe Brot zu lange. Sie wird schwarz und knusprig, es steigt Rauch auf, und die verkohlte Scheibe wiegt deutlich weniger als vorher. Eine Mitbewohnerin meint: „Beim Verbrennen wird Materie zerstört, sonst müsste die Scheibe ja gleich viel wiegen.“","options":["Die Hitze hat nur das Wasser aus dem Brot verdampft, die Kruste ist unverändertes Brot, das lediglich dunkler wurde, und das Fehlende ist allein das verdunstete Wasser.","Ein kleiner Teil der Masse des Brots wurde nach E = mc² in Wärmeenergie umgewandelt, und dieser Masseverlust ist der Grund, warum die Scheibe auf der Waage leichter ist.","Die Hitze hat die Moleküle des Brots nur auseinandergetrieben und teils verdampft; beim Abkühlen ordnen sich dieselben Moleküle wieder an, es war ein rein physikalischer Vorgang.","Die Bindungen im Brot sind aufgebrochen und dieselben Atome haben sich neu angeordnet, zum Teil zu Kruste, zum Teil zu Gasen wie CO₂ und Wasserdampf, die entwichen sind."],"correctIndex":3,"explanation":"Die Mitbewohnerin schließt vom Gewichtsverlust auf zerstörte Materie. Dieser Schluss trägt nicht: Die Scheibe wiegt weniger, weil Wasserdampf, Kohlendioxid und andere Gase im Rauch entweichen. Die Hitze bricht die Bindungen der Kohlenhydrat-Moleküle auf, und die Atome ordnen sich neu an: Ein Großteil des Kohlenstoffs bleibt als schwarze Kruste zurück, Wasserstoff, Sauerstoff und ein Teil des Kohlenstoffs entweichen als Gase; Sauerstoff steckt dafür schon reichlich in den Kohlenhydraten, ein Teil kann auch aus der Luft kommen. Bei einer chemischen Reaktion gehen keine Atome verloren und es kommen keine hinzu, nur ihre Anordnung ändert sich; Elemente wandeln sich erst bei Kernreaktionen um. Dass Wasser verdunstet, stimmt, erklärt aber nicht die schwarze, spröde Kruste mit ganz neuen Eigenschaften. Die Gleichwertigkeit von Masse und Energie gilt, doch der Massenunterschied bei chemischen Reaktionen liegt weit unter dem, was eine Waage zeigt. Ein rein physikalischer Vorgang wie Verdampfen lässt sich beim Abkühlen umkehren, verkohltes Brot wird dagegen nie wieder zu Brot.","coreRule":"⚡ Chemie ordnet Atome neu an: Atome entstehen nicht und verschwinden nicht. Fehlt Masse, sucht man die unsichtbaren Produkte, statt Zerstörung anzunehmen.","beleg":"Werkstück C.2.2 (Das verbrannte Brot; Kernidee; Kontext & Tiefe, „Materie bleibt erhalten“)","status":"entwurf","kurz":"Die Scheibe wird leichter, weil Gase wie Wasserdampf und CO₂ im Rauch entweichen, nicht weil Materie verschwindet. Die Hitze bricht Bindungen auf und die Atome ordnen sich neu, es gehen keine verloren.","prueffrage":"Was geschieht mit allem, was beim Toasten als Rauch oder Dampf aufsteigt, und wo würdest du es mitwiegen?","rueckmeldung":[{"option":0,"text":"Wasser verdampft beim Toasten tatsächlich, und das gehört zum Gewichtsverlust. Die schwarze, spröde Kruste ist aber kein unverändertes Brot, sondern ein neuer Stoff, und auch andere Gase im Rauch tragen Masse davon."},{"option":1,"text":"Masse und Energie sind tatsächlich gleichwertig. Bei chemischen Reaktionen ist der dadurch bedingte Massenunterschied aber weit kleiner, als eine Waage anzeigen könnte; den sichtbaren Verlust erklären die entweichenden Gase."},{"option":2,"text":"Das Verdampfen von Wasser ist ein rein physikalischer Vorgang und lässt sich beim Abkühlen umkehren. Beim Toasten brechen aber Bindungen auf und die Atome ordnen sich neu, und verkohltes Brot wird nie wieder zu Brot."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax (Flowers u. a.): Chemistry 2e, Abschnitt 2.1 „Early Ideas in Atomic Theory“","oeffentlich":true,"url":"https://openstax.org/books/chemistry-2e/pages/2-1-early-ideas-in-atomic-theory","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f9e277be8ccb6b1d"}},{"id":"qx-c1-030","clusterId":"C","werkstueckRef":"C.2.2","stufe":2,"question":"Welche Schlussfolgerung ist die sparsamste?","options":["Die Atome sind in beiden Stoffen unterschiedlich angeordnet; diese Anordnung bestimmt die Eigenschaften, ein Widerspruch entsteht nicht.","Die Proben enthalten verschieden viele Verunreinigungen; diese bestimmen die Eigenschaften, ein Widerspruch entsteht nicht.","Die Atome sind unterschiedliche Isotope des Kohlenstoffs; diese Atomsorten bestimmen die Eigenschaften, ein Widerspruch entsteht nicht.","Die Stoffe liegen in verschiedenen Aggregatzuständen vor; dieser Zustand bestimmt die Eigenschaften, ein Widerspruch entsteht nicht."],"correctIndex":0,"explanation":"Der scheinbare Widerspruch entsteht nur durch die versteckte Annahme, dass dieselben Atome immer dieselben Eigenschaften ergeben müssten. Doch Graphit und Diamant bestehen beide aus reinem Kohlenstoff, und weil die Atome unterschiedlich angeordnet sind, ist das eine ein weiches Schmiermittel und das andere eines der härtesten bekannten Materialien. Die Erklärung kommt ohne zusätzliche Annahmen aus. Verunreinigungen können Eigenschaften verändern, doch die Chemikerin sagt ausdrücklich, beide Stoffe bestünden aus reinem Kohlenstoff. Isotope unterscheiden sich nur in der Zahl der Neutronen und verhalten sich chemisch nahezu gleich, erklären also keinen so großen Unterschied. Aggregatzustände ändern Eigenschaften zwar stark, aber beide Stoffe sind fest.","coreRule":"⚡ Nicht nur woraus ein Stoff besteht, sondern wie die Atome angeordnet sind, entscheidet über seine Eigenschaften.","beleg":"Werkstück C.2.2 (Kontext & Tiefe, „Struktur bestimmt Funktion“)","status":"entwurf","scenario":"Eine Chemikerin sagt: „Graphit und Diamant bestehen beide aus reinem Kohlenstoff. Trotzdem ist der eine ein weiches Schmiermittel, der andere eines der härtesten bekannten Materialien.“ Ein Zuhörer meint, das sei ein Widerspruch.","kurz":"Der Widerspruch entsteht nur, wenn man annimmt, dieselben Atome müssten immer dieselben Eigenschaften ergeben. Die Anordnung der Atome unterscheidet sich, und das erklärt den Unterschied ohne weitere Annahmen.","prueffrage":"Was ist über beide Stoffe gesichert, und wie viel muss man darüber hinaus annehmen, um ihren Unterschied zu erklären?","rueckmeldung":[{"option":1,"text":"Verunreinigungen können Eigenschaften tatsächlich verändern, deshalb wirkt das plausibel. Die Chemikerin spricht aber ausdrücklich von reinem Kohlenstoff, also würdest du eine Annahme einführen, die ihrer Aussage widerspricht."},{"option":2,"text":"Isotope sind Atome desselben Elements mit unterschiedlich vielen Neutronen und verhalten sich chemisch nahezu gleich. Einen so großen Unterschied zwischen Schmiermittel und härtestem Material erklären sie nicht, und im Szenario steht auch nichts von ihnen."},{"option":3,"text":"Aggregatzustände verändern Eigenschaften tatsächlich stark, daher klingt das schlüssig. Hier sind aber beide Stoffe fest, der Zustand unterscheidet sich also gar nicht und kann den Unterschied nicht erklären."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"LibreTexts Chemistry: „14.04: Allotropes of Carbon“ (Map: Inorganic Chemistry, Housecroft)","oeffentlich":true,"url":"https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Map:_Inorganic_Chemistry_(Housecroft)/14:_The_Group_14_Elements/14.04:_Allotropes_of_Carbon","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"77b8932924648cc2"}},{"id":"qx-c1-031","clusterId":"C","werkstueckRef":"C.2.2","stufe":3,"question":"Welchen Denkfehler macht diese Person?","options":["Die Person vergleicht Herkunft statt Struktur: Glutamat kommt als Aminosäure in Tomaten und Parmesan natürlich vor, und identische Moleküle reagieren im Körper gleich.","Die Person beruft sich auf Autoritäten statt auf Belege: Sie verweist auf angeblich bekannte Fachleute, die MSG ablehnen und Tomaten empfehlen würden.","Die Person schließt von zeitlicher Folge auf Ursache: Weil ihr nach einem Essen mit MSG einmal übel wurde, hält sie den Stoff für den Auslöser ihrer Beschwerden.","Die Person bekämpft ein Zerrbild der Gegenseite: Sie unterstellt MSG-Befürwortern, jeden natürlichen Stoff für schädlich zu halten, und widerlegt dann diese Unterstellung."],"correctIndex":0,"explanation":"„Natürlich“ und „synthetisch“ beschreiben die Herkunft eines Stoffes, nicht das Molekül selbst. Glutamat ist eine Aminosäure, die in reifen Tomaten und in Parmesan reichlich frei vorkommt und dort für den Umami-Geschmack sorgt. MSG ist das Natriumsalz der Glutaminsäure: Gelöst in Wasser oder Speichel liegt dasselbe Glutamat vor wie in der Tomate, dazu Natrium wie aus Kochsalz. Für die Wirkung im Körper zählt die Struktur, nicht die Herkunft, ähnlich wie bei Vitamin C aus der Orange und aus dem Labor. Wer das eine meidet und das andere genießt, urteilt nach dem Etikett statt nach dem Stoff. Andere Denkfehler gibt es durchaus, sie liegen hier aber nicht vor: Die Person beruft sich auf keine Fachleute. Von einem eigenen Erlebnis nach dem Essen ist keine Rede, also wird auch nicht von der Folge auf die Ursache geschlossen. Und eine Gegenseite, deren Position sie verzerren könnte, kommt in ihrer Aussage nicht vor.","coreRule":"⚡ „Natürlich“ oder „synthetisch“ sagt nichts über das Molekül – seine Struktur zählt.","beleg":"Werkstück C.2.2 (Werkbank-Frage; Anwendung & Relevanz, „Natürlich vs. Chemisch/Synthetisch“)","status":"entwurf","scenario":"Jemand sagt: „Ich vermeide Mononatriumglutamat (MSG) in meinem Essen, weil es unnatürlich und schädlich ist. Dafür esse ich gern Tomaten und Parmesan, denn die sind natürlich und gesund.“","quote":"","quoteLabel":"","kurz":"Ob ein Stoff natürlich oder synthetisch ist, sagt etwas über seine Herkunft, nicht über das Molekül. Glutamat in MSG ist dasselbe wie in Tomate und Parmesan, daher gilt dort wie hier: Für die Wirkung zählt die Struktur, nicht das Etikett.","prueffrage":"Was steckt in einer reifen Tomate oder im Parmesan chemisch alles drin, und worauf geht ihr herzhafter Geschmack zurück?","rueckmeldung":[{"option":1,"text":"Pauschale Verweise auf „Fachleute“ sind tatsächlich ein häufiger Fehler. Hier tritt aber niemand als Gewährsmann auf: Die Person begründet allein mit „natürlich“ und „unnatürlich“, und genau dort liegt der Schwachpunkt."},{"option":2,"text":"Eine Beschwerde nach einem bestimmten Essen kann dazu verleiten, den Stoff als Auslöser zu sehen. Von einem solchen Erlebnis ist in der Aussage aber keine Rede, sie urteilt grundsätzlich über den Stoff, nicht nach einer einzelnen Erfahrung."},{"option":3,"text":"Ein Zerrbild der Gegenseite wäre ein echter Fehler, setzt aber eine Gegenseite voraus. In der Aussage kommt niemand vor, dessen Position verzerrt würde. Die Person legt nur ihre eigene Haltung dar, und die stützt sich auf ein Etikett."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"U.S. Food and Drug Administration: „Questions and Answers on Monosodium glutamate (MSG)“","oeffentlich":true,"url":"https://www.fda.gov/food/food-additives-petitions/questions-and-answers-monosodium-glutamate-msg","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"16ae39a6343db90b"}},{"id":"qx-c1-032","clusterId":"C","werkstueckRef":"C.2.2","stufe":4,"question":"Ein Anbieter behauptet, nicht näher benannte „Toxine“ lagerten sich im Körper ab, sein Präparat „ziehe sie heraus“. Welche Gegenfrage prüft diese Behauptung am besten?","options":["Welche Stoffe genau gemeint sind und welche chemische Reaktion im Körper ablaufen soll, denn jede Wirkbehauptung braucht beides.","Ob das Präparat natürlichen Ursprungs ist, denn natürliche Stoffe reagieren im Körper anders als im Labor hergestellte.","Wie viel Energie das Präparat enthält, denn nur Energie kann die Stoffe aus dem Körper austreiben.","Ob Kunden von einer Besserung berichten, denn Erfahrungsberichte gelten als sicherer Beleg für die Wirkung des Präparats."],"correctIndex":0,"explanation":"Eine Wirkbehauptung ist erst prüfbar, wenn sie benennt, welche Stoffe beteiligt sind und welche Reaktion abläuft. „Toxine“ oder „Schlacken“ ohne Stoffbenennung lassen sich weder nachweisen noch widerlegen und sind ein Warnsignal. Der Körper wandelt außerdem selbst unzählige potenziell schädliche Stoffe um: Die Leber macht sie wasserlöslich, damit sie ausgeschieden werden können. Die Herkunft („natürlich“) sagt nichts über die Reaktion, denn ein Molekül mit gleicher Struktur reagiert gleich, egal woher es stammt. Und Zufriedenheitsberichte benennen weder Stoffe noch Reaktion und beantworten deshalb nicht die Frage nach dem Wirkmechanismus.","coreRule":"⚡ Frag nach den „Lego-Steinen“: Welche Stoffe, welche Reaktion?","beleg":"Werkstück C.2.2 (Aktivierungs-Frage; Anwendung & Relevanz, „Gegen die ‚Detox‘-Mythen“; Red Flags)","status":"entwurf","kurz":"Eine Wirkbehauptung lässt sich erst prüfen, wenn sie benennt, welche Stoffe beteiligt sind und welche Reaktion ablaufen soll. „Toxine“ ohne Namen kann man weder nachweisen noch widerlegen. Gerade das macht die Behauptung verdächtig.","prueffrage":"Lässt sich die Behauptung so, wie sie dasteht, überhaupt nachmessen, und woran würdest du das festmachen?","rueckmeldung":[{"option":1,"text":"Die Herkunft eines Stoffes sagt nichts darüber, wie er im Körper reagiert: Ein Molekül mit gleicher Struktur verhält sich gleich, egal woher es stammt. Außerdem bleibt offen, welche Stoffe gemeint sind und was passieren soll."},{"option":2,"text":"Der Energiegehalt hat mit dem Entfernen von Stoffen aus dem Körper nichts zu tun, und Energie allein treibt nichts heraus. Die Frage klärt weder, welche Stoffe gemeint sind, noch, welche Reaktion ablaufen soll."},{"option":3,"text":"Berichte über eine Besserung wirken überzeugend, weil sie konkret erlebt sind. Eine Besserung kann aber auch von Erwartung oder vom natürlichen Verlauf kommen, und die Berichte nennen weder Stoffe noch Reaktion."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klein, A. V.; Kiat, H. (2015): „Detox diets for toxin elimination and weight management: a critical review of the evidence“, J Hum Nutr Diet 28(6), 675–686","oeffentlich":true,"doi":"10.1111/jhn.12286","url":"https://pubmed.ncbi.nlm.nih.gov/25522674/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f319f80cf15ee322"}},{"id":"qx-c1-033","clusterId":"C","werkstueckRef":"C.2.3","stufe":1,"question":"Ein Start-up wirbt für einen „Generator der Zukunft“: Er soll dauerhaft Strom liefern, ohne dass Brennstoff, Sonnenlicht oder Wind nötig sind, und dabei angeblich zu 100 % effizient arbeiten, also ohne jede Abwärme. Welche Einschätzung ist physikalisch korrekt?","options":["Das Versprechen „Strom ohne Energiequelle“ widerspricht der Energieerhaltung, und das Versprechen „keine Abwärme“ widerspricht dem Zweiten Hauptsatz, nach dem jede Umwandlung nutzbare Energie in Abwärme verliert.","Beide Versprechen widersprechen allein der Energieerhaltung, denn weil Energie nie verloren geht, ist auch ein Verlust durch Abwärme von vornherein ausgeschlossen.","Das Versprechen „Strom ohne Energiequelle“ widerspricht dem Zweiten Hauptsatz, das Versprechen „keine Abwärme“ widerspricht der Energieerhaltung, denn Abwärme entsteht, wenn Energie neu erzeugt wird.","Beide Versprechen widersprechen weder der Energieerhaltung noch dem Zweiten Hauptsatz, denn ein sehr gut gebauter Generator kann die Reibung so weit senken, dass wirklich kein Verlust mehr auftritt."],"correctIndex":0,"explanation":"Die beiden Versprechen sind zwei verschiedene Verstöße, wie bei einer Bank, die Geld aus dem Nichts auszahlt und jede Transaktion ohne Gebühren abwickelt. Strom ohne jede Energiequelle wäre Energie aus dem Nichts, und Energie kann weder erzeugt noch vernichtet werden (Erster Hauptsatz). Eine völlig verlustfreie Umwandlung gibt es ebenfalls nicht: Bei jedem realen Vorgang wird ein Teil der nutzbaren Energie zu Abwärme, die sich nicht vollständig zurück in Arbeit verwandeln lässt, die Entropie steigt (Zweiter Hauptsatz). Beide Aussagen sind nötig, denn die Energieerhaltung allein erklärt noch nicht, warum immer ein Teil als Abwärme „verloren“ geht. Ein seriöser Prüfschritt fragt deshalb: Woher kommt die Energie, und wohin geht die Abwärme?","coreRule":"⚡ Energie aus dem Nichts verbietet der Erste, verlustfreie Umwandlung der Zweite Hauptsatz.","beleg":"Werkstück C.2.3 (Die unmögliche Bank; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Strom ohne Quelle wäre Energie aus dem Nichts, das verbietet die Energieerhaltung. Verlustfreie Umwandlung scheitert an etwas anderem: Dass Energie erhalten bleibt, heißt nicht, dass sie nutzbar bleibt, denn bei jedem realen Vorgang wird ein Teil zu Abwärme (Zweiter Hauptsatz).","prueffrage":"Woher stammt in dieser Werbung die Energie, die als Strom herauskommt, und wo bliebe die Wärme, die jede Maschine abgibt?","rueckmeldung":[{"option":1,"text":"Dass Energie nie verloren geht, stimmt, und das widerlegt das erste Versprechen. Abwärme schließt es aber nicht aus: Sie ist erhaltene Energie, nur nicht mehr vollständig nutzbar. Warum immer ein Teil so endet, erklärt der Zweite Hauptsatz."},{"option":2,"text":"Hier sind die beiden Gesetze vertauscht: Energie aus dem Nichts verletzt die Energieerhaltung. Abwärme entsteht nicht aus neu erzeugter Energie, sondern aus vorhandener, die in eine kaum nutzbare Form übergeht; das beschreibt der Zweite Hauptsatz."},{"option":3,"text":"Bessere Bauweise senkt Reibungsverluste, das stimmt. Doch Reibung ist nur ein Verlustweg, ganz ohne Abwärme läuft kein realer Vorgang ab. Und gegen Strom ohne Quelle hilft keine Konstruktion, denn Energie lässt sich nicht erzeugen."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.1 „The First Law of Thermodynamics“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-1-the-first-law-of-thermodynamics","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.3 „Introduction to the Second Law of Thermodynamics: Heat Engines and Their Efficiency“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-3-introduction-to-the-second-law-of-thermodynamics-heat-engines-and-their-efficiency","abruf":"2026-10-12"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"dccba23870c1a2ef"}},{"id":"qx-c1-034","clusterId":"C","werkstueckRef":"C.2.3","stufe":2,"question":"Eine Freundin sagt: „Wenn ich in meinem Kamin Holz verbrenne, erzeuge ich Wärme – das ist doch Energie, die aus dem Nichts entsteht.“ Welche Antwort trifft den Denkfehler am besten?","options":["Beim Verbrennen verschwindet kein Stoff, denn aus Holz und Sauerstoff werden Asche, Rauch und Gase mit zusammen gleicher Masse.","Die Energie war schon im Holz gespeichert, denn der Baum hat per Photosynthese Sonnenlicht in chemische Energie umgewandelt.","Wärme und Temperatur sind verschiedene Dinge, denn die Temperatur sagt nur, wie heiß etwas ist, nicht wie viel Energie darin steckt.","Bei jeder Umwandlung geht nutzbare Energie in Abwärme über, denn die Entropie eines abgeschlossenen Systems nimmt nie ab."],"correctIndex":1,"explanation":"Energie kann weder erzeugt noch vernichtet werden, sie wird nur umgewandelt. Auch das Feuer erschafft nichts neu, sondern setzt chemische Energie frei, die im Holz gespeichert war; die Pflanze hat sie per Photosynthese aus Sonnenlicht gewonnen. Mehr Energie, als vorher im Holz steckte, kann deshalb beim Verbrennen nicht frei werden. Die Behauptung „Energie aus dem Nichts“ scheitert an der Frage, woher die Energie vorher kam. Die anderen Gedanken sind für sich richtig, beantworten diese Frage aber nicht: Dass kein Stoff verschwindet, betrifft die Masse und nicht die Energie. Der Unterschied zwischen Wärme und Temperatur sagt nichts über die Herkunft der Energie. Und dass bei Umwandlungen nutzbare Energie zu Abwärme wird, regelt, wie viel davon nutzbar bleibt, nicht woher sie stammt.","coreRule":"⚡ Energie entsteht nie neu – frage immer: Woher kam sie vorher?","beleg":"Werkstück C.2.3 (Schmiede-Übung „Der persönliche Energie-Audit“; Kontext & Tiefe: Erster Hauptsatz)","status":"entwurf","scenario":"","kurz":"Das Feuer erschafft keine Energie, es setzt frei, was schon im Holz steckte: chemische Energie, die der Baum aus Sonnenlicht gewonnen hat. „Aus dem Nichts“ scheitert an der Frage, woher die Energie vorher kam.","prueffrage":"Was war mit dieser Energie, bevor das Holz im Kamin lag, und wo steckte sie dann?","rueckmeldung":[{"option":0,"text":"Dass bei der Verbrennung kein Stoff verschwindet, stimmt: Die Gesamtmasse bleibt gleich. Das betrifft aber die Masse, nicht die Energie, und sagt nichts darüber, woher die Wärme kommt."},{"option":2,"text":"Wärme und Temperatur sind tatsächlich verschiedene Größen, und die Temperatur allein verrät nicht, wie viel Energie in einem Körper steckt. Wo die Wärme im Kamin herkommt, klärt das aber nicht."},{"option":3,"text":"Dass bei Umwandlungen nutzbare Energie zu Abwärme wird, trifft zu. Der Gedanke regelt jedoch, wie viel Energie nutzbar bleibt, nicht, woher sie stammt, und auf diese Herkunft zielt die Aussage der Freundin."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.1 „The First Law of Thermodynamics“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-1-the-first-law-of-thermodynamics","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"24dd3a9b39dd2b02"}},{"id":"qx-c1-035","clusterId":"C","werkstueckRef":"C.2.3","stufe":3,"question":"Welche der folgenden Aussagen sollte dich am ehesten misstrauisch machen, weil hier ein Energie-Begriff als physikalische Tatsache verkauft wird und Menschen dadurch zu einer Entscheidung gedrängt werden?","options":["„Mein Gerät liefert dauerhaft mehr Strom, als es verbraucht, aus ‚Raumenergie‘ – investier jetzt in deine Unabhängigkeit.“","„Mein neuer Kühlschrank braucht laut Energielabel weniger Energie als der alte; das kannst du am Stromzähler selbst nachmessen.“","„Nur noch heute: Wer jetzt unterschreibt, sichert sich den Rabatt – morgen gilt wieder der volle Preis, überleg nicht zu lange.“","„Meine Kollegin hat eine Energie, die den ganzen Raum mitreißt, sobald sie ein Meeting beginnt, und bringt jede Diskussion in Gang.“"],"correctIndex":0,"explanation":"Die Aussage mit dem Gerät behauptet einen physikalischen Vorgang (mehr Strom heraus als hinein) und knüpft daran eine Geldforderung. Nach dem Ersten Hauptsatz kann Energie weder erzeugt noch vernichtet werden. Ein Gerät, das mehr abgibt, als es aufnimmt, wäre eine „Bank“, die Geld aus dem Nichts druckt. Der Zweite Hauptsatz kommt noch hinzu: Kein realer Vorgang läuft ohne Verlust ab, ein Teil der nutzbaren Energie wird immer zu Abwärme. Wer für eine solche Maschine Geld verlangt, verkauft eine Metapher oder ein Wort als Physik. Das Wort „Raumenergie“ ohne Maßeinheit und ohne benannte Quelle ist zusätzlich ein Warnsignal. Prüffrage: Woher kommt die Energie, in welcher Form fließt sie, und wohin geht die Abwärme? Die anderen Aussagen sind unauffällig, weil jeweils ein Teil fehlt: Der Kühlschrank-Satz nutzt Energie als messbare Größe, lässt sich nachprüfen und drängt niemanden. Der Rabatt-Satz setzt unter Druck, behauptet aber nichts über Energie. Und die Kollegin benutzt „Energie“ erkennbar als Bild für Ausstrahlung, ohne dass jemand etwas entscheiden soll.","coreRule":"⚡ Eine Metapher ist harmlos. Gefährlich wird sie, wenn jemand sie als Physik verkauft und daran eine Forderung knüpft.","beleg":"Werkstück C.2.3 (Der Kipppunkt; Red Flags)","status":"entwurf","kurz":"Hier wird ein physikalischer Vorgang behauptet (mehr Strom heraus als hinein) und mit einer Geldforderung verknüpft. Energie kann aber weder erzeugt noch vernichtet werden, und „Raumenergie“ ohne Quelle und Maßeinheit ist ein bloßes Wort, das als Physik verkauft wird.","prueffrage":"Was müsste man messen, um jede dieser Aussagen zu überprüfen, und wer hätte einen Schaden, wenn sie falsch wäre?","rueckmeldung":[{"option":1,"text":"Hier steht Energie für eine messbare Größe: Du kannst die Angabe am Stromzähler selbst nachprüfen, und niemand verlangt eine schnelle Entscheidung von dir. Es fehlen also beide Merkmale, die misstrauisch machen sollten."},{"option":2,"text":"Befristete Rabatte setzen dich unter Zeitdruck, und das ist ein Warnsignal. Der Satz behauptet aber nichts über Energie oder Physik. Gefragt war nach der Verbindung aus Druck und einer als Tatsache verkauften Energie-Behauptung."},{"option":3,"text":"Hier ist „Energie“ erkennbar ein Bild für Ausstrahlung und Elan, niemand hält es für eine physikalische Größe. Außerdem soll niemand etwas kaufen oder entscheiden, deshalb gibt es keinen Anlass zu Misstrauen."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.1 „The First Law of Thermodynamics“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-1-the-first-law-of-thermodynamics","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.3 „Introduction to the Second Law of Thermodynamics: Heat Engines and Their Efficiency“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-3-introduction-to-the-second-law-of-thermodynamics-heat-engines-and-their-efficiency","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"a97c065174602883"}},{"id":"qx-c1-036","clusterId":"C","werkstueckRef":"C.2.3","stufe":4,"question":"Ein Freund schwärmt von einer „Kristall-Klangschale“, die Wasser „energetisiere“ und ihm heilende Eigenschaften verleihe. Welche Reaktion bringt ihn am ehesten dazu, die Behauptung selbst zu prüfen, ohne dass das Gespräch zum Streit wird?","options":["Du fragst nach, welche Energieform gemeint ist und woher sie kommt.","Du erklärst ihm die Gesetze der Thermodynamik und stellst klar, dass die Schale nicht funktionieren kann.","Du sagst, „energetisiertes“ Wasser lasse sich nicht beweisen oder widerlegen, und wechselst das Thema.","Du behauptest, jeder Klang erzeuge nur Wärme, und eine Schale könne Wasser deshalb nicht verändern."],"correctIndex":0,"explanation":"Wer eine Wirkung behauptet, behauptet damit einen Energiefluss: Etwas Messbares muss von der Schale auf das Wasser übergehen. Offene, neugierige Fragen wie: Welche Energieform meinst du genau, Wärme oder Schall? Woher kommt mehr Energie, als ich beim Anschlagen hineingesteckt habe? lassen den Freund die Lücke in dieser Energie-Buchhaltung selbst bemerken. Eine Belehrung oder ein Verbot (es könne gar nicht funktionieren) lädt dagegen zur Verteidigung ein. Eine Behauptung ohne Energiebilanz unkommentiert stehen zu lassen, regt nicht zum Prüfen an. Und die Aussage, jeder Klang erzeuge nur Wärme und könne Wasser deshalb nicht verändern, ist überzogen und unbelegt: Sinnvoll ist stattdessen, die behauptete Energieform konkret zu benennen und ihre Messbarkeit zu klären.","coreRule":"⚡ Frag nach der Energie-Buchhaltung: Woher kommt die Energie, in welcher Form wird sie übertragen, wohin geht der Verlust? Der andere findet die Lücke am besten selbst.","beleg":"Werkstück C.2.3 (Werkbank-Frage; Aktivierungs-Frage)","status":"entwurf","scenario":"Du sitzt mit einem Freund beim Kaffee. Er erzählt begeistert, seine Klangschale „energetisiere“ Wasser. Er hat die Schale gekauft und will dich überzeugen.","kurz":"Wer fragt, welche Energieform gemeint ist und woher sie kommt, lässt den Freund die Lücke in seiner Behauptung selbst bemerken. Eine Belehrung oder ein Verbot („kann nicht funktionieren“) lädt dagegen zur Verteidigung ein.","prueffrage":"Was hat dein Freund in die Schale investiert, und wie dürfte er reagieren, wenn ihm jemand sagt, sie könne gar nicht wirken?","rueckmeldung":[{"option":1,"text":"Eine Energiebilanz ist das richtige Kriterium, um die Behauptung zu prüfen. Als Vortrag mit dem fertigen Urteil „kann nicht funktionieren“ lädt dieses Wissen den Freund aber zur Verteidigung ein, statt ihn selbst nachdenken zu lassen."},{"option":2,"text":"Ein Themenwechsel vermeidet zwar den Streit, aber auch das Prüfen. Die Behauptung ist durchaus prüfbar, sobald die behauptete Energieform benannt ist; unkommentiert stehen gelassen, regt sie niemanden zum Nachdenken an."},{"option":3,"text":"Skepsis ist berechtigt, und beim Anschlagen entsteht auch etwas Wärme. „Jeder Klang erzeugt nur Wärme“ ist aber überzogen und unbelegt; eine solche Gegenbehauptung lässt sich so leicht zurückweisen wie die Behauptung des Freundes."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.1 „The First Law of Thermodynamics“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-1-the-first-law-of-thermodynamics","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax: College Physics 2e, Abschnitt 15.3 „Introduction to the Second Law of Thermodynamics: Heat Engines and Their Efficiency“","oeffentlich":true,"url":"https://openstax.org/books/college-physics-2e/pages/15-3-introduction-to-the-second-law-of-thermodynamics-heat-engines-and-their-efficiency","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"258761af65aef570"}},{"id":"qx-c1-037","clusterId":"C","werkstueckRef":"C.3.1","stufe":1,"question":"Eine Mitschülerin behauptet: „Für den Bau eines Proteins muss die gesamte DNA aus dem Zellkern heraus zu den Ribosomen, denn dort steht ja die Bauanleitung.“ Welche Erwiderung passt am besten zum Weg vom Gen zum Protein?","options":["Falsch: Die DNA bleibt als Blaupause im Zellkern, nur der benötigte Gen-Abschnitt wird als RNA-Arbeitskopie abgeschrieben und zu den Ribosomen gebracht, wo daraus das Protein entsteht.","Falsch: Die DNA bleibt im Zellkern und wird dort in Aminosäuren übersetzt, die danach als fertige Kette zu den Ribosomen wandern und sich dort zum Protein falten.","Richtig: Die gesamte DNA wird als Kopie zu den Ribosomen geschickt, wo daraus in einem einzigen Schritt alle Proteine der Zelle entstehen.","Richtig: Die Ribosomen lesen zuerst die fertigen Aminosäuren ab, aus denen im Zellkern anschließend die passende RNA und zuletzt die DNA des Gens entsteht."],"correctIndex":0,"explanation":"Die DNA ist der robuste Informationsspeicher im Zellkern und dient als Master-Blaupause. Für ein bestimmtes Protein wird nur der passende Gen-Abschnitt in eine mobile Arbeitskopie (RNA) umgeschrieben; das nennt man Transkription. Diese Kopie verlässt den Zellkern, wird an den Ribosomen gelesen und in eine Kette von Aminosäuren übersetzt, die sich zum funktionierenden Protein faltet (Translation). Die Übersetzung in Aminosäuren findet also nicht im Zellkern statt, sondern an den Ribosomen. Der Ablauf ist eindeutig: Die DNA bleibt im Zellkern, nur eine RNA-Kopie des Gens verlässt ihn. Der Weg führt vom Gen über die RNA zur Aminosäurekette; die DNA entsteht nicht erst am Ende aus fertigen Aminosäuren. Die Behauptung der Mitschülerin verwechselt außerdem Gen und gesamtes Erbgut: Ein Gen ist nur ein Abschnitt der DNA mit der Anleitung für ein bestimmtes Protein oder eine funktionale RNA-Einheit.","coreRule":"⚡ DNA ist die Blaupause, RNA die Arbeitskopie, das Protein das fertige Bauteil: Die Information fließt vom Gen über die RNA zum Protein, nie wird dafür das Original verschickt.","beleg":"Werkstück C.3.1 (Kontext & Tiefe, „Vom Gen zum Protein“; Kernidee)","status":"entwurf","scenario":"Im Biologiekurs geht es darum, wie eine Zelle ein Protein herstellt. Du sollst eine Behauptung prüfen.","quote":"","quoteLabel":"","kurz":"Die DNA bleibt als Blaupause im Zellkern; nur der Abschnitt des benötigten Gens wird als RNA-Kopie abgeschrieben und zu den Ribosomen gebracht. Die Behauptung verwechselt ein einzelnes Gen mit dem gesamten Erbgut.","prueffrage":"Braucht die Zelle für ein einzelnes Protein wirklich die Anleitung für alle anderen Proteine mit?","rueckmeldung":[{"option":1,"text":"Dass die DNA im Zellkern bleibt, stimmt. Aminosäuren entstehen dort aber nicht aus ihr: Das Übersetzen in eine Aminosäurekette geschieht erst an den Ribosomen, und zwar anhand der RNA-Kopie."},{"option":2,"text":"Hier steckt derselbe Gedanke wie in der Behauptung: das ganze Erbgut als Vorlage. Kopiert wird aber nur der Abschnitt, den die Zelle gerade braucht, und jedes Protein hat seine eigene Anleitung statt eines einzigen Rundumschritts."},{"option":3,"text":"Das wäre der Weg rückwärts. Die Information fließt vom Gen über die RNA zur Aminosäurekette; die Ribosomen lesen die RNA, und die DNA entsteht nicht am Ende aus fertigen Aminosäuren."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"National Human Genome Research Institute (NHGRI): „Transcription and Translation Lesson Plan“","oeffentlich":true,"url":"https://www.genome.gov/about-genomics/teaching-tools/transcription-translation","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"66338a8a36115bbb"}},{"id":"qx-c1-038","clusterId":"C","werkstueckRef":"C.3.1","stufe":2,"question":"Im Netz kursiert: „Der Mensch hat 50 % seiner DNA mit der Banane gemeinsam.“ Ein Kommentar darunter lautet: „Das passt doch, denn bei Menschen und Schimpansen ist es ja auch nur etwa die Hälfte.“ Welche Antwort prüft beides sauber?","options":["Die Zahl ist ein Mythos: Viele Gene haben ein Gegenstück in der Banane, weil alles Leben gemeinsame Vorfahren hat. Die Sequenzen stimmen aber nicht zur Hälfte überein, und beim Schimpansen liegt die Übereinstimmung bei rund 99 %.","Die Zahl stimmt: Die DNA aller Lebewesen besteht aus denselben vier Basen, deshalb deckt sie sich bei Mensch und Banane zur Hälfte, und beim Schimpansen ist es ähnlich viel.","Die Zahl stimmt für einzelne Gene: Selbst bei Menschen und Schimpansen liegt die Übereinstimmung der Erbgut-Sequenzen nur bei etwa 50 %, bei der Banane also entsprechend ähnlich.","Die Zahl ist ein Mythos: Pflanzen und Tiere besitzen kein gemeinsames Erbgut und sind nicht verwandt, deshalb hat jedes Lebewesen einen eigenen Code, und beim Schimpansen gilt das ebenso."],"correctIndex":0,"explanation":"Die „50 % Banane“ vermischen zwei verschiedene Dinge: Dass viele unserer Gene ein Gegenstück in der Banane haben, ist plausibel, weil alles Leben gemeinsame Vorfahren hat. Daraus folgt aber nicht, dass die DNA-Sequenz zur Hälfte übereinstimmt. Wo sich das Erbgut von Mensch und Schimpanse vergleichen lässt, stimmt es zu rund 99 % überein (Chimpanzee Sequencing and Analysis Consortium 2005, Nature 437): etwa 1,2 % Unterschied bei einzelnen Basen, einige Prozent, wenn Einfügungen und Verluste mitzählen. Wer die Banane mit „50 %“ vergleicht und den Schimpansen mit „nur etwa der Hälfte“ gleichsetzt, wirft Genverwandtschaft und Sequenzübereinstimmung durcheinander. Die Kommentar-Aussage zum Schimpansen ist zudem leicht überprüfbar falsch.","coreRule":"⚡ Gemeinsame Gene heißen nicht gleiche Sequenzen: Verwandtschaft ist etwas anderes als Prozentzahlen aus dem Netz. Prüfe, was genau verglichen wurde, bevor du eine Zahl glaubst.","beleg":"Werkstück C.3.1 (Schmiede-Übung „Der Code-Vergleich“); Fn. gl-c-schimpanse (Chimpanzee Sequencing and Analysis Consortium 2005, Nature 437, S. 69–87)","status":"entwurf","kurz":"Viele Gene haben ein Gegenstück in der Banane, weil alles Leben gemeinsame Vorfahren hat. Daraus folgt nicht, dass die Sequenzen zur Hälfte übereinstimmen; beim Schimpansen sind es sogar rund 99 %. Verwandte Gene und gleiche Sequenz sind zweierlei.","prueffrage":"Was genau wird bei der Zahl „50 %“ verglichen, und welcher Wert ist für Mensch und Schimpanse tatsächlich gemessen worden?","rueckmeldung":[{"option":1,"text":"Dass alle Lebewesen dieselben vier Basen nutzen, stimmt, sagt aber nichts über die Reihenfolge der Basen. Genau auf die Reihenfolge kommt es an, und bei Mensch und Schimpanse stimmt sie zu rund 99 % überein, nicht nur zur Hälfte."},{"option":2,"text":"Dass viele Gene in der Banane ein Gegenstück haben, trifft zu, aber das ist keine 50-%-Übereinstimmung der Sequenzen. Beim Schimpansen ist der Wert mit rund 99 % auch deutlich höher, als hier behauptet wird."},{"option":3,"text":"Dass die 50 % nicht stimmen, ist richtig, die Begründung aber nicht. Pflanzen und Tiere haben gemeinsame Vorfahren und teilen viele Gene, und gerade deshalb lässt sich ihr Erbgut überhaupt vergleichen."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Smithsonian National Museum of Natural History, Human Origins: „Genetics“","oeffentlich":true,"url":"https://humanorigins.si.edu/evidence/genetics","abruf":"2026-10-12"},{"typ":"doi","kurz":"The Chimpanzee Sequencing and Analysis Consortium (2005): „Initial sequence of the chimpanzee genome and comparison with the human genome“, Nature 437, 69–87 (Landkarte [^gl-c-schimpanse], im Belegregister bestätigt; Volltext nur mit Abo)","oeffentlich":false,"doi":"10.1038/nature04072"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"580aa9ccc77e2741"}},{"id":"qx-c1-039","clusterId":"C","werkstueckRef":"C.3.1","stufe":3,"question":"Ein Coach verspricht: „Mit positiven Gedanken reprogrammierst du deine DNA – das beweist die Epigenetik.“ Welche Einordnung hält der Prüfung stand?","options":["Der Satz kehrt die Beweislast um: Der Coach verlangt von Skeptikern, ihm das Gegenteil zu beweisen, statt die Wirkung der Epigenetik auf die DNA selbst zu belegen.","Der Satz verallgemeinert Einzelfälle: Er schließt aus den Erfolgen einiger Kunden, die sich auf die Epigenetik berufen, auf eine Wirkung bei allen Menschen, ohne Vergleichsgruppe.","Der Satz beruht auf einem Zirkelschluss: Er begründet die Wirkung der Gedanken mit der Epigenetik und die Epigenetik wiederum nur mit der Wirkung der Gedanken.","Der Satz vermengt zwei Ebenen: Die Aktivität von Genen lässt sich beeinflussen, die Buchstabenfolge der DNA aber nicht durch bloße Absicht; die Epigenetik wird hier als „Beweis“ missbraucht."],"correctIndex":3,"explanation":"Der Satz des Coachs vermischt zwei verschiedene Dinge. Die Aktivität von Genen kann beeinflusst werden, das ist das Feld der Epigenetik. Die DNA dagegen ist ein bemerkenswert stabiles Molekül, und ihre Buchstabenfolge lässt sich nicht durch bloße Absicht verändern. Wer „DNA umprogrammieren“ verspricht, muss einen konkreten, experimentell belegten Mechanismus nennen, der die Sequenz verändert; ein Wort wie „Epigenetik“ ersetzt diesen Beleg nicht. Die anderen Einwände beschreiben echte Denkfehler, die hier aber nicht vorliegen: Der Coach verlangt von niemandem, das Gegenteil zu widerlegen. Von Kundenerfolgen oder Einzelfällen ist keine Rede. Und er begründet nichts im Kreis, er behauptet nur und beruft sich auf ein Wort.","coreRule":"⚡ Gene lassen sich steuern, die Buchstabenfolge nicht – wer „DNA umschreiben“ verspricht, braucht einen Mechanismus.","beleg":"Werkstück C.3.1 (Anwendung & Relevanz, „In der Pseudomedizin“; Verbindungen; Aktivierungs-Frage)","status":"entwurf","scenario":"","kurz":"Epigenetik betrifft, wie aktiv Gene sind, nicht die Buchstabenfolge der DNA, die sich durch bloße Absicht nicht verändern lässt. Der Fehler: Ein Fachwort wird als Beweis genommen, obwohl ein belegter Mechanismus fehlt.","prueffrage":"Welcher konkrete, experimentell belegte Vorgang soll hier laut Coach etwas Bestimmtes in der Zelle verändern?","rueckmeldung":[{"option":0,"text":"Eine umgekehrte Beweislast ist ein echter Denkfehler, im Satz taucht sie aber nicht auf: Der Coach fordert von niemandem, das Gegenteil zu widerlegen. Er behauptet nur und beruft sich auf ein Wort, ohne es zu belegen."},{"option":1,"text":"Fehlende Vergleichsgruppen sind bei Erfolgsversprechen oft das Problem. Hier ist aber von Kundenerfolgen oder Einzelfällen gar keine Rede, es geht allein um die Behauptung und den Verweis auf die Epigenetik."},{"option":2,"text":"Zirkelschlüsse erkennt man daran, dass sich zwei Aussagen gegenseitig stützen. Hier wird die Epigenetik nicht durch die Wirkung der Gedanken begründet, sondern nur als Schlagwort angeführt. Der Beleg fehlt, aber es entsteht kein Kreis."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"National Human Genome Research Institute (NHGRI): „Epigenomics Fact Sheet“","oeffentlich":true,"url":"https://www.genome.gov/about-genomics/fact-sheets/Epigenomics-Fact-Sheet","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f9ad9a6f8e5b1a10"}},{"id":"qx-c1-040","clusterId":"C","werkstueckRef":"C.3.1","stufe":4,"question":"Jemand sagt: „Gentechnisch veränderter Mais ist pures Gift, weil er ‚unnatürliche Gene‘ enthält.“ Welche Antwort widerlegt das Argument am besten?","options":["Das ist ein Zirkelschluss: „Giftig“ soll beweisen, dass die Gene unnatürlich sind, und „unnatürlich“ soll dann wiederum beweisen, dass der Mais giftig ist, ohne dass etwas Drittes herangezogen wird.","Das ist ein Autoritätsargument: Es beruft sich auf das Urteil einer angeblichen Fachperson, die vor GV-Mais warnt, und ersetzt damit die Prüfung der Sache selbst durch ein bloßes Ansehen.","Das ist ein Natürlichkeitsfehlschluss: Auch Züchtung verändert seit Jahrtausenden das Erbgut, nur zufällig und unpräzise; ob eine Pflanze sicher ist, zeigt ihr Ergebnis, nicht die Herkunft der Veränderung.","Das ist eine Verallgemeinerung aus Einzelfällen: Aus schlechten Erfahrungen mit einer einzelnen Maissorte wird gefolgert, jede Pflanze mit eingefügten Genen müsse deshalb giftig sein."],"correctIndex":2,"explanation":"Das Argument setzt „unnatürlich“ mit „giftig“ gleich, doch Herkunft oder Methode allein sagen nichts über Giftigkeit. Auch klassische Züchtung verändert seit etwa 10.000 Jahren das Erbgut, nur langsamer, zufälliger und unpräziser; Gentechnik wie CRISPR kann dagegen gezielt einzelne Gene verändern. Entscheidend für die Sicherheit ist das neue Merkmal der Pflanze, etwa ob sie ein Gift oder Allergen bildet, und genau das lässt sich prüfen. Die anderen Einordnungen nennen echte Denkfehler, die hier nicht vorliegen: Ein Zirkel ist nicht erkennbar, denn es wird nur in einer Richtung begründet. Eine Fachperson wird nicht angeführt. Und von einer einzelnen schlechten Erfahrung, aus der verallgemeinert würde, ist keine Rede.","coreRule":"⚡ Bewerte das Ergebnis, nicht die Methode: „Natürlich“ ist kein Sicherheitsurteil.","beleg":"Werkstück C.3.1 (Anwendung & Relevanz, „Bei genetisch veränderten Organismen“; Werkbank-Frage; Red Flags)","status":"entwurf","kurz":"Dass Mais „unnatürliche Gene“ hat, sagt nichts darüber, ob er giftig ist. Schon Züchtung verändert das Erbgut seit Jahrtausenden; sicher ist eine Pflanze oder nicht je nach ihrem neuen Merkmal, und das lässt sich prüfen.","prueffrage":"Wie sah die Wildpflanze aus, von der unser heutiger Mais abstammt, und wie wurde daraus die Pflanze auf dem Feld?","rueckmeldung":[{"option":0,"text":"Kreisschlüsse sind ein echter Denkfehler, und die Aussage klingt tatsächlich nach Selbstbestätigung. Sie begründet aber nur in einer Richtung, von „unnatürlich“ auf „giftig“. Schwach ist diese Gleichsetzung, nicht ein Kreis."},{"option":1,"text":"Ein Autoritätsargument stützt sich auf das Ansehen einer Person oder Institution. Hier beruft sich der Satz auf niemanden, er behauptet nur, „unnatürliche Gene“ machten den Mais giftig. Genau diese Gleichsetzung trägt nicht."},{"option":3,"text":"Verallgemeinerungen aus Einzelfällen kommen oft vor und sollten geprüft werden. Hier wird aber kein Einzelfall genannt, aus dem verallgemeinert würde. Geschlossen wird von der Herkunft der Gene auf die Giftigkeit."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"National Academies of Sciences, Engineering, and Medicine (2016): „Genetically Engineered Crops: Experiences and Prospects – New Report“ (Pressemitteilung)","oeffentlich":true,"url":"https://www.nationalacademies.org/news/2016/05/genetically-engineered-crops-experiences-and-prospects-new-report","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1af927a7019b3aa1"}},{"id":"qx-c1-041","clusterId":"C","werkstueckRef":"C.3.3","stufe":1,"question":"In einer Diskussion sagt jemand: „Wenn der Mensch vom Affen abstammt, warum gibt es dann noch Affen? Also kann die Abstammung nicht stimmen.“ Was ist an diesem Schluss fehlerhaft?","options":["Er setzt voraus, dass eine Art nach der Entstehung einer neuen Art verschwinden muss; zwei Linien können aber aus einem gemeinsamen Vorfahren hervorgehen und nebeneinander weiterbestehen.","Er greift die Vertreter der Abstammungslehre persönlich an, statt ihre Belege zu prüfen; ein Argument ist aber unabhängig von der Person zu bewerten, die es vorbringt.","Er beruft sich auf eine Autorität statt auf Belege; dass bekannte Persönlichkeiten die Abstammung ablehnen, ersetzt aber keinen Nachweis gegen die Abstammung.","Er argumentiert im Kreis, weil er die Falschheit der Abstammung schon voraussetzt; ein Argument muss aber unabhängig von seinem Ergebnis begründet werden, sonst beweist es nichts."],"correctIndex":0,"explanation":"Der Schluss setzt stillschweigend voraus, dass eine Stammart verschwinden muss, sobald sich aus ihr eine andere Art entwickelt hat. Das ist nicht der Fall: Zwei Linien können sich von einem gemeinsamen Vorfahren aus getrennt weiterentwickeln, so wie du und dein Cousin einen gemeinsamen Großvater habt. Dass dein Cousin noch lebt, widerlegt die Verwandtschaft nicht, und dass es heute noch Affen gibt, widerlegt die gemeinsame Abstammung ebenso wenig. Andere Fehlschlüsse gibt es durchaus, sie liegen hier aber nicht vor: Die Person greift niemanden persönlich an, sondern bringt einen Einwand vor. Sie beruft sich auch auf keine bekannte Persönlichkeit. Und sie setzt ihre Folgerung nicht schon voraus, sondern leitet sie aus der Frage nach den heutigen Affen ab.","coreRule":"⚡ Wir stammen nicht von heutigen Affen ab, sondern teilen mit ihnen gemeinsame Vorfahren.","beleg":"Werkstück C.3.3 (Red Flags)","status":"entwurf","scenario":"","kurz":"Der Einwand unterstellt stillschweigend, dass eine Stammart verschwinden muss, sobald aus ihr eine neue Art hervorgeht. Zwei Linien können aber nebeneinander weiterbestehen, so wie dein Cousin trotz gemeinsamen Großvaters noch lebt.","prueffrage":"Leben heute verwandte Affenarten wie Schimpanse und Bonobo nebeneinander, und musste dafür eine die andere ablösen?","rueckmeldung":[{"option":1,"text":"Persönliche Angriffe sind ein verbreiteter Fehlschluss, und ein Argument gehört unabhängig von der Person bewertet. Hier greift aber niemand jemanden an; der Einwand betrifft allein die Sache."},{"option":2,"text":"Autoritätsargumente sind tatsächlich oft schwach, weil Ansehen keinen Beleg ersetzt. In diesem Satz wird aber keine bekannte Persönlichkeit genannt; er stützt sich allein auf die Frage nach den heutigen Affen."},{"option":3,"text":"Zirkelschlüsse setzen ihr Ergebnis schon voraus, und das ist ein echter Fehler. Hier wird die Falschheit der Abstammung jedoch nicht vorausgesetzt, sondern aus der Frage nach den heutigen Affen abgeleitet. Die versteckte Annahme liegt woanders."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Smithsonian National Museum of Natural History, Human Origins: „Genetics“","oeffentlich":true,"url":"https://humanorigins.si.edu/evidence/genetics","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0d1cfbd00a06f29e"}},{"id":"qx-c1-042","clusterId":"C","werkstueckRef":"C.3.3","stufe":2,"question":"Welche Erklärung trägt die Beobachtung am besten, dass nach massenhaftem Antibiotika-Einsatz fast nur noch resistente Keime übrig sind?","options":["Das Mittel tötet die empfindlichen Bakterien, die wenigen zufällig resistenten überleben und vermehren sich: Der Einsatz wirkt wie ein Filter.","Die einzelnen Bakterien gewöhnen sich an das Mittel und geben diese erworbene Unempfindlichkeit an ihre Nachkommen weiter: Der Einsatz wirkt wie ein Training.","Reiner Zufall (Gendrift) hat einzelne Varianten häufiger werden lassen, unabhängig vom Mittel: Der Einsatz wirkt wie ein Würfel.","Eine kleine Gruppe resistenter Keime hat die Station zuerst besiedelt, und alle späteren Keime stammen von ihr ab: Der Einsatz wirkt wie ein Nebenschauplatz."],"correctIndex":0,"explanation":"Die Beobachtung lässt sich ohne Absicht und ohne „Lernen“ der Bakterien erklären: Zufällige Veränderungen im Erbgut entstehen ungerichtet, etwa durch Kopierfehler. Wo viel Antibiotikum eingesetzt wird, sterben die empfindlichen Keime, die wenigen zufällig resistenten überleben und vermehren sich, bis sie die Mehrheit stellen. Der Einsatz erzeugt also einen hohen Selektionsdruck, er verändert die Bakterien nicht gezielt. Die Variation ist zufällig, die Auswahl ist es nicht. Dieselbe Logik erklärt, warum schnell evolvierende Grippeviren jedes Jahr einen neuen Impfstoff nötig machen. Die anderen Erklärungen nennen bekannte Gedanken, passen hier aber nicht: Eine Gewöhnung einzelner Bakterien wird nicht vererbt und erklärt nicht, warum die empfindlichen Keime fehlen. Reiner Zufall würde nicht ausgerechnet nach massivem Einsatz die Resistenten begünstigen. Von einer kleinen Gründergruppe, die die Station zuerst besiedelt hätte, ist keine Rede, und der Zusammenhang mit dem Einsatz bliebe unerklärt.","coreRule":"⚡ Resistenz wird nicht „gelernt“, sondern ausgelesen: Das Mittel selektiert, was zufällig schon resistent war.","beleg":"Werkstück C.3.3 (Anwendung & Relevanz, „Gegen Missverständnisse in der Medizin“; Kipppunkt)","status":"entwurf","scenario":"In einer Klinik wird beobachtet: Nach Jahren intensiven Antibiotika-Einsatzes sind die meisten Keime auf der Station gegen das Mittel resistent. Ein Kollege sagt: „Die Bakterien haben sich eben an das Medikament gewöhnt und angepasst.“ Du sollst beurteilen, welche Erklärung die Beobachtung am besten trägt.","kernregel":"⚡ Resistenz wird nicht „gelernt“, sondern ausgelesen: Das Mittel selektiert die zufällig resistenten Bakterien.","kurz":"Das Mittel tötet die empfindlichen Keime, die wenigen zufällig resistenten überleben und vermehren sich. Verführerisch ist die Idee, die Bakterien hätten sich angepasst, doch hier wirkt Auslese: Die Variation ist zufällig, die Auswahl nicht.","prueffrage":"Gab es in der Bakterienmenge schon vor der Behandlung Unterschiede, und wie ließe sich das nachprüfen?","rueckmeldung":[{"option":1,"text":"Dass sich die Keime verändert zeigen, wirkt wie eine Gewöhnung. Erworbene Unempfindlichkeit einzelner Bakterien wird aber nicht vererbt und erklärt nicht, warum die empfindlichen Keime fehlen. Hier wirkt Auslese statt Training."},{"option":2,"text":"Zufall spielt tatsächlich eine Rolle, nämlich bei der Entstehung neuer Varianten im Erbgut. Gendrift allein hätte aber keinen Grund, ausgerechnet nach massivem Einsatz die Resistenten zu begünstigen. Der Zusammenhang mit dem Mittel bliebe offen."},{"option":3,"text":"Ein Gründereffekt ist ein bekannter Mechanismus, im Szenario steht dafür aber nichts: Von einer Gruppe, die die Station zuerst besiedelt hätte, ist keine Rede. Und selbst dann bliebe unerklärt, warum es mit dem Einsatz zusammenhängt."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"University of California Museum of Paleontology, Understanding Evolution: „Misconceptions about evolution“ (Abschnitte b1, a6)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"c664038ecbcafc69"}},{"id":"qx-c1-043","clusterId":"C","werkstueckRef":"C.3.3","stufe":3,"question":"Ein Ernährungs-Influencer sagt: „Wir sind biologisch an die Steinzeit angepasst – iss deshalb wie unsere Vorfahren.“ Welcher Einwand trifft die Behauptung am besten?","options":["Die Behauptung stimmt: Zehntausend Jahre sind biologisch so kurz, dass sich beim Menschen seitdem nichts Wesentliches verändert haben kann.","Die Behauptung stimmt, nur die Milchverdauung ist eine Ausnahme: Sie geht auf eine einzelne Mutation zurück und breitete sich rein zufällig aus.","Die Behauptung ist falsch, weil wir heute perfekt angepasst sind: Evolution arbeitet immer auf den bestmöglichen Zustand hin.","Die Behauptung ist falsch, weil Evolution weiterging: Wo Menschen Milch nutzten, breitete sich die Milchzuckerverdauung im Erwachsenenalter aus."],"correctIndex":3,"explanation":"Die Behauptung unterstellt, die Anpassung sei vor langer Zeit abgeschlossen worden und es gebe einen „natürlichen“ Idealzustand. Das ist doppelt falsch. Erstens hat die Evolution nicht aufgehört: In Populationen, deren Vorfahren Milch nutzten, hat sich die Fähigkeit ausgebreitet, auch als Erwachsene Milchzucker zu verdauen. Das ist eines der am stärksten selektierten Merkmale der letzten 10.000 Jahre. Die Selektion hängt mit dem Milchkonsum zusammen, dessen Stärke allein erklärt die Ausbreitung aber nicht; als zusätzliche Treiber werden Hungersnöte und Krankheiten vermutet. Zweitens ist Evolution nicht auf Perfektion ausgelegt, sondern auf „gut genug“ in der jeweiligen Umgebung. Es gibt deshalb nicht „den einen“ Zustand, an den wir perfekt angepasst sind, weder den steinzeitlichen noch den heutigen. Und die Selektion wirkt nicht zufällig: Die Variation ist zufällig, die Auswahl durch die Umwelt ist es nicht.","coreRule":"⚡ Evolution ist nie fertig, und einen „natürlichen“ Idealzustand, an den wir perfekt angepasst wären, gibt es nicht.","beleg":"Werkstück C.3.3 (Anwendung & Relevanz, „Gegen den Appell an die Natur in seiner ‚Paläo‘-Form“); Fn. gl-c-laktase (Evershed u. a. 2022, Nature 608, S. 336–345)","status":"entwurf","kurz":"Die menschliche Evolution endete nicht in der Steinzeit: Wo Menschen Milch nutzten, breitete sich die Milchzuckerverdauung im Erwachsenenalter aus. Der Denkfehler ist die Annahme, die Anpassung sei längst abgeschlossen und es gebe einen „natürlichen“ Idealzustand.","prueffrage":"Gibt es Merkmale, die sich bei Menschen erst in den letzten Jahrtausenden verbreitet haben, und woran würdest du das erkennen?","rueckmeldung":[{"option":0,"text":"Zehntausend Jahre wirken im Vergleich zur Erdgeschichte winzig. Doch starke Selektion kann schon in wenigen hundert Generationen etwas verändern, wie die Ausbreitung der Milchzuckerverdauung bei Erwachsenen zeigt."},{"option":1,"text":"Die Ausbreitung der Milchverdauung war kein Zufall: Mehrere Erbgutvarianten entstanden unabhängig und zufällig, durchgesetzt haben sie sich, wo Menschen Milch nutzten. Sie ist keine Ausnahme, sondern ein Beleg, dass Evolution weiterging."},{"option":2,"text":"Dass die Behauptung falsch ist, stimmt, doch diese Begründung verlegt ihren Fehler nur in die Gegenwart: Evolution steuert keinen bestmöglichen Zustand an, die Auslese begünstigt, was in der jeweiligen Umgebung gut genug ist."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Evershed, R. P. u. a. (2022): „Dairying, diseases and the evolution of lactase persistence in Europe“, Nature 608, 336–345 (frei in PMC7615474)","oeffentlich":true,"doi":"10.1038/s41586-022-05010-7","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7615474/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of California Museum of Paleontology, Understanding Evolution: „Misconceptions about evolution“ (Abschnitte a8, b7)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5e69b199bac7f957"}},{"id":"qx-c1-044","clusterId":"C","werkstueckRef":"C.3.3","stufe":4,"question":"Wie ist dieses Argument zu bewerten?","options":["Es ist stichhaltig: Bei so hoher Komplexität können Mutation und Selektion grundsätzlich nichts mehr erklären.","Es schließt von „ich kann mir keinen schrittweisen Weg vorstellen“ auf „es gab keinen“; komplexe Strukturen können schrittweise entstanden sein.","Es ist erst widerlegt, wenn jeder einzelne Zwischenschritt des Organs im Fossilbericht lückenlos belegt ist.","Es zeigt zu Recht, dass Zufall allein so etwas nicht hervorbringt; deshalb braucht es einen Plan."],"correctIndex":1,"explanation":"Das Argument schließt von der eigenen Ratlosigkeit auf die Wirklichkeit: Weil sich der Redner keinen schrittweisen Weg vorstellen kann, soll es keinen gegeben haben. Das ist ein Fehlschluss aus persönlichem Unglauben. Dass ein Organ heute ohne ein Teil nicht mehr funktioniert, sagt nichts über seine Entstehung: Komplexe Strukturen konnten schrittweise entstehen. Proto-Flügel dienten etwa vielleicht erst der Isolierung oder Balz, bevor sie beim Gleiten nützlich wurden. Außerdem ist Evolution kein reiner Zufallsprozess, sondern die nicht-zufällige Auswahl zufälliger Variationen. Auch muss nicht jeder Zwischenschritt lückenlos fossil belegt sein: Der Fossilienbestand ist naturgemäß lückenhaft.","coreRule":"⚡ „Das kann ich mir nicht vorstellen“ ist kein Argument gegen eine Erklärung, sondern eine Aussage über die eigene Vorstellungskraft.","beleg":"Werkstück C.3.3 (Anwendung & Relevanz, „Gegen Kreationismus & ‚Intelligent Design‘“; Red Flags)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"7c6d328b4853f9ac","vermerk":"Prüfpult"},"scenario":"Ein Redner behauptet: „Dieses Organ ist ‚irreduzibel komplex‘: Nimmt man ein einziges Teil weg, funktioniert es nicht mehr. Also muss ein Designer es geschaffen haben.“","kurz":"Aus „ich kann mir keinen schrittweisen Weg vorstellen“ folgt nicht, dass es keinen gab. Dass heute kein Teil fehlen darf, sagt nichts über die Entstehung: Teile konnten früher andere Aufgaben erfüllen.","prueffrage":"Was wurde an dem Organ tatsächlich beobachtet, und was davon sagt etwas über seine Entstehung?","rueckmeldung":[{"option":0,"text":"Hohe Komplexität wirkt, als überfordere sie jeden schrittweisen Prozess. Doch Selektion wählt nicht-zufällig aus, und Teile können früher anderen Zwecken gedient haben. Aus fehlender Vorstellung folgt kein „grundsätzlich unmöglich“."},{"option":2,"text":"Lückenlose Belege wären schön, sind aber keine Bedingung: Der Fossilienbestand ist naturgemäß lückenhaft. Entscheidend ist, dass das Argument selbst nicht trägt, weil es aus Unvorstellbarkeit auf Unmöglichkeit schließt."},{"option":3,"text":"Reiner Zufall würde komplexe Strukturen tatsächlich nicht hervorbringen. Evolution ist aber kein reiner Zufallsprozess, sondern die nicht-zufällige Auswahl zufälliger Variationen. Daraus, dass „Zufall allein“ nicht reicht, folgt daher noch kein Plan."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"University of California Museum of Paleontology, Understanding Evolution: „Misconceptions about evolution“ (Abschnitte a2, e4)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7c6d328b4853f9ac"}},{"id":"qx-c1-045","clusterId":"C","werkstueckRef":"C.3.4","stufe":1,"question":"Eine Bekannte erzählt begeistert: „Im Wald hinter dem Dorf lebt ein einzelnes, riesiges Tier, das noch nie jemand eingefangen hat. Es ist vermutlich schon seit Jahrhunderten dort.“ Welcher Einwand trifft den Kern des Problems am besten?","options":["Über Jahrhunderte hält sich in der Regel nur eine Population, kein Einzeltier, und kleine Gruppen sterben durch Inzucht, Krankheiten oder eine Katastrophe leicht aus.","Die Bekannte beruft sich auf eine Autorität, die sich mit Tieren nicht auskennt, doch ein Expertenwort ersetzt keinen Beleg und trägt die Behauptung nicht.","Die Bekannte schließt aus der Lage in einem einzigen Wald auf alle Wälder und verallgemeinert voreilig, obwohl ein Einzelfall keine Regel begründet.","Die Bekannte stellt es so dar, als gebe es nur die Wahl zwischen dem Riesentier und einem Märchen, und blendet jede dritte Möglichkeit aus (falsches Dilemma)."],"correctIndex":0,"explanation":"Die Behauptung verwechselt ein einzelnes Tier mit einer Art. Damit etwas über Jahrhunderte besteht, braucht es eine Population, die sich fortpflanzt. Sehr kleine Gruppen sind stark gefährdet: Inzucht und Gendefekte schwächen den Nachwuchs, Krankheiten und zufällige Ereignisse wie ein Waldbrand können alle auf einmal treffen. Für große Säugetiere schätzen Wissenschaftler die minimal überlebensfähige Population auf mehrere hundert bis einige tausend Individuen, die miteinander in Kontakt stehen (Frankham, Bradshaw und Brook 2014; Jamieson und Allendorf 2012). Die genauen Zahlen schwanken je nach Studie, die Größenordnung bleibt aber gleich: weit mehr als ein Pärchen. Wer von „einem Tier“ spricht, muss also die ganze Population mitdenken, samt Nahrungsbedarf, Spuren und Kadavern. Eine Berufung auf eine Autorität kommt im Gespräch gar nicht vor. Die Bekannte schließt auch nicht von einem Wald auf andere Wälder. Und sie stellt keine Alternative auf, die andere Möglichkeiten ausblendet, sondern behauptet nur ein einzelnes Tier, das so nicht bestehen könnte.","coreRule":"⚡ Wer von „einem Monster“ spricht, muss von einer ganzen Population sprechen.","beleg":"Werkstück C.3.4 (Kontext & Tiefe, „Die minimal überlebensfähige Population“); Fn. gl-c-mvp (Frankham/Bradshaw/Brook 2014, S. 61; Jamieson/Allendorf 2012, S. 582 f.)","status":"entwurf","scenario":"","kurz":"Über Jahrhunderte besteht nur eine fortpflanzungsfähige Population, nie ein einzelnes Tier. Der Denkfehler: „ein Tier“ wird mit „eine Art“ verwechselt, obwohl hinter dem Tier eine ganze Gruppe samt Nahrungsbedarf und Spuren stehen müsste.","prueffrage":"Wie alt werden große Waldtiere wie Bären oder Elche höchstens, und wie oft passt das in einige Jahrhunderte?","rueckmeldung":[{"option":1,"text":"Dass ein Expertenwort keinen Beleg ersetzt, stimmt als Grundsatz. Hier fehlt der Anlass dafür: Die Bekannte beruft sich auf keine Autorität, sie erzählt nur selbst. Das Problem liegt im Inhalt der Behauptung."},{"option":2,"text":"Ein Einzelfall begründet tatsächlich keine Regel. Die Bekannte spricht aber nur über den Wald hinter dem Dorf und schließt nicht auf andere Wälder. Die Schwäche steckt in der Behauptung selbst, nicht in einer Verallgemeinerung."},{"option":3,"text":"Ein falsches Dilemma verlangt, dass nur zwei Möglichkeiten zur Wahl gestellt werden. Die Bekannte stellt aber keine Alternative auf, sie behauptet nur ein einzelnes Tier. Dessen Fortbestand über Jahrhunderte ist das eigentliche Problem."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Traill, L. W.; Bradshaw, C. J. A.; Brook, B. W. (2007): „Minimum viable population size: A meta-analysis of 30 years of published estimates“, Biological Conservation 139, 159–166, doi:10.1016/j.biocon.2007.06.011 (Autorenkopie)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","seite":"159","abruf":"2026-10-12"},{"typ":"doi","kurz":"Frankham, R.; Bradshaw, C. J. A.; Brook, B. W. (2014): „Genetics in conservation management: Revised recommendations for the 50/500 rules …“, Biological Conservation 170, 56–63 (Landkarte [^gl-c-mvp])","oeffentlich":false,"doi":"10.1016/j.biocon.2013.12.036","seite":"61"},{"typ":"doi","kurz":"Jamieson, I. G.; Allendorf, F. W. (2012): „How does the 50/500 rule apply to MVPs?“, Trends in Ecology & Evolution 27(10), 578–584 (Landkarte [^gl-c-mvp])","oeffentlich":false,"doi":"10.1016/j.tree.2012.07.001","seite":"582 f."}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f60cd9bb91804da2"}},{"id":"qx-c1-046","clusterId":"C","werkstueckRef":"C.3.4","stufe":2,"question":"Ein Bigfoot-Anhänger sagt: „Die Tiere sind eben scheu und hinterlassen keine Spuren.“ Welche Überlegung stellt diesen Einwand am stärksten infrage?","options":["Eine Population von einigen Tausend großen Primaten bräuchte täglich Tonnen Nahrung und ließe Tausende Spuren, Kothaufen, Nester und im Lauf der Zeit auch Kadaver zurück.","Einzelne Sichtungen sind unzuverlässig, weil Menschen im Wald Bären oder Schatten leicht für aufrechte Gestalten halten und ihre Erinnerung daran später oft ausschmücken.","Große Tiere, die Menschen meiden, sind oft nachtaktiv und halten sich abseits von Wegen und Siedlungen auf, sodass sie nur selten gesehen oder fotografiert werden.","Man sollte den Anhänger nicht persönlich angreifen, sondern sein Argument prüfen, denn wie glaubwürdig jemand wirkt, sagt nichts darüber, ob seine Aussage stimmt."],"correctIndex":0,"explanation":"Scheu mag erklären, warum man ein einzelnes Tier selten sieht, aber nicht, warum eine ganze Population keine Spuren hinterlässt. Damit sich eine große Tierart über Generationen hält, braucht sie meist mehrere hundert bis einige tausend Tiere; die bräuchten täglich Tonnen an Nahrung und hinterließen Fußspuren, Kothaufen mit DNA, Schlafnester und irgendwann Knochen und Kadaver. Bestätigt wurde bis heute weder ein Körper noch ein Knochen eines solchen Wesens, und genetisch untersuchte Haarproben stammten von bekannten Tieren wie Bären, Pferden oder Menschen. Dass einzelne Sichtungen unzuverlässig sind, stimmt, betrifft aber Zeugenberichte und nicht die Frage nach den Spuren. Nachtaktivität und Menschenscheu erklären wenige Sichtungen, aber keine Tausende Spuren, Nester und Kadaver. Und die Glaubwürdigkeit des Anhängers ist für die Sache unerheblich, geprüft wird das Argument.","coreRule":"⚡ Scheu erklärt, warum Einzeltiere selten auffallen, nicht das Fehlen von Kot, Spuren und Knochen einer ganzen Population.","beleg":"Werkstück C.3.4 (Kontext & Tiefe, „Der ökologische Fußabdruck“); Fn. gl-c-sykes (Sykes u. a. 2014, Proc. R. Soc. B 281, 20140161; Lan u. a. 2017)","status":"entwurf","scenario":"","kurz":"Scheu erklärt, warum man ein einzelnes Tier selten sieht, nicht aber, warum eine ganze Population nichts hinterlässt. Eine Art, die Generationen überdauert, bräuchte täglich Tonnen Nahrung und ließe Spuren, Kot, Nester und irgendwann Kadaver zurück.","prueffrage":"Was hinterlassen scheue Waldtiere wie Bären oder Luchse, obwohl man sie selbst kaum zu Gesicht bekommt?","rueckmeldung":[{"option":1,"text":"Dass Sichtungen unzuverlässig sind, stimmt: Bären, Schatten und ausgeschmückte Erinnerungen spielen eine Rolle. Der Einwand des Anhängers betrifft aber die fehlenden Spuren, und dazu sagt die Kritik an Zeugenberichten nichts."},{"option":2,"text":"Nachtaktivität und Menschenscheu erklären durchaus, warum solche Tiere selten gesehen oder fotografiert werden. Tausende Spuren, Nester und Kadaver einer ganzen Population ließen sich damit aber nicht verbergen; Sichtbarkeit und Spuren sind zweierlei."},{"option":3,"text":"Als Regel stimmt das: Man prüft ein Argument, nicht die Person, die es vorbringt. Die Frage zielt aber auf die Sache selbst, und dazu, was eine Population hinterlassen müsste, sagt diese Antwort nichts."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Traill, L. W.; Bradshaw, C. J. A.; Brook, B. W. (2007): „Minimum viable population size …“, Biological Conservation 139, 159–166 (Autorenkopie)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","seite":"159","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): „Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates“, Proc. R. Soc. B 281, 20140161 (frei in PMC4100498)","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4100498/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"aec71dbddf1b119c"}},{"id":"qx-c1-047","clusterId":"C","werkstueckRef":"C.3.4","stufe":3,"question":"Jemand zeigt dir ein unscharfes Foto eines angeblichen Riesenprimaten in einem nordamerikanischen Wald und sagt: „Das ist der eindeutige Beweis, dass es diese Tiere gibt!“ Du willst das Foto nicht als Fälschung abtun. Wie antwortest du am überzeugendsten?","options":["Ein scharfes, echtes Foto würde die Existenz der Art belegen, denn nur an der Unschärfe dieses Bildes scheitert die Überzeugungskraft.","Auch ein echtes Foto reicht nicht aus, denn es zeigt höchstens ein Einzeltier, während eine Art eine Population braucht, die Kadaver, Knochen und DNA hinterlässt.","Das Foto genügt, wenn mehrere Zeugen es unabhängig bestätigen, denn dann spricht die Übereinstimmung für eine ganze Population.","Der Fotobeweis muss zuerst als Fälschung entlarvt werden, denn solange das nicht gelingt, bleibt die Existenz der Art bewiesen."],"correctIndex":1,"explanation":"Ein einzelnes Foto, selbst ein echtes, belegt höchstens ein Einzeltier. Eine Art kann aber nicht von einem Einzeltier oder einem Pärchen leben: Bei großen Säugetieren braucht es nach Schätzungen mehrere hundert bis einige tausend Individuen, die in Kontakt stehen, damit Inzucht, Gendefekte und Zufallskatastrophen die Gruppe nicht auslöschen. Eine so große Population hinterlässt jeden Tag messbare Spuren: Fußabdrücke, Kot (eine Fundgrube für DNA-Analysen), Schlafnester und Spuren in der Vegetation. Sie würde außerdem sterben und Kadaver, Knochen oder Fossilien hinterlassen. Bis heute wurde jedoch kein einziger Körper und kein junges Fossil eines solchen Wesens wissenschaftlich bestätigt, und keine der genetisch untersuchten Haarproben ließ sich einer unbekannten Primatenart zuordnen. Die Frage lautet also nicht „Ist auf dem Foto etwas Echtes zu sehen?“, sondern „Wo sind die Belege für eine ganze Population?“. Auch der Weg, erst die Fälschung entlarven zu wollen, führt nicht weiter: Die Logik der Populationsbiologie setzt nicht beim Foto an, sondern bei den Belegen, die eine ganze Population hinterlassen müsste. Mehr Zeugen für dasselbe Einzelbild ersetzen weder Kadaver noch DNA.","coreRule":"⚡ Ein Foto belegt höchstens ein Tier, eine Art braucht eine Population – mit Kadavern, Knochen und DNA.","beleg":"Werkstück C.3.4 (Werkbank-Frage; Red Flags; MVP-Abschnitt; Fußnote gl-c-mvp)","status":"entwurf","scenario":"Das Bild zeigt eine verschwommene, aufrecht gehende Gestalt am Waldrand. Der Fotograf behauptet, es handle sich um ein Mitglied einer bisher unentdeckten Tierart.","kurz":"Selbst ein echtes Foto zeigt höchstens ein Einzeltier, aber eine Art braucht eine Population von vielen Tieren. Die würde Kot, Kadaver, Knochen und DNA hinterlassen. Der Fehler wäre, beim Foto statt bei diesen Spuren anzusetzen.","prueffrage":"Welche Belege außer Fotos gibt es für Bären oder Elche in Nordamerika, und gibt es Vergleichbares für den Riesenprimaten?","rueckmeldung":[{"option":0,"text":"Ein schärferes Bild ließe sich besser beurteilen, deshalb wirkt die Unschärfe wie das eigentliche Problem. Aber auch ein makelloses, echtes Foto zeigt nur ein einzelnes Tier und belegt keine Art, die als ganze Population bestehen müsste."},{"option":2,"text":"Übereinstimmende Zeugen sprechen dafür, dass wirklich etwas gesehen wurde. Sie bleiben aber bei Einzelbeobachtungen und ersetzen weder Kadaver noch Knochen noch DNA, die eine ganze Population hinterlassen müsste."},{"option":3,"text":"Das Foto wirkt wie ein Beweis, dem erst jemand das Gegenteil nachweisen muss. Doch die Beweislast liegt bei der Behauptung: Dass sich keine Fälschung nachweisen lässt, belegt weder das Tier noch eine ganze Population."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Traill, L. W.; Bradshaw, C. J. A.; Brook, B. W. (2007): „Minimum viable population size …“, Biological Conservation 139, 159–166 (Autorenkopie)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","seite":"159","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): „Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates“, Proc. R. Soc. B 281, 20140161 (frei in PMC4100498)","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4100498/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d43331bdb8e0a46b"}},{"id":"qx-c1-048","clusterId":"C","werkstueckRef":"C.3.4","stufe":4,"question":"Ein Reiseführer am Loch Ness behauptet, in dem See lebe seit der Dinosaurier-Zeit eine Population von Plesiosauriern. Welche Fragen prüfen diese Behauptung am besten?","options":["Wie viele Tiere es für das Überleben der Art bräuchten, wovon sie sich im See ernähren würden und wo die Kadaver blieben.","Wie lang ein Plesiosaurier werden konnte, ob er Flossen oder Beine hatte und auf welche Weise er seine Beute fing.","Wer die Behauptung zuerst aufgestellt hat, welche Absicht dahinterstand und ob der Reiseführer vom Tourismus am See lebt.","Seit wann die Legende erzählt wird, welche Geschichten es in der Gegend früher gab und wie sie sich verbreitet haben."],"correctIndex":0,"explanation":"Eine Art überlebt nicht als Einzeltier, sondern nur als Population, die groß genug für einen gesunden Genpool ist; bei großen Wirbeltieren schätzt man dafür meist mehrere hundert bis einige tausend Individuen. Eine solche Population bräuchte täglich viel Nahrung, würde den Fischbestand spürbar verändern und hinterließe Kadaver und Knochen, und ein begrenzter, gut erforschter See könnte sie kaum ernähren. Eine gezielte Umwelt-DNA-Suche in Loch Ness fand denn auch keine Reptilien-DNA. Dazu kommt: Das Tal war in der letzten Eiszeit von Gletschern bedeckt, den See gibt es erst seit rund 10.000 Jahren, also nicht seit der Zeit der Dinosaurier. Wie ein Plesiosaurier aussah und jagte, beschreibt das Tier, beantwortet aber nicht, ob eine überlebensfähige Population dort bestehen kann. Wer die Behauptung aufgestellt hat und wovon er lebt, ist eine sinnvolle Quellenfrage, sagt aber nichts über die Möglichkeit eines solchen Bestands. Die Geschichte der Legende erklärt, woher die Erzählung kommt, nicht, ob sie biologisch möglich ist.","coreRule":"⚡ Prüfe die Herde, nicht das einzelne Wesen: Populationsgröße, Nahrung, Kadaver.","beleg":"Werkstück C.3.4 (Anwendung & Relevanz, „Bei Mythen über ‚überlebende Dinosaurier‘“; Aktivierungs-Frage; Red Flags)","status":"entwurf","scenario":"","kurz":"Eine Art überlebt nur als Population mit vielen Tieren. Die bräuchte täglich viel Nahrung und hinterließe Kadaver; im begrenzten See ist beides kaum denkbar. Wie so ein Tier aussah, sagt dazu nichts.","prueffrage":"Ließe sich die Behauptung auch prüfen, ohne dass je jemand eines der Tiere sieht oder ortet?","rueckmeldung":[{"option":1,"text":"Zu wissen, wie ein Plesiosaurier gebaut war und jagte, hilft, sich das Tier vorzustellen. Es beschreibt aber nur das Tier und klärt nicht, ob im See überhaupt eine überlebensfähige Gruppe davon bestehen könnte."},{"option":2,"text":"Wer etwas behauptet und wovon er lebt, ist eine sinnvolle Quellenfrage. Sie sagt aber nichts darüber, ob ein solcher Bestand im See möglich wäre; das lässt sich unabhängig von der Person prüfen."},{"option":3,"text":"Die Herkunft der Legende erklärt, warum man sich die Geschichte erzählt. Ob ein solcher Bestand im See biologisch möglich wäre, folgt daraus nicht, denn auch alte, weit verbreitete Erzählungen können falsch sein."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Traill, L. W.; Bradshaw, C. J. A.; Brook, B. W. (2007): „Minimum viable population size …“, Biological Conservation 139, 159–166 (Autorenkopie)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","seite":"159","abruf":"2026-10-12"},{"typ":"url","kurz":"phys.org (AFP, 2019): „Could the Loch Ness monster be a giant eel?“","oeffentlich":true,"url":"https://phys.org/news/2019-09-loch-ness-monster-giant-eel.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"698da9520c2d0b9b"}},{"id":"qx-c1-049","clusterId":"C","werkstueckRef":"C.3.6","stufe":1,"question":"Wie ist die Behauptung zu beurteilen, ein Werkzeug sei „nur menschengemacht“, wenn man seine Herkunft prüft?","options":["Die Behauptung hält nicht stand: Das Schneidesystem gibt es in der Natur als Abwehr von Bakterien gegen Viren, Forscher haben es nur umprogrammiert.","Die Behauptung hält stand: Weil Forscher das System so umprogrammiert haben, dass es jede DNA-Stelle schneidet, ist es in dieser Form ein reines Laborprodukt.","Die Behauptung hält nicht stand: Das System stammt aus menschlichen Abwehrzellen, die damit Krebszellen erkennen und deren DNA zerschneiden.","Die Behauptung hält nicht stand: Das System stammt aus Viren, die damit die DNA ihrer Wirtszellen zerschneiden, um sich darin einzubauen."],"correctIndex":0,"explanation":"Die Behauptung verwechselt die Umprogrammierung eines Werkzeugs mit seiner Entstehung. Bakterien speichern Bruchstücke der DNA früherer Angreifer als eine Art Fahndungsfoto-Archiv und zerschneiden bei erneutem Angriff mithilfe dieses Archivs und der Cas-Proteine die virale DNA, bei manchen Bakterien mit Cas9. Das System ist also ein uraltes natürliches Abwehrsystem. 2012 zeigten Doudna und Charpentier, dass man ihm eine beliebige „Adresse“ mitgeben kann, sodass es jede gewünschte Sequenz schneidet; dafür erhielten sie 2020 den Nobelpreis für Chemie. Dass die Herkunft natürlich ist, sagt allerdings noch nichts darüber, ob eine Anwendung sicher oder ethisch vertretbar ist. „Natürlich“ ist kein Gütesiegel und „künstlich“ kein Makel, geprüft werden muss die konkrete Anwendung.","coreRule":"⚡ Prüfe die Herkunft einer Sache, bevor du sie als „völlig neu“ oder „unnatürlich“ bewertest. Und bewerte die Anwendung nach Nutzen und Risiko, nicht nach dem Etikett „natürlich“ oder „künstlich“.","beleg":"Werkstück C.3.6 (Kontext & Tiefe, „Woher das Werkzeug kommt“); Fn. gl-c-crispr-immun (Doudna/Sternberg 2017); Fn. gl-c-crispr-nobel (Jinek u. a. 2012, Science 337, S. 816–821)","status":"entwurf","scenario":"In einer Diskussion über Gentechnik sagt jemand: „CRISPR ist ein rein künstliches Laborprodukt. Die Natur hat damit nichts zu tun, deshalb ist es ein unkontrollierbarer Eingriff in etwas, das es vorher nie gab.“ Du willst die Behauptung prüfen, bevor du sie bewertest.","kurz":"Wer ein umprogrammiertes Werkzeug für rein künstlich hält, verwechselt Umbau mit Ursprung: CRISPR/Cas ist ein altes bakterielles Abwehrsystem gegen Viren, das Forscher nur auf neue Zielstellen eingestellt haben.","prueffrage":"Woher stammen die Bausteine, die in diesem Verfahren eingesetzt werden, und was haben die Forscher daran verändert?","rueckmeldung":[{"option":1,"text":"Dass Forscher dem System beliebige Zielstellen mitgeben können, stimmt und war eine echte Leistung. Das ändert aber nichts an seinem Ursprung: Umprogrammiert wurde ein vorhandenes bakterielles Abwehrsystem, erfunden wurde es nicht."},{"option":2,"text":"Eine Abwehrfunktion gegen Eindringlinge gibt es hier tatsächlich, nur an anderer Stelle: Das System stammt aus Bakterien, nicht aus menschlichen Zellen. Menschliche Abwehrzellen erkennen zwar Krebszellen, tun das aber nicht mit diesem Schneidesystem."},{"option":3,"text":"Viren sind im Spiel, aber in der umgekehrten Rolle: Bakterien nutzen das System, um sich gegen Viren zu wehren. Es stammt aus der Abwehr der Bakterien und dient nicht den Viren zum Einbau in fremde DNA."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Jinek, M.; Chylinski, K.; Fonfara, I.; Hauer, M.; Doudna, J. A.; Charpentier, E. (2012): „A programmable dual-RNA-guided DNA endonuclease in adaptive bacterial immunity“, Science 337, 816–821 (frei in PMC6286148)","oeffentlich":true,"doi":"10.1126/science.1225829","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6286148/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Doudna, J. A.; Sternberg, S. H. (2017): A Crack in Creation, Kap. „Cracking the Code“ (Landkarte [^gl-c-crispr-immun], E-Book ohne Seitenzahlen)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"3a69c437331f9068"}},{"id":"qx-c1-050","clusterId":"C","werkstueckRef":"C.3.6","stufe":2,"question":"Welche Antwort begründet am besten, warum der erste Fall unstrittig als medizinischer Fortschritt gilt, der zweite aber nicht?","options":["Bei Meldung 1 ist die Veränderung auf den behandelten Menschen beschränkt, er kann zustimmen, und die Anwendung ist geprüft und zugelassen; bei Meldung 2 trifft all das nicht zu.","Bei Meldung 1 kommt ein bewährtes Werkzeug zum Einsatz, bei Meldung 2 ein neues, und nur langjährig erprobte Werkzeuge gelten am Menschen als vertretbar.","Bei Meldung 2 droht ein Weg hin zu Designerbabys, bei Meldung 1 nicht, und Eingriffe gelten als verwerflich, wenn sie zu weiteren Eingriffen führen könnten.","Bei Meldung 1 wird ein natürlicher Vorgang unterstützt, bei Meldung 2 gegen die Natur gehandelt, und Eingriffe gegen die Natur gelten als verwerflich."],"correctIndex":0,"explanation":"Beide Meldungen nutzen dasselbe Werkzeug, der Unterschied liegt woanders. Bei der zugelassenen Therapie wird nur der behandelte Mensch verändert (somatisch, nicht vererbbar), er ist einwilligungsfähig, die Krankheit ist schwer und gut verstanden, und Behörden haben die Anwendung nach klinischer Prüfung zugelassen (Großbritannien im November 2023, USA im Dezember 2023). Beim Embryo-Eingriff wird dagegen das Erbgut aller künftigen Generationen verändert, ohne dass diese je zustimmen konnten. Die Folgen lassen sich nicht zurücknehmen, und der Eingriff erfolgte an gesunden Embryonen zur Vorbeugung statt zur Heilung. Wer beides unter „Gentechnik“ in einen Topf wirft, übersieht genau die Fragen, auf die es ankommt: Welche Zellen sind betroffen, wer stimmt zu, wird geheilt oder „verbessert“, ist die Anwendung geprüft? Ein Unterschied im Werkzeug scheidet aus, weil in beiden Meldungen CRISPR genutzt wird. Die Sorge vor einer schiefen Ebene hin zu Designerbabys ist eine Vermutung über die Zukunft und erklärt nicht, was die beiden Fälle heute trennt. Und ob etwas „natürlich“ ist, taugt nicht als Maßstab, denn in beiden Fällen wird das Erbgut mit demselben Werkzeug verändert.","coreRule":"⚡ Bei Gentechnik zählt nicht das Werkzeug, sondern: Welche Zellen werden verändert, wer stimmt zu, wird geheilt oder verbessert, und ist die Anwendung geprüft?","beleg":"Werkstück C.3.6 (Kontext & Tiefe, „Wo CRISPR heute bereits legal Leben rettet“; Kipppunkt); Fn. gl-c-casgevy (MHRA 16.11.2023; FDA 8.12.2023)","status":"entwurf","scenario":"Zwei Meldungen zur Genschere CRISPR:\\n\\nMeldung 1: Eine Therapie gegen die Sichelzellkrankheit wurde von mehreren Zulassungsbehörden genehmigt. Dabei werden einem jugendlichen oder erwachsenen Patienten Blutstammzellen entnommen, außerhalb des Körpers gezielt editiert und zurückgegeben.\\n\\nMeldung 2: Ein Forscher verkündet, er habe Embryonen gesunder Eltern editiert, um die Kinder gegen eine Infektion zu schützen. Die Veränderung wird an alle späteren Nachkommen weitergegeben.","kurz":"Entscheidend ist nicht das Werkzeug, denn beide Male kommt CRISPR zum Einsatz, sondern wen der Eingriff betrifft: Bei der Therapie nur einen einwilligungsfähigen Patienten, geprüft und zugelassen, beim Embryo-Eingriff alle künftigen Nachkommen ohne ihre Zustimmung.","prueffrage":"Welche Angaben machen die beiden Meldungen zu Werkzeug, behandelter Person und Weitergabe der Veränderung, und wo unterscheiden sie sich?","rueckmeldung":[{"option":1,"text":"Dass sich Neues erst bewähren muss, klingt vernünftig. Hier trennt es die Fälle aber nicht: In beiden Meldungen kommt dasselbe Werkzeug zum Einsatz. Geprüft und zugelassen wurde die Anwendung, nicht das Werkzeug."},{"option":2,"text":"Die Sorge vor einer schiefen Ebene hat ihren Reiz, ist aber eine Vermutung über später. Sie erklärt nicht, was die beiden Fälle heute unterscheidet, und als Regel träfe sie fast jeden Fortschritt, der Folgeschritte haben könnte."},{"option":3,"text":"Was „natürlich“ ist, wirkt als schnelles Maß, taugt aber nicht dazu: In beiden Fällen wird das Erbgut mit demselben Werkzeug verändert. Aus „gegen die Natur“ folgt außerdem nicht von selbst, dass etwas verwerflich ist."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"U.S. Food and Drug Administration (08.12.2023): „FDA Approves First Gene Therapies to Treat Patients with Sickle Cell Disease“","oeffentlich":true,"url":"https://www.fda.gov/news-events/press-announcements/fda-approves-first-gene-therapies-treat-patients-sickle-cell-disease","abruf":"2026-10-12"},{"typ":"url","kurz":"National Human Genome Research Institute (NHGRI): „What are the Ethical Concerns of Genome Editing?“","oeffentlich":true,"url":"https://www.genome.gov/about-genomics/policy-issues/Genome-Editing/ethical-concerns","abruf":"2026-10-12"},{"typ":"url","kurz":"MIT Technology Review (30.12.2019): „He Jiankui sentenced to three years in prison for CRISPR babies“","oeffentlich":true,"url":"https://www.technologyreview.com/2019/12/30/131061/he-jiankui-sentenced-to-three-years-in-prison-for-crispr-babies","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8f6fa1771c38b04c"}},{"id":"qx-c1-051","clusterId":"C","werkstueckRef":"C.3.6","stufe":3,"question":"Eine Kommentatorin schreibt zu einem Gentechnik-Skandal: „Das Problem war das Werkzeug. Wer CRISPR benutzt, spielt mit dem Feuer – wer es einsetzt, hat die Grenze schon überschritten.“ Tatsächlich wird CRISPR in Laboren weltweit routinemäßig genutzt, und eine CRISPR-basierte Therapie ist bei Sichelzellkrankheit zugelassen. Welche Frage trennt den Skandalfall am besten von dieser legalen Anwendung?","options":["Welche Zellen wurden verändert, wer konnte zustimmen und wurde eine bestehende Krankheit behandelt oder ein gesunder Mensch verändert?","Welches Werkzeug wurde jeweils eingesetzt, arbeitet es in beiden Fällen nach demselben Prinzip und wie lange gibt es das Verfahren schon?","Wie zuverlässig arbeitet die Genschere im Labor, wie oft schneidet sie an der falschen Stelle und wie lässt sich das messen?","Wer hat die Entwicklung der Genschere bezahlt, welche Firmen verdienen an ihr und wie unabhängig sind die Gutachter?"],"correctIndex":0,"explanation":"Wenn dasselbe Werkzeug in einem Fall verurteilt und im anderen zugelassen wird, kann das Werkzeug den Unterschied nicht erklären. Er muss in den Umständen der Anwendung liegen. Hier gab es zwei Grenzüberschreitungen zugleich: Gesunden Embryonen wurde ein Gen ausgeschaltet, um sie später vor einer HIV-Infektion zu schützen – eine Vorbeugung, keine Heilung einer bestehenden Krankheit. Und die Veränderung betrifft die Keimbahn und wird an alle Nachkommen weitergegeben, die nie zustimmen konnten. Bei der zugelassenen Sichelzell-Therapie werden dagegen Blutstammzellen eines einwilligungsfähigen Patienten außerhalb des Körpers editiert. Das betrifft nur diese Person, und die Krankheit besteht bereits. Die Frage nach Zellart, Zustimmung und Behandlungsziel trennt beide Fälle sauber. Ob das Werkzeug in beiden Fällen dasselbe ist, steht bereits fest und trennt deshalb nichts. Die Zuverlässigkeit der Genschere im Labor gilt für beide Anwendungen gleichermaßen und erklärt den Unterschied nicht. Und wer an der Technik verdient, ist als Quellenfrage sinnvoll, sagt aber nichts darüber, wer hier wen verändert hat.","coreRule":"⚡ Wenn dasselbe Werkzeug mal verurteilt, mal zugelassen wird, liegt der Unterschied in der Anwendung: Welche Zellen, wer stimmt zu, Heilung oder Verbesserung?","beleg":"Werkstück C.3.6 (Der Tag, an dem die Grenze verschwand; Kipppunkt; Wo CRISPR heute bereits legal Leben rettet); Fn. gl-c-hejiankui (Verurteilung in Shenzhen, Dezember 2019); Fn. gl-c-casgevy (Zulassung MHRA/FDA 2023)","status":"entwurf","scenario":"Ein Forscher hat 2018 mit CRISPR ein Gen im Erbgut von Embryonen ausgeschaltet, um die später geborenen Kinder gegen eine Virusinfektion zu schützen. Die Kinder waren gesund. Fachwelt und Behörden verurteilten das Experiment, der Forscher wurde 2019 zu drei Jahren Haft verurteilt. Dieselbe Technik wird in anderen Fällen als zugelassene Therapie eingesetzt.","kurz":"Wenn dasselbe Werkzeug einmal verurteilt und einmal zugelassen wird, kann es den Unterschied nicht erklären. Er liegt in den Umständen: Zellart, Zustimmung und Ziel. Den Fehler macht, wer ein Werkzeug für ein Ergebnis verantwortlich macht, das von seiner Anwendung abhängt.","prueffrage":"Was haben der verurteilte Versuch und die zugelassene Therapie gemeinsam, und worin unterscheiden sie sich?","rueckmeldung":[{"option":1,"text":"Dass in beiden Fällen CRISPR eingesetzt wurde, steht schon fest, und genau deshalb trennt es nichts. Gleiches gilt für Prinzip und Alter des Verfahrens. Der Unterschied muss in der Anwendung liegen, nicht im Werkzeug."},{"option":2,"text":"Wie genau die Genschere schneidet, ist eine berechtigte Sicherheitsfrage. Sie betrifft aber beide Anwendungen gleichermaßen und erklärt deshalb nicht, warum der eine Fall verurteilt und der andere zugelassen wurde."},{"option":3,"text":"Wer die Entwicklung bezahlt und wer daran verdient, ist als Quellenfrage sinnvoll. Sie sagt aber nichts darüber, wer in den beiden Fällen verändert wurde, wer zustimmen konnte und was das Ziel war."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"MIT Technology Review (30.12.2019): „He Jiankui sentenced to three years in prison for CRISPR babies“","oeffentlich":true,"url":"https://www.technologyreview.com/2019/12/30/131061/he-jiankui-sentenced-to-three-years-in-prison-for-crispr-babies","abruf":"2026-10-12"},{"typ":"url","kurz":"U.S. Food and Drug Administration (08.12.2023): „FDA Approves First Gene Therapies to Treat Patients with Sickle Cell Disease“","oeffentlich":true,"url":"https://www.fda.gov/news-events/press-announcements/fda-approves-first-gene-therapies-treat-patients-sickle-cell-disease","abruf":"2026-10-12"},{"typ":"url","kurz":"National Human Genome Research Institute (NHGRI): „What are the Ethical Concerns of Genome Editing?“","oeffentlich":true,"url":"https://www.genome.gov/about-genomics/policy-issues/Genome-Editing/ethical-concerns","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9e6b604c6896d81a"}},{"id":"qx-c1-052","clusterId":"C","werkstueckRef":"C.3.6","stufe":4,"question":"Welche Einordnung des Angebots ist am besten begründet?","options":["Das Angebot ist vertretbar, weil Erwachsene über ihren Körper selbst entscheiden dürfen und das Risiko einer Behandlung freiwillig auf sich nehmen.","Das Angebot ist vertretbar, weil die zugrunde liegende Methode von Forschenden entwickelt wurde, deren Leistung mit dem Nobelpreis anerkannt ist.","Das Angebot ist abzulehnen, weil Eingriffe ins Erbgut des Menschen unnatürlich sind und die Natur ihre Ordnung nicht ohne Not ändern lassen sollte.","Das Angebot ist ein Warnsignal, weil hier Hoffnung verkauft wird, bevor Wirksamkeit und Sicherheit der Behandlung belegt sind."],"correctIndex":3,"explanation":"Ein Nobelpreis würdigt die Entdeckung einer Methode, nicht die Wirksamkeit oder Sicherheit einer einzelnen Anwendung. Ob eine Behandlung hilft, zeigen nur kontrollierte Studien und eine behördliche Zulassung. Die Klinik bietet außerhalb davon eine Behandlung gegen ein derart breites Ziel wie „Alterung“ an, zeigt keine Belege und verlangt hohe Preise: Hier wird Hoffnung zu Geld gemacht, bevor die Wissenschaft nachgezogen hat. Seriös wäre ein Angebot erst als zugelassenes Medikament oder im Rahmen einer regulären klinischen Studie. Entscheidend ist also nicht die Technik, sondern der Prüfstatus der konkreten Anwendung. Dass Erwachsene über ihren Körper entscheiden dürfen, ist ein wichtiger Grundsatz, setzt aber voraus, dass sie die Belege kennen, die hier fehlen. Der Ruf der Entwickler sagt etwas über die Methode, aber nichts darüber, ob diese Anwendung hilft. Und Eingriffe ins Erbgut pauschal als unnatürlich abzulehnen ist keine Begründung, denn geprüfte, zugelassene Therapien zeigen, dass dieselbe Methode Leben retten kann.","coreRule":"⚡ Prüfe bei „CRISPR-Angeboten“ zuerst: Gibt es ein zugelassenes Medikament oder eine reguläre Studie? Wenn nicht, ist Vorsicht geboten. Ein Preis für die Methode ist kein Beleg für die Anwendung.","beleg":"Werkstück C.3.6 (Anwendung & Relevanz, „Gegen unregulierte ‚Gentherapie‘-Kliniken“; Red Flags)","status":"entwurf","scenario":"Eine Klinik wirbt außerhalb von Studien mit „CRISPR-Behandlungen gegen Alterung“. Die Behandlung kostet mehrere zehntausend Euro. Belastbare Wirksamkeitsnachweise zeigt die Klinik nicht, nennt aber stolz, dass die Entwickler der Methode den Nobelpreis erhalten haben.","kurz":"Entscheidend ist der Prüfstatus der konkreten Anwendung: Der Nobelpreis würdigt die Methode, nicht dieses Angebot. Ohne kontrollierte Studien und Zulassung wird hier Hoffnung verkauft, bevor Wirksamkeit und Sicherheit belegt sind.","prueffrage":"Was führt die Klinik zu ihren Gunsten an, und bezieht sich das auf die Methode allgemein oder auf genau diese Behandlung?","rueckmeldung":[{"option":0,"text":"Selbstbestimmung über den eigenen Körper ist ein wichtiger Grundsatz. Eine freie Entscheidung setzt aber voraus, dass man die Belege kennt, und die zeigt die Klinik gar nicht. Zustimmung ohne diese Grundlage ist keine informierte Entscheidung."},{"option":1,"text":"Der Preis ehrt eine Entdeckung und sagt, dass die Methode etwas kann. Ob diese eine Anwendung gegen „Alterung“ hilft und sicher ist, folgt daraus nicht und zeigen erst kontrollierte Studien und eine Zulassung."},{"option":2,"text":"Die Skepsis gegenüber dem Angebot ist berechtigt, die Begründung trägt aber nicht. „Unnatürlich“ sagt nichts über Nutzen oder Schaden: Dieselbe Methode kann als geprüfte, zugelassene Therapie Leben retten. Maßgeblich ist der fehlende Beleg, nicht die Technik."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"U.S. Food and Drug Administration: „Important Patient and Consumer Information About Regenerative Medicine Therapies“","oeffentlich":true,"url":"https://www.fda.gov/vaccines-blood-biologics/consumers-biologics/important-patient-and-consumer-information-about-regenerative-medicine-therapies","abruf":"2026-10-12"},{"typ":"url","kurz":"U.S. Food and Drug Administration (08.12.2023): „FDA Approves First Gene Therapies to Treat Patients with Sickle Cell Disease“","oeffentlich":true,"url":"https://www.fda.gov/news-events/press-announcements/fda-approves-first-gene-therapies-treat-patients-sickle-cell-disease","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"55df1a45260d39db"}},{"id":"qx-c1-053","clusterId":"C","werkstueckRef":"C.4.1","stufe":1,"question":"Welche Schlussfolgerung stützen die Daten am besten?","options":["Die Erkrankung wird durch winzige, unsichtbare Krankheitserreger verursacht, die an den Händen der Ärzte vom Seziersaal zu den Müttern gelangen.","Die Erkrankung hängt von der Erfahrung ab: Hebammen haben mehr Routine bei Geburten als Ärzte und Studenten, deshalb sterben bei ihnen weniger Mütter.","Die Erkrankung hängt von den Müttern ab: Wer schwerer gebärt, kommt eher in die erste Abteilung, und dort sterben deshalb mehr Frauen.","Die Erkrankung entsteht durch grobe Untersuchungen: Ärzte und Studenten untersuchen häufiger und verletzen dabei die Geburtswege stärker als Hebammen."],"correctIndex":0,"explanation":"Der Unterschied zwischen den Abteilungen fällt mit einem Faktor zusammen: Wer aus dem Seziersaal kommt, trägt etwas auf den Händen zu den Müttern. Dass die Sterblichkeit nach dem Desinfizieren der Hände sofort und deutlich fällt, stützt diese Ursache: Wird die vermutete Ursache entfernt, verschwindet der Effekt. Das passt zu der Erklärung, dass viele Krankheiten durch unsichtbare Mikroorganismen verursacht werden, die in den Körper gelangen und sich dort vermehren (Keimtheorie). Mehr Routine der Hebammen würde nicht erklären, warum dieselben Ärzte nach dem Desinfizieren der Hände plötzlich viel weniger Mütter verlieren. Unterschiede zwischen den Müttern ändern sich durch eine Maßnahme an den Händen der Ärzte nicht. Und grobe Untersuchungen blieben auch nach der Chlorlösung genauso grob.","coreRule":"⚡ Wenn das Entfernen einer vermuteten Ursache die Wirkung beseitigt und ein Unterschied zwischen Gruppen genau mit dieser Ursache zusammenfällt, ist die Ursachen-Erklärung gestützt – bei Krankheiten oft: ein spezifischer Erreger statt diffuser „Dünste“ oder „Milieus“.","beleg":"Werkstück C.4.1 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"In einer Geburtsklinik gibt es zwei Abteilungen. In der ersten, betreut von Ärzten und Medizinstudenten, sterben bis zu 18 % der Mütter an Kindbettfieber. In der zweiten, betreut ausschließlich von Hebammen, sind es etwa 2 %. Die Ärzte und Studenten kommen vor ihrer Arbeit direkt aus dem Seziersaal, die Hebammen nicht. Nachdem sich alle Ärzte vor jeder Untersuchung die Hände in einer Chlorlösung desinfizieren müssen, fällt die Sterblichkeit in der ersten Abteilung auf unter 2 %.","kurz":"Die Sterblichkeit sinkt, sobald genau das entfernt wird, was die Ärzte vom Seziersaal an den Händen mitbringen. Dass andere Unterschiede zwischen den Abteilungen bestehen, erklärt diesen Rückgang nicht, denn sie bleiben nach dem Desinfizieren bestehen.","prueffrage":"Worin unterscheiden sich die beiden Abteilungen außer der Sterblichkeit noch, und was änderte sich genau vor dem Rückgang?","rueckmeldung":[{"option":1,"text":"Erfahrung unterscheidet Hebammen und Ärzte tatsächlich. Sie erklärt aber nicht, warum dieselben Ärzte nach dem Händedesinfizieren plötzlich viel weniger Mütter verlieren, denn ihre Routine blieb gleich."},{"option":2,"text":"Unterschiedliche Mütter könnten Sterblichkeitsunterschiede erklären. Eine Chlorlösung an den Händen der Ärzte verändert die Mütter aber nicht, und trotzdem sinkt die Sterblichkeit sofort. Außerdem nennt das Szenario keinen Hinweis auf solche Unterschiede."},{"option":3,"text":"Grobe Untersuchungen wären als Risiko denkbar, das Szenario sagt dazu aber nichts. Und sie blieben mit der Chlorlösung genauso grob. Der deutliche Rückgang nach dem Desinfizieren passt deshalb nicht zu dieser Erklärung."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Carson, E. A.; Toodayan, N. (2018): „Ignaz Philipp Semmelweis (1818–1865): herald of hygienic medicine“, Med J Aust 209(11), 480–482","oeffentlich":true,"doi":"10.5694/mja18.00706","url":"https://www.mja.com.au/journal/2018/209/11/ignaz-philipp-semmelweis-1818-1865-herald-hygienic-medicine","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Semmelweis, I. P. (1861): Die Ätiologie, der Begriff und die Prophylaxis des Kindbettfiebers (Landkarte [^gl-c-semmelweis])","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"dc3951e313f45b78"}},{"id":"qx-c1-054","clusterId":"C","werkstueckRef":"C.4.1","stufe":2,"question":"Welche Schlussfolgerung passt am besten zu dem Muster in den Beobachtungen, und welcher nächste Schritt prüft sie?","options":["Etwas von den Leichen gelangt über die Hände der Ärzte zu den Müttern; die Ärzte sollten sich vor jeder Untersuchung die Hände desinfizieren und die Sterblichkeit weiter beobachten.","Die Hebammen haben mehr Erfahrung bei Geburten als die Ärzte und Studenten, deshalb sterben bei ihnen weniger Mütter; die Ärzte sollten von ihnen geschult werden und die Sterblichkeit weiter beobachten.","Schlechte Luft aus dem Seziersaal verteilt sich im ganzen Haus; die Ärzte sollten die erste Abteilung stärker belüften und die Sterblichkeit weiter beobachten.","Die Ärzte und Studenten untersuchen die Frauen häufiger und gröber als die Hebammen und verletzen dabei die Geburtswege; die Ärzte sollten schonender untersuchen und die Sterblichkeit weiter beobachten."],"correctIndex":0,"explanation":"Die Ausgangslage legt einen gemeinsamen Faktor nahe: Genau die Gruppe mit der hohen Sterblichkeit kommt vom Sezieren, die andere nicht. Dass der Arzt nach einer Verletzung bei der Leichenöffnung an denselben Symptomen stirbt, stützt die Annahme, dass etwas von den Leichen die Krankheit auslöst. Der Weg über die Hände erklärt, warum die Abteilung mit den Ärzten betroffen ist und die andere nicht. Diese Erklärung lässt sich gezielt prüfen: Wenn sich die Ärzte die Hände desinfizieren und die Sterblichkeit sinkt, spricht das für sie. Genau das geschah historisch bei Semmelweis in Wien, wo die Rate nach Chlorwaschungen auf unter zwei Prozent fiel, zeitweise unter eins. Eine Beobachtung kann den Anfang liefern, belastbar wird die Erklärung erst durch Prüfung und Wiederholung. Das Lüften erklärt nicht, warum nur die Abteilung der Ärzte betroffen ist, und hatte bereits nichts gebracht. Mehr Erfahrung der Hebammen erklärt nicht die Symptome des gestorbenen Arztes. Gröbere Untersuchungen erklären ebenfalls nicht, warum ein Arzt nach einer Verletzung bei der Leichenöffnung dieselbe Krankheit bekommt.","coreRule":"⚡ Such den Faktor, in dem sich die Gruppen unterscheiden, formuliere daraus eine Erklärung und prüfe sie mit einer gezielten Maßnahme.","beleg":"Werkstück C.4.1 (Der Arzt, der sich die Hände wusch; Verbindungen); Fn. gl-c-semmelweis (Semmelweis 1861; Best/Neuhauser 2004)","status":"entwurf","scenario":"Eine Klinik hat zwei Geburtsabteilungen. In der ersten, betreut von Ärzten und Medizinstudenten, sterben bis zu 18 % der Mütter an Kindbettfieber, in der zweiten, betreut von Hebammen, nur etwa 2 %. Geburtsposition und Belüftung wurden schon verändert, ohne dass sich etwas bessert. Dann stirbt ein Arzt der Klinik an einer Schnittwunde, die er sich bei einer Leichenöffnung zugezogen hat, mit denselben Symptomen wie die erkrankten Mütter. Die Ärzte und Studenten der ersten Abteilung kommen direkt aus dem Seziersaal, die Hebammen nicht.","kurz":"Genau die Gruppe, die aus dem Seziersaal kommt, hat die hohe Sterblichkeit, und der Arzt stirbt nach einer Verletzung bei der Leichenöffnung an denselben Symptomen. Das spricht für Übertragung von den Leichen über die Hände; ob das stimmt, zeigt erst die Handdesinfektion.","prueffrage":"Was haben die Personen der Abteilung mit hoher Sterblichkeit gemeinsam, das bei der anderen Abteilung fehlt?","rueckmeldung":[{"option":1,"text":"Dass Erfahrung etwas ausmacht, ist denkbar, steht hier aber nirgends. Vor allem erklärt sie nicht, warum ein Arzt nach einer Schnittwunde bei der Leichenöffnung dieselben Symptome entwickelt und stirbt."},{"option":2,"text":"Der Seziersaal als Ursprung ist richtig erkannt, aber Luft im ganzen Haus müsste beide Abteilungen treffen. Und stärkeres Lüften wurde laut Ausgangslage schon geändert, ohne dass sich etwas besserte."},{"option":3,"text":"Ob die Ärzte gröber untersuchen, ist eine Vermutung, die das Szenario nicht belegt. Selbst wenn es so wäre, erklärt es nicht, warum ein Arzt nach einer Verletzung bei der Leichenöffnung an denselben Symptomen stirbt."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Carson, E. A.; Toodayan, N. (2018): „Ignaz Philipp Semmelweis (1818–1865): herald of hygienic medicine“, Med J Aust 209(11), 480–482","oeffentlich":true,"doi":"10.5694/mja18.00706","url":"https://www.mja.com.au/journal/2018/209/11/ignaz-philipp-semmelweis-1818-1865-herald-hygienic-medicine","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Semmelweis, I. P. (1861): Die Ätiologie, der Begriff und die Prophylaxis des Kindbettfiebers (Landkarte [^gl-c-semmelweis])","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"919e259666c08528"}},{"id":"qx-c1-055","clusterId":"C","werkstueckRef":"C.4.1","stufe":3,"question":"Welche Bewertung ist an diesem Gespräch am stichhaltigsten?","options":["Ein gesunder Lebensstil ist sinnvoll, ersetzt aber nicht den gezielten Schutz gegen einen bestimmten Erreger. Bei Wundstarrkrampf reicht allgemeine Abwehrstärke nicht aus.","Ein gesunder Lebensstil senkt nachweislich das Risiko vieler Infektionen. Außerdem helfen Antibiotika nicht gegen Viren, daher ist die Haltung der Bekannten insgesamt gut begründet.","Jeder Mensch darf über Impfungen und Behandlungen am eigenen Körper selbst entscheiden. Deshalb lässt sich an der Haltung der Bekannten sachlich nichts bemängeln.","Ein Einzelfall sagt wenig über das Risiko vieler Menschen. Die Bekannte schließt von ihrer eigenen Gesundheit auf alle und verallgemeinert deshalb voreilig."],"correctIndex":0,"explanation":"Ein gesunder Lebensstil und ein gut funktionierendes Immunsystem helfen dabei, Krankheiten abzuwehren. Der Fehler liegt woanders: Die Bekannte setzt diese allgemeinen Maßnahmen an die Stelle von spezifischen Schutzmaßnahmen. Tetanus wird durch einen bestimmten Erreger verursacht. Dagegen schützt die Impfung gezielt, und bei einer bakteriellen Wundinfektion wirken Antibiotika gezielt gegen den Erreger. Allgemeine Abwehrstärke kann das nicht ersetzen. Dass ein gesunder Lebensstil das Risiko vieler Infektionen senkt und Antibiotika nicht gegen Viren helfen, stimmt, trifft aber eine bakterielle Wundinfektion nicht. Selbstbestimmung über den eigenen Körper ist ein wichtiger Grundsatz, bewertet aber nicht, ob die Begründung der Bekannten trägt. Und sie verallgemeinert nicht auf andere, sondern setzt für sich selbst Wohlbefinden mit Schutz gleich.","coreRule":"⚡ Lebensstil stärkt, ersetzt aber weder Impfung noch Antibiotika bei Infektionen mit spezifischen Erregern.","beleg":"Werkstück C.4.1 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Eine Bekannte erzählt: „Ich ernähre mich sehr bewusst, schlafe gut und treibe viel Sport. Mein Immunsystem ist bestens, deshalb brauche ich keine Tetanus-Impfung. Und wenn ich mir mal an rostigem Metall die Hand aufreiße und die Wunde sich entzündet, kommt kein Antibiotikum infrage, ich vertraue auf meine Abwehrkräfte.“","kurz":"Ein gesunder Lebensstil stärkt die Abwehr allgemein, schützt aber nicht gezielt vor einem bestimmten Erreger wie dem des Wundstarrkrampfs. Der Denkfehler: Wohlbefinden wird mit gezieltem Schutz gleichgesetzt.","prueffrage":"Erkranken auch sportliche, gut ernährte Menschen ohne Impfung an Wundstarrkrampf, und wie ließe sich das nachprüfen?","rueckmeldung":[{"option":1,"text":"Dass ein gesunder Lebensstil das Risiko vieler Infektionen senkt und Antibiotika nicht gegen Viren helfen, stimmt. Eine Wundinfektion nach einer Verletzung ist aber bakteriell und gegen den Tetanus-Erreger schützt Lebensstil nicht gezielt, die Haltung ist also nicht gut begründet."},{"option":2,"text":"Selbstbestimmung über den eigenen Körper ist ein wichtiger Grundsatz. Gefragt ist aber, ob die Begründung der Bekannten trägt, und das ist eine andere Frage als die, ob sie entscheiden darf. Eine Entscheidung kann frei und trotzdem schlecht begründet sein."},{"option":3,"text":"Einzelfälle sagen tatsächlich wenig über viele Menschen. Die Bekannte spricht hier aber nur von sich selbst und schließt nicht auf andere. Ihr Fehler liegt darin, dass sie ihr eigenes Wohlbefinden mit gezieltem Schutz gegen einen Erreger gleichsetzt."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Centers for Disease Control and Prevention (CDC): „About Tetanus“","oeffentlich":true,"url":"https://www.cdc.gov/tetanus/about/index.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"943af2abcd66ee31"}},{"id":"qx-c1-056","clusterId":"C","werkstueckRef":"C.4.1","stufe":4,"question":"Ein Therapeut behauptet: „Keime sind nicht die Ursache von Infektionen, sondern nur ein Symptom des ‚ungesunden Milieus‘. Mit einer Entsäuerungskur heilst du die Krankheit.“ Welche Rückfrage prüft diese Behauptung am besten?","options":["Wer hat die Milieu-Idee entwickelt, denn so alte Theorien aus dem 19. Jahrhundert sind allein wegen ihres Alters überholt?","Wie erklärt diese Sicht, dass sich dieselbe Krankheit bei jeder Ansteckung mit demselben Erreger zeigt, denn eine Behauptung muss zu den Befunden passen?","Wie viele zufriedene Kunden hat die Kur, denn spürbare Besserung nach der Anwendung beweist, dass die Therapie wirkt?","Sind Keime nur unter dem Mikroskop sichtbar, denn nur mit bloßem Auge Sichtbares kann als Krankheitsursache gelten?"],"correctIndex":1,"explanation":"Eine Behauptung wird nicht dadurch stark, dass sie plausibel klingt, sondern dadurch, dass sie die vorhandenen Befunde erklären kann. Hier lautet der Befund: Bestimmte Mikroben lösen bestimmte Krankheiten mit bestimmten Symptomen aus, und wo man die Übertragung der Erreger gezielt unterbindet (Hygiene, Impfung, Antibiotika), sinkt die Erkrankungsrate. Das Beispiel Semmelweis zeigt, wie stark so ein Eingriff wirkt: Nach der Einführung der Chlorwaschungen fiel die Sterblichkeit durch Kindbettfieber in seiner Abteilung von bis zu 18 Prozent auf unter zwei Prozent. Erst die Arbeit von Pasteur und Koch bestätigte später die Keimtheorie dahinter. Wer behauptet, Keime seien nur ein Symptom, muss erklären, warum diese Muster so zuverlässig auftreten. Das Alter einer Idee sagt nichts darüber, ob sie zu den Befunden passt. Auch die Zufriedenheit einzelner Kunden beantwortet diese Frage nicht, denn sie zeigt nicht, ob die Kur der Grund für die Besserung war. Dass Keime mit bloßem Auge unsichtbar sind, spricht nicht gegen ihre Wirkung, denn die Wirkung zeigt sich in den Folgen, nicht in der Sichtbarkeit.","coreRule":"⚡ Verlange Erklärung für die Belege: Wer eine etablierte Ursache bestreitet, muss erklären, warum spezifische Mikroben, spezifische Krankheiten und Heilung durch Beseitigung der Mikroben so zuverlässig zusammenfallen.","beleg":"Werkstück C.4.1 (Anwendung & Relevanz, „Bei der Leugnung der Keimtheorie“; Aktivierungs-Frage)","status":"entwurf","kurz":"Eine Behauptung überzeugt nicht durch Plausibilität, sondern dadurch, dass sie die Befunde erklärt. Wer Keime zum bloßen Symptom erklärt, muss erklären, warum bestimmte Erreger zuverlässig bestimmte Krankheiten auslösen und warum weniger Übertragung weniger Erkrankungen bringt.","prueffrage":"Was geschieht mit der Zahl bestimmter Erkrankungen, wenn Hygiene oder Impfung die Übertragung ihrer Erreger unterbindet?","rueckmeldung":[{"option":0,"text":"Wer eine Behauptung auf ihren Ursprung zurückverfolgt, wirkt gründlich. Das Alter einer Idee entscheidet aber nicht über ihre Geltung: Ob sie trägt, zeigt sich daran, ob sie zu den vorhandenen Befunden passt."},{"option":2,"text":"Zufriedene Kunden wirken wie ein Beleg aus der Praxis. Sie zeigen aber nur, dass es nach der Kur vielen besser ging, nicht, dass die Kur der Grund war. Die Besserung kann auch ohne sie eingetreten sein."},{"option":3,"text":"Dass Keime nur unter dem Mikroskop sichtbar sind, stimmt, und das Unsichtbare kann Misstrauen wecken. Ob etwas Ursache sein kann, hängt aber nicht von seiner Sichtbarkeit ab, sondern davon, ob sich seine Wirkung in den Folgen zeigt."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Carson, E. A.; Toodayan, N. (2018): „Ignaz Philipp Semmelweis (1818–1865): herald of hygienic medicine“, Med J Aust 209(11), 480–482","oeffentlich":true,"doi":"10.5694/mja18.00706","url":"https://www.mja.com.au/journal/2018/209/11/ignaz-philipp-semmelweis-1818-1865-herald-hygienic-medicine","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Semmelweis, I. P. (1861): Die Ätiologie, der Begriff und die Prophylaxis des Kindbettfiebers (Landkarte [^gl-c-semmelweis])","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a5c664b13e590835"}},{"id":"qx-c1-057","clusterId":"C","werkstueckRef":"C.4.2","stufe":1,"question":"Eine Freundin hat eine fiebrige Erkältung und will sich beim Arzt „etwas Starkes“ verschreiben lassen: „Das ist eine Infektion, also muss ein Antibiotikum her.“ Wie beurteilst du ihre Schlussfolgerung?","options":["Sie ist ein Zirkelschluss, denn die Schlussfolgerung „Antibiotikum“ steckt schon in der Annahme „Infektion“.","Sie ist unvollständig, denn entscheidend ist der Erreger: Antibiotika wirken nur gegen Bakterien, nicht gegen Viren.","Sie ist ein Fehlschluss von Korrelation auf Ursache, denn gemeinsames Auftreten beweist keinen ursächlichen Zusammenhang.","Sie ist eine Verfügbarkeitsverzerrung, denn sie urteilt nach auffälligen Einzelfällen im Gedächtnis statt nach Häufigkeiten."],"correctIndex":1,"explanation":"„Infektion“ sagt nur, dass ein Erreger im Körper ist, nicht welcher. Bakterien sind einzellige Lebewesen mit eigenem Stoffwechsel; Antibiotika greifen Strukturen an, die menschlichen Zellen fehlen oder sich von ihnen unterscheiden, etwa die bakterielle Zellwand. Viren gelten meist nicht als Lebewesen: Sie bestehen aus Erbgut in einer Proteinhülle, haben weder Zellwand noch eigenen Stoffwechsel und vermehren sich nur, indem sie eine Wirtszelle umprogrammieren, deshalb wirken Antibiotika gegen sie nicht, auch bei starken Symptomen. Unnötiger Einsatz begünstigt zudem resistente Bakterien. Die klärende Frage lautet also nicht „Infektion ja oder nein?“, sondern „Welcher Erreger?“. Ein Zirkelschluss liegt nicht vor, denn „Antibiotikum“ steckt nicht schon im Begriff „Infektion“. Auch behauptet die Freundin keinen Ursachenzusammenhang zwischen Fieber und Erkältung, sondern wendet eine Regel auf eine Diagnose an. Von auffälligen Einzelfällen, die ihr Urteil verzerren könnten, ist ebenfalls keine Rede.","coreRule":"⚡ Erst fragen, welcher Erreger: Bakterium (eigenständiger Zwerg) oder Virus (Gen-Pirat, der eine Zelle kapern muss). Davon hängt die Behandlung ab.","beleg":"Werkstück C.4.2 (Kernidee; Kontext & Tiefe, „Bakterien“ und „Viren“; Anwendung & Relevanz, Antibiotika-Krise)","status":"entwurf","scenario":"","kurz":"„Infektion“ sagt nur, dass ein Erreger im Körper ist, nicht welcher. Antibiotika wirken gegen Bakterien, aber nicht gegen Viren. Der Fehler liegt darin, von „Infektion“ direkt aufs Mittel zu springen, statt zu fragen, welcher Erreger dahinter steckt.","prueffrage":"Wie verlaufen fiebrige Erkältungen gewöhnlich, und in welchen Fällen verschreiben Ärzte dabei überhaupt ein Antibiotikum?","rueckmeldung":[{"option":0,"text":"Ein Zirkelschluss setzt die Behauptung schon in die Annahme. Hier steckt „Antibiotikum“ aber nicht im Begriff „Infektion“. Der Schluss hat eine Lücke: Er überspringt die Frage, welcher Erreger dahintersteckt."},{"option":2,"text":"Hier werden nicht zwei Beobachtungen zu Ursache und Wirkung verbunden. Die Freundin wendet eine Regel auf ihre Diagnose an. Ob die Regel überhaupt für ihren Fall gilt, hängt vom Erreger ab, und genau diese Frage wird nicht gestellt."},{"option":3,"text":"Eine Verzerrung durch auffällige Einzelfälle im Gedächtnis wäre denkbar, steht aber nicht im Szenario. Die Freundin beruft sich auf eine allgemeine Regel, nicht auf erinnerte Fälle. Das Problem liegt in der Regel selbst, nicht in ihrer Erinnerung."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"MSD Manual (Consumer Version): Overview of Viral Infections","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/viral-infections/overview-of-viral-infections","abruf":"2026-10-12"},{"typ":"url","kurz":"Mobley 2006, How do antibiotics kill bacterial cells but not human cells?, Scientific American","oeffentlich":true,"url":"https://www.scientificamerican.com/article/how-do-antibiotics-kill-b/","abruf":"2026-10-12"},{"typ":"url","kurz":"MSD Manual (Consumer Version): Overview of Antibiotics","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/antibiotics/overview-of-antibiotics","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"98fd1e96abcfc959"}},{"id":"qx-c1-058","clusterId":"C","werkstueckRef":"C.4.2","stufe":2,"question":"Eine Bekannte lehnt eine Impfung ab: „Da spritzen die mir ja die Krankheit direkt in den Körper.“ Welche Erwiderung trifft den Kern?","options":["Impfungen schützen auch Menschen, die sich nicht impfen lassen können, weil weniger Erreger weitergegeben werden. Das nennt man Herdenimmunität.","Impfstoffe enthalten oft nur ungefährliche Bestandteile oder abgeschwächte bzw. abgetötete Erreger. Das Immunsystem lernt daran, den Erreger zu erkennen.","Bei manchen Erregern lässt der Impfschutz mit der Zeit nach. Deshalb sind Auffrischimpfungen in bestimmten Abständen nötig, um den Schutz zu erhalten.","Wie gut ein Impfstoff wirkt, zeigt der Vergleich von Geimpften und Ungeimpften. Erkranken Geimpfte deutlich seltener, spricht das für die Wirksamkeit."],"correctIndex":1,"explanation":"Die Sorge verwechselt den vollständigen, aktiven Erreger mit dem, was tatsächlich gespritzt wird. Impfstoffe enthalten oft nur harmlose Bestandteile des Erregers, etwa ein Oberflächenprotein oder ein unschädlich gemachtes Bakteriengift, oder abgeschwächte bzw. abgetötete Erreger, die in aller Regel keine Krankheit auslösen. Daran lernt das Immunsystem den Eindringling kennen wie an einem „Fahndungsfoto“ und bildet Antikörper und Gedächtniszellen, sodass es den echten Erreger später rasch erkennt und bekämpft. Der Schutz anderer durch Herdenimmunität ist ein gutes Argument, räumt aber die Sorge nicht aus, man bekomme die Krankheit selbst gespritzt. Dass der Schutz nachlassen kann, betrifft die Dauer der Wirkung, nicht den Inhalt der Spritze. Der Vergleich von Geimpften und Ungeimpften zeigt, ob ein Impfstoff wirkt, sagt aber nichts darüber, was in der Spritze steckt.","coreRule":"⚡ Wer eine Aussage über Impfstoffe prüft, fragt zuerst: Was wird tatsächlich gespritzt, der ganze aktive Erreger oder nur ein „Fahndungsfoto“?","beleg":"Werkstück C.4.2 (Kontext & Tiefe, „Impfungen“; Anwendung & Relevanz, „In der Impfdebatte“; Red Flags)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Die Sorge verwechselt den vollständigen Erreger mit dem, was tatsächlich gespritzt wird: oft nur harmlose Bestandteile oder abgeschwächte bzw. abgetötete Erreger. Daran lernt das Immunsystem den Erreger kennen, ohne dass die Krankheit ausbricht.","prueffrage":"Erkranken Geimpfte nach der Spritze an der Krankheit, gegen die sie geimpft wurden, und wie oft kommt das vor?","rueckmeldung":[{"option":0,"text":"Herdenimmunität ist ein gutes Argument für Impfungen und stimmt. Die Sorge der Bekannten betrifft aber den Inhalt der Spritze und bleibt davon unberührt: Sie fürchtet, die Krankheit selbst zu bekommen."},{"option":2,"text":"Bei manchen Erregern kann der Schutz mit der Zeit nachlassen, das ist richtig. Es geht dabei jedoch um die Dauer der Wirkung. Was überhaupt gespritzt wird und ob das die Krankheit auslöst, beantwortet es nicht."},{"option":3,"text":"Der Vergleich von Geimpften und Ungeimpften zeigt, ob ein Impfstoff wirkt, das ist eine gute Methode. Er sagt aber nichts darüber, was in der Spritze steckt, und damit nichts zur geäußerten Sorge."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"WHO: How do vaccines work?","oeffentlich":true,"url":"https://www.who.int/news-room/feature-stories/detail/how-do-vaccines-work","abruf":"2026-10-12"},{"typ":"url","kurz":"MSD Manual (Consumer Version): Overview of Viral Infections","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/viral-infections/overview-of-viral-infections","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c832f64ce088d1d3"}},{"id":"qx-c1-059","clusterId":"C","werkstueckRef":"C.4.2","stufe":3,"question":"Welcher Einwand trifft den Kern, warum diese Werbung unglaubwürdig ist?","options":["Viren vermehren sich in lebenden Körperzellen und haben weder Zellwand noch eigenen Stoffwechsel; ein Mittel muss in der Zelle wirken, ohne sie zu schädigen, daher ist „ganz ohne Nebenwirkungen“ kaum glaubwürdig.","Viele Virusinfektionen heilen von selbst aus, sodass die meisten Menschen ein Mittel dagegen gar nicht brauchen; deshalb preist die Werbung vor allem etwas an, das kaum jemand wirklich benötigt.","Impfungen verhindern viele Virusinfektionen schon vor der Ansteckung; ein Mittel, das erst nach der Infektion wirkt, bleibt gegenüber der Vorbeugung durch Impfstoffe deshalb nur die zweite Wahl.","Laborergebnisse, in denen ein Wirkstoff Viren hemmt, lassen sich nicht ohne Weiteres auf den Menschen übertragen; deshalb beruht die Werbung auf einem voreiligen Schluss aus dem Reagenzglas."],"correctIndex":0,"explanation":"Antibiotika sind deshalb so gezielt, weil Bakterien Strukturen haben, die menschliche Zellen nicht besitzen, etwa die Zellwand. Dort kann ein Wirkstoff ansetzen, ohne Körperzellen zu treffen. Viren haben weder Zellwand noch eigenen Stoffwechsel. Sie vermehren sich, indem sie eine lebende Wirtszelle umprogrammieren. Ein antivirales Mittel muss deshalb in die bereits infizierte Zelle gelangen und dort die Vermehrung des Virus stören, ohne die Wirtszelle zu sehr zu schädigen. Das ist deutlich schwieriger als bei Antibiotika; manche antivirale Mittel setzen zwar an virusspezifischen Schritten an, aber das Versprechen, genauso gezielt und völlig ohne Nebenwirkungen zu wirken, ist nicht plausibel. Dass viele Virusinfektionen von selbst ausheilen, sagt etwas über den Bedarf, nicht über die Glaubwürdigkeit des Versprechens. Der Vorrang der Impfung vor der Behandlung ist richtig, ändert aber nichts daran, ob ein Mittel gezielt und frei von Nebenwirkungen sein kann. Und von Laborergebnissen ist in der Werbung gar nicht die Rede.","coreRule":"⚡ Gegen Bakterien gibt es Angriffsflächen von außen, gegen Viren muss man in die gekaperte Zelle hinein. Bei Heilversprechen prüfst du deshalb zuerst, ob ein plausibler Mechanismus erklärt wird.","beleg":"Werkstück C.4.2 (Kontext & Tiefe, „Antivirale Medikamente“; „Wie man sie bekämpft“)","status":"entwurf","scenario":"Ein Pharmakonzern wirbt für ein neues Mittel: „Wirkt gegen Viren genauso gezielt wie gängige Antibiotika gegen Bakterien, und das ganz ohne Nebenwirkungen.“","kurz":"Viren haben keine eigenen Strukturen wie Bakterien, sondern nutzen lebende Körperzellen zur Vermehrung. Ein Mittel muss deshalb in der Zelle ansetzen, ohne sie zu schädigen. Genauso gezielt und völlig ohne Nebenwirkungen ist das kaum plausibel.","prueffrage":"Haben gängige Antibiotika selbst Nebenwirkungen, und gibt es bereits zugelassene Mittel gegen Viren?","rueckmeldung":[{"option":1,"text":"Dass viele Virusinfektionen von selbst abklingen, stimmt. Das betrifft aber nur den Bedarf an einem Mittel. Ob das Versprechen „gezielt und ohne Nebenwirkungen“ glaubwürdig ist, lässt sich damit nicht beurteilen."},{"option":2,"text":"Impfungen verhindern viele Infektionen schon vor der Ansteckung, das ist richtig. Es beantwortet aber nicht, ob ein Mittel nach der Infektion gezielt und nebenwirkungsfrei wirken kann, und erklärt die Werbung daher nicht für unglaubwürdig."},{"option":3,"text":"Von Laborergebnissen auf den Menschen zu schließen, ist tatsächlich riskant. In der Werbung ist aber von keiner Studie die Rede, nur von einem Versprechen. Der Einwand setzt etwas voraus, das dort gar nicht steht."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"MSD Manual (Consumer Version): Overview of Viral Infections","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/viral-infections/overview-of-viral-infections","abruf":"2026-10-12"},{"typ":"url","kurz":"Mobley 2006, How do antibiotics kill bacterial cells but not human cells?, Scientific American","oeffentlich":true,"url":"https://www.scientificamerican.com/article/how-do-antibiotics-kill-b/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d72d792c60f925d2"}},{"id":"qx-c1-060","clusterId":"C","werkstueckRef":"C.4.2","stufe":4,"question":"Ein Bekannter sagt: „Ich lasse mich nicht mit mRNA impfen. Die verändert doch mein Erbgut.“ Welche Rückfrage prüft diese Befürchtung am besten?","options":["Was genau bringt der Impfstoff in die Körperzellen: den Bauplan für ein Virusprotein, das die Zellen vorübergehend selbst herstellen, oder etwas, das ins Erbgut eingebaut wird?","Wie gut schützt die Impfung vor schweren Verläufen der Krankheit: deutlich besser als keine Impfung, oder kaum anders als ein Scheinpräparat in einer Vergleichsstudie?","Wie lange hält der Schutz nach der Impfung an: nur wenige Monate, sodass regelmäßige Auffrischungen nötig wären, oder viele Jahre ohne weitere Dosis?","Gibt es gegen dieselbe Krankheit auch Impfstoffe ohne mRNA, die er stattdessen nehmen könnte, oder ist der mRNA-Impfstoff die einzige Möglichkeit?"],"correctIndex":0,"explanation":"Die Sorge hängt an einer Sachfrage: Was bringt der Impfstoff in die Zelle, und was geschieht damit? mRNA ist eine Arbeitsanweisung für die Herstellung eines Proteins. Die Körperzellen bauen daraufhin ein Oberflächenprotein des Virus, das dem Immunsystem als „Fahndungsfoto“ dient. Das vorübergehende Ablesen eines Bauplans ist etwas ganz anderes als ein Eingriff ins Erbgut, und Fachleute sehen übereinstimmend keine Gefahr für das menschliche Erbgut. Wer so nachfragt, prüft die Behauptung an ihrem Mechanismus. Die Frage nach dem Schutz vor schweren Verläufen ist sinnvoll, sagt aber nichts darüber, was im Körper mit dem Erbgut geschieht. Auch die Dauer des Schutzes betrifft eine andere Frage als die nach einem Eingriff ins Erbgut. Und ob es Alternativen ohne mRNA gibt, umgeht die Befürchtung, statt sie zu prüfen.","coreRule":"⚡ Prüfe eine Befürchtung zuerst am behaupteten Mechanismus: Was passiert in der Zelle tatsächlich? mRNA liefert den Bauplan für ein Protein, nicht für Veränderungen am Erbgut.","beleg":"Werkstück C.4.2 (Anwendung & Relevanz, „In der Impfdebatte“); Fn. gl-c-mrna (Kuhrt/Oude-Aost/Betsch 2021, Fakten-Check Impfen; Verweis auf Band II, Sektion II.3.2)","status":"entwurf","scenario":"Im Gespräch über die Corona-Impfung äußert ein Bekannter seine Sorge, ein mRNA-Impfstoff greife ins Erbgut ein.","kurz":"Die Befürchtung hängt an einer Sachfrage: Was gelangt in die Zelle und was geschieht dort damit? mRNA ist nur eine vorübergehend abgelesene Bauanleitung für ein Protein, kein Eingriff ins Erbgut. Wirksamkeit, Schutzdauer oder Alternativen beantworten das nicht.","prueffrage":"Welche Untersuchungen gibt es dazu, ob Geimpfte ein verändertes Erbgut haben, und was zeigen sie?","rueckmeldung":[{"option":1,"text":"Wie gut die Impfung schützt, ist eine berechtigte Frage, nur eine andere als die des Bekannten. Ob ein Impfstoff schwere Verläufe verhindert, sagt nichts darüber, was in der Zelle mit dem Erbgut geschieht."},{"option":2,"text":"Wie lange der Schutz anhält, ist für die Entscheidung durchaus relevant. Mit der Sorge um das Erbgut hat es aber nichts zu tun, denn die Dauer sagt nichts darüber, ob etwas ins Erbgut eingreift."},{"option":3,"text":"Alternativen anzusprechen kann praktisch hilfreich sein, geht aber an der Sorge vorbei. Die Befürchtung bleibt dann einfach stehen, statt dass jemand nachsieht, ob sie überhaupt zutrifft."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"CDC: How COVID-19 vaccines work (Seite zur Funktionsweise der mRNA-Impfstoffe)","oeffentlich":true,"url":"https://www.cdc.gov/covid/vaccines/how-they-work.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kuhrt, Oude-Aost & Betsch 2021, Fakten-Check Impfen, Gräfe und Unzer (E-Book ohne Seitenzahlen)","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"54eb58d2ef7a66f9"}}]`);export{t as n,n as t};